/* ÇEVİRİ zh · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("zh","olay",{
"OLAYLAR_EK4:1839-07-14:0":{"b": ["舰队交给亚历山大", "a53e6103"], "d": ["海军大臣艾哈迈德·费夫齐帕夏怀疑大维齐尔科贾·胡斯雷夫帕夏要把舰队交给俄国，遂把舰队开往亚历山大，交给穆罕默德·阿里。奥斯曼国家在同一个月内陷入无军、无苏丹、无舰队的境地。", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["大国联合照会", "2a3b8316"], "d": ["五国向奥斯曼朝廷递交照会，要求其在埃及问题上不得单独达成协议。一个内部问题由此正式变成了“欧洲问题”；奥斯曼国家事实上失去了对自己行省作出决定的权力。", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["《伦敦条约》：四国站在奥斯曼一边", "a517f775"], "d": ["将法国排除在外而签署的条约向穆罕默德·阿里发出最后通牒：十日内接受，则得埃及世袭总督之位及终身担任阿克总督；二十日内接受，则仅得埃及；拒绝，则一无所得。总督拒绝了。", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["炮击贝鲁特与盟军登陆", "0905ce92"], "d": ["英奥舰队炮击贝鲁特；武器被分发给黎巴嫩山区起来反抗埃及统治的民众。易卜拉欣帕夏在叙利亚的控制在内部叛乱与外部干预之间崩溃。", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["贝鲁特和沿海城市丧失", "09bdaf23"], "d": ["在巴勒贝克方向的交战之后，埃及军队自海岸撤退。地图上，黎巴嫩海岸脱离藩属色，回到奥斯曼直接管理。", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["阿克两小时陷落", "5aec21f0"], "d": ["在盟国舰队的炮击中，要塞的军火库爆炸，阿克数小时内投降。八年前易卜拉欣帕夏花了六个月才攻下的这座要塞，显示了海军炮兵的优势。", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["《亚历山大公约》", "85cb47b0"], "d": ["穆罕默德·阿里同意放弃叙利亚、阿达纳、克里特和汉志，归还奥斯曼舰队，并承认苏丹的宗主权；作为回报，埃及的世袭总督之位得到保证。", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["埃及军队撤出叙利亚与奇里乞亚平原", "719a28dc"], "d": ["持续九年的占领结束；易卜拉欣帕夏的军队经西奈返回埃及。地图上，自阿勒颇至加沙、自阿达纳至克里特的广阔地带重新转入奥斯曼直接管理。同日丧失的其他定居点：乌尔法、马拉什、塔尔苏斯、安条克、干地亚（克里特）、哈马、大马士革、耶路撒冷、雅法、纳布卢斯。", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["敕令：埃及总督之位留给卡瓦拉家族世袭", "87b89ff8"], "d": ["苏丹敕令承认总督之位在王朝内部由父传子；作为回报，军队人数被削减到一万八千，赋税归属伊斯坦布尔，铸币和缔约权被取消。埃及仍是一个行省，但已是另一王朝之国。汉志与两圣地的管理回到奥斯曼朝廷。同日由藩属层回到直属层的其他定居点：麦加、麦地那、吉达、延布。", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["《伦敦海峡公约》", "0e95a1ea"], "d": ["取代温卡尔·伊斯凯莱西条约的这一公约规定，和平时期海峡对一切战舰关闭。俄国单独获得的特权，由此变成欧洲的共同保障；海峡问题获得了国际地位。", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["易卜拉欣帕夏事实上成为埃及总督", "9e14f5d9"], "d": ["年迈并丧失心智的穆罕默德·阿里被其子易卜拉欣帕夏取代出任总督。但数月之后，1848年11月，他先于其父去世。", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["卡瓦拉的穆罕默德·阿里帕夏去世", "871310e0"], "d": ["生于卡瓦拉、在埃及建立王朝、两度使帝国濒临深渊的这位总督，八十岁去世。他创立的王朝在埃及统治到1953年；国家则看到他所开的伤口要靠欧洲干预才能弥合，遂在坦志麦特的道路上前进。", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["苏莱曼·本·库塔尔米什在艾因苏莱姆兵败身亡；安塔基亚脱离罗姆塞尔柱人", "0412dfa1"], "d": ["1084年自拜占庭手中夺取安塔基亚的苏莱曼·本·库塔尔米什，在与叙利亚塞尔柱统治者图图什进行的艾因苏莱姆之战中身亡；该城转入大塞尔柱苏丹马利克沙的控制，亚吉西扬被任命为总督。", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["马利克沙去世；安塔基亚连同亚吉西扬归属叙利亚塞尔柱人图图什", "c61da1b4"], "d": ["大塞尔柱苏丹马利克沙去世之后，国家在继承者之间被瓜分；安塔基亚总督亚吉西扬归附叙利亚的统治者图图什。", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["尼西亚向十字军投降；塞尔柱中心退至科尼亚，拜占庭开始收复西安纳托利亚", "8a4e90fa"], "d": ["十字军围攻尼西亚之后，该城于1097年6月19日向拜占庭投降；塞尔柱苏丹克尔奇·阿尔斯兰一世将中心退往内地科尼亚，而拜占庭则收复了以弗所等西安纳托利亚沿海地方。", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["克尔奇·阿尔斯兰二世从拜占庭手中夺取多利莱翁（埃斯基谢希尔）和屈塔希亚", "3ddee6c2"], "d": ["米里奥克法隆（1176年）之后，拜占庭在安纳托利亚内陆的多利莱翁和屈塔希亚城堡，在曼努埃尔晚年／去世之后的伊历576年／1180年落入克尔奇·阿尔斯兰二世之手。", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["卡拉曼奥卢·穆罕默德贝伊被任命为埃尔梅内克苏巴什，掌管伊奇伊尔", "6d62be11"], "d": ["卡拉曼奥卢·穆罕默德贝伊于伊历675年（1276年）被任命为埃尔梅内克苏巴什，并把伊奇伊尔置于自己管辖之下；埃尔梅内克成为次年将进军科尼亚的卡拉曼王朝的第一个中心。", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["埃尔图鲁尔加齐之死与奥斯曼贝伊继任侯位——索于特与多马尼奇的遗产", "395fb9fa"], "d": ["据TDV，埃尔图鲁尔加齐卒于680年（1281—82年）；该条目指出也有1288年和1289年的说法。奥斯曼贝伊从父亲那里继承的不是一座被征服的城市，而是塞尔柱苏丹把埃尔图鲁尔安置在其边地最前沿时给予的两处封赐：索于特的冬营地（耶尔鲁克）和多马尼奇的夏牧场。也就是说，侯国不是以征服遗产，而是以两处牧场封赐起步的；地图上这两个地方以“继承”而非“征服”标示。", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["西西里晚祷——安茹王朝失去西西里岛", "547db635"], "d": ["在巴勒莫复活节星期一晚祷之时爆发的反对安茹的查理一世统治的起义，使西西里岛脱离了安茹王朝。西西里王国一分为二：该岛倒向阿拉贡，而安茹王朝则在以那不勒斯为中心的大陆王国中立足。王朝在亚得里亚海与地中海的海外领地也仍隶属这一王国：自1267年起在其手中的科孚岛，以及自1270年代起所据的都拉斯，作为那不勒斯王国的一部分延续；阿尔巴尼亚海岸的发罗拉、卡尼纳和希马拉要塞也留在以那不勒斯为中心的王国中（发罗拉指挥官塔克西斯的约翰在整个1282年中抵抗拜占庭人；都拉斯、发罗拉和卡尼纳大概在1285年初转入拜占庭）。而马耳他直到1284年才落入阿拉贡人之手。", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["库拉贾希萨尔袭击——奥斯曼贝伊的首次军事行动", "79b00b14"], "d": ["TDV奥斯曼一世条目：“他在伊内格尔附近劫掠并焚烧了小库拉贾要塞（684/1285年）。”这是奥斯曼贝伊在史料中可考证日期的第一次军事行动。并未夺取永久定居点，要塞被劫掠烧毁；因此这与其说是征服，不如说是典型的边地袭击。被视为侯国军事活动的起点。", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["征服卡拉贾希萨尔——首次获得城市并控制埃斯基谢希尔", "178ae619"], "d": ["TDV奥斯曼一世条目：奥斯曼贝伊于687年（1288年）“征服卡拉贾希萨尔，占有埃斯基谢希尔”。这是侯国第一次真正获得城市；据传奥斯曼贝伊凭此成就晋升为边地的桑贾克贝伊；相传以他的名义的第一次聚礼呼图白在卡拉贾希萨尔诵读，并在此任命了第一位卡迪。TDV埃斯基谢希尔条目指出奥斯曼传统给出的日期是1291年，但其真实性存疑。", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["阿克陷落于马穆鲁克——十字军被逐出叙利亚海岸：赛伊达与贝鲁特", "3ca7a464"], "d": ["长期作为耶路撒冷十字军王国中心的阿克，被马穆鲁克苏丹马利克·阿什拉夫·哈利勒攻取，十字军在巴勒斯坦的统治终结。自阿克撤出的圣殿骑士团躲入赛伊达；马穆鲁克军队逼近时，他们放弃海上要塞逃往塞浦路斯，该城于同一个夏天落入马穆鲁克之手。自1197年起在十字军手中的贝鲁特也于1291年被大马士革总督桑贾尔·舒贾伊攻取。两个世纪的十字军存在由此从叙利亚—巴勒斯坦海岸抹去。", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["夜袭征服比莱吉克与亚尔希萨尔", "f461b0af"], "d": ["TDV比莱吉克条目：“虽然包括比莱吉克总督在内的该地区其他总督策划暗杀奥斯曼加齐，但在阴谋被察觉后，奥斯曼军队以突然袭击征服了亚尔希萨尔和比莱吉克（1299年）。”两座要塞在同一次行动、同一夜袭中被攻占。这一日期是被视为奥斯曼国家建立之年的转折点。同日并入的其他地方：伊内格尔。", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["科尤恩希萨尔（巴菲翁）之战——对拜占庭军队的第一次大捷", "584a9512"], "d": ["TDV奥斯曼一世条目：奥斯曼贝伊于1302年7月27日在巴菲翁（科尤恩希萨尔）与拜占庭军队交战并将其击败。这一胜利是使奥斯曼贝伊从地方边地贝伊升格为王朝创建者地位的转折点。战役之后，布尔萨平原进入奥斯曼控制，对伊兹尼克的封锁开始。", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["迪姆博斯大捷及随后攻取基特与乌卢巴特", "e168ab64"], "d": ["TDV奥斯曼一世条目：702年（1303年），布尔萨、凯斯泰尔、基特和阿德拉诺斯诸总督所结成的联盟在迪姆博斯隘口被击溃；敌人边战边退至隘口，凯斯泰尔总督战死沙场。胜利之后随即攻占基特和乌卢巴特要塞，切断了布尔萨的陆路联系，并收紧了对它的封锁。年轻的奥尔汗也参加了这场战斗。", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["萨卡里亚战役：攻取莱布莱比吉希萨尔、莱夫凯、梅凯杰和盖伊韦", "a51ba4d3"], "d": ["TDV奥斯曼一世条目给出了704年（1304年）萨卡里亚战役的顺序：“他来到莱布莱比吉要塞时，总督归顺……他到达莱夫凯……他抵达梅凯杰……他前往盖伊韦，占领了发现为空的要塞。”莱夫凯是萨卡里亚河谷通向比莱吉克的门户。这一次战役使沿河谷延伸的要塞链进入奥斯曼控制，封闭了伊兹尼克盆地的东翼。", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["希俄斯落入热那亚扎卡里亚家族控制", "9eebe4de"], "d": ["面对艾登奥卢侯国的威胁，拜占庭皇帝向热那亚人贝内代托·扎卡里亚求援；该岛落入其控制之下（名义上是拜占庭的附庸）。扎卡里亚的统治持续到1329年。", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["萨摩斯归入希俄斯热那亚人（扎卡里亚）的所有", "0e6f51e3"], "d": ["控制希俄斯的热那亚扎卡里亚家族，也把几乎已空无居民的萨摩斯纳入其所有（TDV：1304至1329年）。", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["征服盖伊韦隘口诸要塞：卡拉切普什、卡拉蒂金与阿卜苏", "76907c78"], "d": ["TDV奥尔汗条目：奥尔汗在705年（1305年）萨卡里亚战役中“征服了卡拉切普什（卡托伊基亚）、伊兹尼克前的卡拉蒂金、阿卜苏（希普苏：位于盖伊韦隘口）诸要塞”。这三座要塞封闭了萨卡里亚河谷与伊兹尼克盆地之间的通道，使伊兹尼克的陆路援助彻底断绝。盖伊韦隘口上的卡拉切普什和阿卜苏被安置了加齐·阿卜杜拉赫曼；该城此后只能靠饥饿攻陷。", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["阿德拉诺斯（奥尔汉内利）战役——奥斯曼贝伊的最后一次战役", "4811546c"], "d": ["TDV奥尔汗条目将1323年秋的阿德拉诺斯要塞战役记为奥斯曼贝伊最后一次战役。阿德拉诺斯总督是二十年前在迪姆博斯组成反对奥斯曼的总督联盟的成员；这次战役意味着清算那笔旧账。要塞确切的征服日期不详；行动由奥尔汗贝伊继续进行。", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["奥斯曼加齐去世与奥尔汗贝伊继任侯位", "021487cd"], "d": ["侯国以其为名的奥斯曼加齐，据阿斯波尔恰哈通与梅凯杰的捐赠文书为证，于724年（1324年）去世。自1305年起在各次战役中统率军队的其子奥尔汗，在父亲去世后未经任何王位之争即登上侯位。开创一代平稳移交旗帜，表明王朝在从边地侯国走向国家的道路上，平静地通过了第一次大考。", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["希俄斯自扎卡里亚手中收回并划归拜占庭", "f6741b26"], "d": ["皇帝安德罗尼科斯三世把扎卡里亚逐出该岛，并在贝内代托三世任总督的情况下使该岛隶属拜占庭。该岛将于1346年被热那亚人西莫内·维尼奥西占领。", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["萨摩斯自扎卡里亚归还拜占庭（希俄斯链条）", "08034974"], "d": ["随着扎卡里亚领主权的覆灭（希俄斯于1329年归属拜占庭），热那亚在萨摩斯的所有权也告终结。", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["佩勒卡农（马尔泰佩）之战与科贾埃利全境被攻取", "389e7bd4"], "d": ["TDV奥尔汗条目：战斗第一天，奥尔汗加齐为吸引拜占庭军队，派出一支三百人的部队；第二天，在帕扎尔卢指挥的部队下到平地后战斗扩大，皇帝被箭射伤后拜占庭军中出现恐慌。结果是决定性的：“奥尔汗占领了整个科贾埃利；胜利之后，伊兹尼克人再无任何希望。”从海列凯到于斯屈达尔的沿海城镇进入奥斯曼统治，盖布泽成为该地区的中心。这是为拯救君士坦丁堡而来的最后一支拜占庭帝国军队。", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["在伊兹尼克建立第一所奥斯曼经学院", "c85fb625"], "d": ["奥尔汗贝伊攻取伊兹尼克之后，立即任命昌达尔勒·卡拉·哈利勒为该地卡迪，把一座巴西利卡改为清真寺，并在其旁修建了一座施舍所和一所经学院，开始了城市建设。据TDV达乌德·开塞里条目，经学院的工程于1336年完成，奥尔汗加齐以日薪30阿克切请达乌德·开塞里担任教授。这所经学院是奥斯曼学术生活的第一个制度性步骤；侯国在征服力量之外，又增添了一种学术传统。以征服得来的拜占庭都城转变为伊斯兰学术中心，是奥斯曼定居国家抱负的第一个具体标志。", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["拜占庭被纳入贡赋——围攻伊兹米特与条约", "0c1ec8d3"], "d": ["TDV奥尔汗条目：奥尔汗于733年（1333年）夏以大军和抛石机围攻伊兹米特，皇帝同意缔约。作为他放弃围攻的回报，拜占庭同意每年向奥尔汗支付12000枚金币（海佩皮隆）；“于是在奥斯曼埃米尔眼中，拜占庭就成了纳贡之国”。作为回报，奥尔汗将成为皇帝的朋友，不攻击隶属拜占庭的城市。一个边地侯国使东罗马纳贡，宣告了力量对比已经发生了怎样的逆转。", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["萨莫色雷斯自威尼斯人转入热那亚加蒂卢西奥家族", "c499ed5f"], "d": ["热那亚的加蒂卢西奥家族把自1204年起占据该岛的威尼斯人逐出了该岛。", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["吞并卡拉西侯国：巴勒克埃西尔、贝尔加马、比加、埃德雷米特和埃尔代克", "c7cb0511"], "d": ["TDV奥尔汗条目（伊纳尔哲克）把吞并定在735年（1334—35年）：德米尔汗贝伊去世后，卡拉西的加齐们和哈吉·伊勒贝伊邀请杜尔松贝伊登位，并向奥尔汗求援。奥尔汗先向巴勒克埃西尔进军；前往和谈的杜尔松贝伊被从贝尔加马要塞射出的一箭杀死，侯国遂全部并入奥斯曼国土。在同一次行动中，基尔马斯蒂和米哈利奇归顺，居利亚尔被攻占，此前以安全保证放过的乌卢巴特被最终占领。奥尔汗任命苏莱曼帕夏为卡拉西桑贾克，并以比加为边地中心——渡往鲁米利的海上人员班底就这样获得了。注：TDV的卡拉西奥卢条目就同一事件给出746年（1345年）；该百科全书自相矛盾。同日并入的其他地方：恰纳卡莱。", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["萨摩斯归入希俄斯马奥纳的所有", "01628b2f"], "d": ["随着热那亚人西莫内·维尼奥西夺取希俄斯并把管理交给马奥纳公司，萨摩斯也归入希俄斯热那亚人（马奥纳）的所有（TDV：1346至1475年）。", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["奥尔汗加齐与热那亚人的第一份治外法权", "e64cb196"], "d": ["在威尼斯—热那亚战争期间与热那亚人达成协议的奥尔汗加齐，在1352年2月海峡海战之后，向佩拉的防御派去1000名弓箭手，并为运兵提供了60000枚金币；作为回报，他给予热那亚人第一份治外法权。条约全文未传至今日。这是奥斯曼与一个欧洲海上强国的第一份正式协议，并将于三十五年后的1387年续订。", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["攻取加利波利——在鲁米利的永久桥头堡", "ba51a160"], "d": ["1349—1352年间以坎塔库泽诺斯盟友身份熟悉其周边的加利波利，奥斯曼人于1354年攻取；摧毁该城城墙的大地震提供了机会。钦佩的狭窄桥头堡由此变成海峡鲁米利一侧的真正基地，通往色雷斯的大门被完全推开。加利波利将在1366年因萨伏依十字军而丧失，却将在1376年第二次征服后最终进入奥斯曼统治。同日并入的其他地方：基利特巴希尔。", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["鲁米利征服者苏莱曼帕夏之死", "2dc98228"], "d": ["奥尔汗贝伊的长子、鲁米利征服的缔造者苏莱曼帕夏，在史料中给出的758年（1357年）、759年和760年（1359年）诸日期中最为通行的1357年秋，于狩猎时坠马而死。凭1352—1354年间的渡海建立了奥斯曼在鲁米利永久存在的这位王子之死，使王储之位留给了其弟穆拉德。葬于博拉尔的苏莱曼帕夏陵墓，一直是奥斯曼在欧洲最古老的王朝纪念建筑。", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["彭契克法——奠定近卫军军团的基础", "e5877c2d"], "d": ["鲁米利征服之后，依乌理玛成员卡拉曼利·卡拉·鲁斯特姆的建议，规定把战俘的五分之一或相当于此的现金留归国家的彭契克制度开始施行。从这些战俘中挑选者被安置在突厥人家庭中抚养并征入军队，由此形成了直属苏丹的常备步兵力量——近卫军军团——的核心。以部落骑兵为基础的边地侯国变为拥有中央军队的国家，就由这一安排开始。", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["下到西色雷斯：征服古梅尔吉纳", "9ef69221"], "d": ["攻取埃迪尔内之后转向马里查河以西的边地部队，在加齐埃夫雷诺斯贝伊指挥下夺取了西色雷斯的中心古梅尔吉纳。该城成为埃夫雷诺斯贝伊把袭击推向马其顿的前进大本营。色雷斯延伸至爱琴海岸的部分由此进入奥斯曼控制，通往塞萨洛尼基之路打开。", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["瓦尔纳并入多布罗加公国并成为首都", "2bfe73f9"], "d": ["保加利亚沙皇国解体过程中，黑海沿岸的瓦尔纳并入多布罗蒂奇所建的多布罗加公国，并成为这个小国的首都。", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["菲利波波利斯以西：塔塔尔帕扎尔奇克与伊赫蒂曼并入", "1664d0e1"], "d": ["1372年攻取菲利波波利斯之后，马里查河谷上端的塔塔尔帕扎尔奇克，以及扼守通往索非亚隘口的伊赫蒂曼，归入奥斯曼管理。这一由切尔诺门之战后成为藩属的地方诸侯控制的地带，被改为直接统治，使菲利波波利斯—索非亚一线畅通无阻。这一推进，是十二年后征服索非亚之路的准备。", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["萨夫吉贝伊叛乱——王子与拜占庭王储的联合反叛", "75198c33"], "d": ["穆拉德一世之子萨夫吉贝伊与拜占庭皇帝约翰五世之子安德洛尼卡·帕列奥列格，于1373年5月初在布尔萨和君士坦丁堡同时起兵反对各自的父亲。这个联合两个王朝王储的同盟很快被镇压；萨夫吉贝伊被擒，被烙瞎双眼并处死。奥斯曼传说给出的叛乱日期787年（1385年）有误；事件紧接在拜占庭成为奥斯曼藩属之后的几年，显示出两座宫廷纠缠得多么紧密。", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["斯特鲁马与梅斯塔河谷：科斯滕迪尔、佩特里奇、涅夫罗科普与德拉马并入", "8c0980c4"], "d": ["切尔诺门大捷之后开始向奥斯曼纳贡的塞尔维亚和保加利亚地方诸侯控制的斯特鲁马与梅斯塔河谷，随着边地贝伊们的推进被纳入奥斯曼直接管理。随着科斯滕迪尔、佩特里奇、涅夫罗科普和德拉马的并入，马其顿东半部洞开，塞萨洛尼基与塞雷进入包围圈。地图上鲁米利向西南的扩展，即这次行动的结果。", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["帖木儿攻取赫拉特：克尔特王朝的终结与呼罗珊归入帖木儿", "15f6019e"], "d": ["1380年的呼罗珊在萨尔巴达尔王朝、克尔特王朝与穆扎法尔王朝的争斗中四分五裂。帖木儿先派其子米兰沙赫前往该地，随后亲自向赫拉特进军，围攻一段时间后，从克尔特王加亚斯丁·皮尔·阿里手中接收了该城。他离开之后爆发的叛乱被米兰沙赫血腥镇压，自1255年起在赫拉特统治的克尔特王朝终结。从马什哈德到内沙布尔的整个呼罗珊，在这一日期进入帖木儿统治。", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["埃雷特纳侯国终结与卡迪·布尔汉丁国家建立", "60dcaf57"], "d": ["1335年源于伊儿汗总督之职、以锡瓦斯和开塞利为中心统治中安纳托利亚四十六年的埃雷特纳奥卢，在宫廷内部的争斗中瓦解。1378年5月出任维齐尔的卡迪·布尔汉丁，在除掉对手克勒奇阿尔斯兰和哈吉·沙德盖尔迪之后，于1381年秋宣布称苏丹，终结了侯国，建立了以自己之名为称的国家。奥斯曼东邻由此易主；锡瓦斯—开塞利一线此后十七年留在卡迪·布尔汉丁手中。", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["向马其顿腹地推进：征服马纳斯提尔与奥赫里德", "63bb7838"], "d": ["埃格纳提亚大道上的马纳斯提尔和湖畔的奥赫里德，在向阿尔巴尼亚方向的袭击中进入奥斯曼管理。二者都是通往亚得里亚海之路的关键点；奥赫里德还是巴尔干最古老的东正教大主教驻地。TDV指出，奥赫里德的征服日期没有确切信息，有787年（1385年）以及克拉列维奇·马尔科去世后的797年（1395年）等说法；此处采用1385年。马纳斯提尔在此后的世纪里将成为鲁米利最重要的军事中心之一。", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["萨乌拉之战——阿尔巴尼亚之门被打开", "dda6671b"], "d": ["在被巴尔沙家族逼得走投无路的阿尔巴尼亚贝伊卡尔洛·托皮亚求援之下，奥斯曼军队在萨乌拉平原击溃了巴尔沙二世的军队；巴尔沙阵亡于战场。应一位当地贝伊之邀而进入的这场战争，使奥斯曼人在延伸至亚得里亚海岸的阿尔巴尼亚土地上获得了第一个持久影响。利用该地区诸贝伊相互失和的这一政策，将在此后一个世纪里成为巴尔干征服不变的方法。", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["帖木儿的“三年战役”：攻取阿塞拜疆与伊朗北部", "2a98ec51"], "d": ["在呼罗珊战役期间近距离目睹伊朗分裂状态的帖木儿，于788年（1386年）向西进军。在被称为“三年战役”的1386—1388年行动中，他经马赞德兰、卢里斯坦和格鲁吉亚进入阿塞拜疆并抵达卡拉巴赫；大不里士、阿尔达比勒、乌尔米耶和纳希切万进入帖木儿统治。他夺取伊朗北部与阿塞拜疆，如同当年术赤兀鲁思与伊儿汗国之间一样，也成为与金帐汗国长期争夺的开端。", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["弗伦克亚济斯之战与围攻科尼亚——第一次卡拉曼战役", "af4e5d77"], "d": ["针对虽为女婿却对奥斯曼在西安纳托利亚的扩张感到不安的卡拉曼奥卢阿拉丁·阿里贝伊，穆拉德一世亲自出征；在名为弗伦克亚济斯之处进行的战斗中，训练有素、经验丰富的奥斯曼军队击败了卡拉曼军队。随后科尼亚要塞被围，但由于阿拉丁贝伊获赦，侯国并未被彻底消灭。这次战役是奥斯曼与卡拉曼之间将持续一个世纪、直到1468年最终吞并才告结束的长期清算的开幕。", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["穆什自黑羊王朝统治转入帖木儿统治（789/1387）", "ed2e7a11"], "d": ["蒙古时代之后转入黑羊王朝统治的穆什，于789年（1387年）归入占有黑羊王朝领土的帖木儿的统治之下。在地图集中，穆什于这一年由黑羊王朝记为帖木儿王朝。", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["建立加利波利船坞——奥斯曼海军的诞生", "47546241"], "d": ["奥斯曼国家第一座成体系的船坞，于1390年由雷霆巴耶塞特在加利波利、拜占庭遗留的船坞旧址上建立。继承西安纳托利亚诸侯国航海遗产的奥斯曼，由此第一次成为自造船只的海上力量。坐落在恰纳卡莱海峡要冲的这座船坞，自围攻君士坦丁堡至爱琴海远征，一个半世纪里一直是奥斯曼舰队的主要基地。", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["哈米德地区并入奥斯曼：伊斯帕尔塔、布尔杜尔、乌卢博尔卢、埃伊尔迪尔", "e3da7de5"], "d": ["卡拉曼奥卢阿拉埃丁贝伊进攻哈米德地区、居民申诉之后出征的雷霆巴耶塞特，夺取了哈米德奥卢家族剩余的全部领土，并把管理权交给其子伊萨·切莱比。", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["穆扎法尔王朝的终结：沙赫·曼苏尔在设拉子前战败", "5fd14eb8"], "d": ["自1318年起统治亚兹德、法尔斯、伊斯法罕和克尔曼的穆扎法尔王朝的最后一位强势君主沙赫·曼苏尔，联合亲族起而对抗帖木儿。在设拉子附近的战斗中，因其一名埃米尔倒向对方而损失大部分兵力，兵败被杀。帖木儿随后又下令处死了王朝全体成员，穆扎法尔统治就此终结，法尔斯与克尔曼并入帖木儿统治。", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["阿马西亚并入奥斯曼领土", "fe2860cf"], "d": ["在雷霆巴耶塞特的中安纳托利亚战役中被围的阿马西亚埃米尔把城交给奥斯曼人，巴耶塞特于1393年进入该城。苏丹把此地的管理留给其子穆罕默德·切莱比；作为王子桑贾克，阿马西亚此后成为奥斯曼王室最重要的教育场所之一。这一选择将在日后的空位时期起决定性作用，切莱比穆罕默德正是以这个阿马西亚为根基，展开重新统一国家的斗争。", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["帖木儿攻占巴格达——杰拉伊尔王朝逃往安纳托利亚", "4d5602b3"], "d": ["帖木儿在长期围攻之后攻占巴格达；该城统治者杰拉伊尔苏丹艾哈迈德向西逃走，先投奔马穆鲁克，后寄身于奥斯曼宫廷。帖木儿向西扩张由此首次与奥斯曼势力范围直接接触。两位君主之间仇隙的第一环自此开始。", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["攻取黑海岸的瓦尔纳", "a84b2abf"], "d": ["在保加利亚沙皇国位于多瑙河与黑海之间的领土被压缩之际，沿岸最大的港口瓦尔纳转入奥斯曼管理。港口的攻取为向多布罗加方向推进扫清了道路，并使奥斯曼获得了黑海西岸第一个大码头。瓦尔纳也将在五十一年后成为十字军大军被歼的1444年之战的舞台。", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["内夫谢希尔与于尔居普地区从卡拉曼王朝转入奥斯曼之手", "06ff59e8"], "d": ["在雷霆巴耶塞特对卡拉曼王朝的战事中，内夫谢希尔（穆什卡拉）和于尔居普地区于伊历800年／1398年归入奥斯曼统治；1402年安卡拉战役之后，帖木儿把该地区归还给卡拉曼王朝。", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["卡迪·布尔汉丁国家的覆灭", "b13391e3"], "d": ["被白羊王朝君主卡拉尤吕克·奥斯曼贝伊俘虏的卡迪·布尔汉丁，虽提出以交出锡瓦斯换取获释，城中居民仍加抵抗，苏丹在城墙前被处决。锡瓦斯的显贵们虽拥立其子阿拉丁·阿里·切莱比，但面对白羊王朝的压力，他们向雷霆巴耶塞特求援；苏莱曼·切莱比统率的奥斯曼军队击败卡拉尤吕克并控制该城。卡迪·布尔汉丁国家由此成为历史，锡瓦斯、托卡特、尼克萨尔与开塞利并入奥斯曼领土。同日并入的其他地方：克尔谢希尔、乔鲁姆。", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["帖木儿的逼迫：拒绝引渡逃亡者", "33790bc8"], "d": ["在帖木儿的压力下，杰拉伊尔苏丹艾哈迈德与黑羊王朝首领卡拉·优素福投靠奥斯曼领土；帖木儿要求引渡这两名逃亡者，雷霆巴耶塞特拒绝。于是两位君主之间开始互通充满相互侮辱的书信。战争的意识形态基础，是在一兵一卒尚未出动之前，就以这些书信建立起来的。", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["布尔萨的雷霆医院——第一所奥斯曼医院", "5f0dc59a"], "d": ["雷霆巴耶塞特在布尔萨建造宏伟大清真寺的那些年，也为该城增设了一所医院；这是由施舍所、经学院、客栈和桥梁构成的广泛慈善工程中划给医学的一环。作为国家建立的第一所医院，这座建筑也兼具培养医生的医学校的功能，奠定了奥斯曼卫生机构的模式。在安卡拉惨败前仅两年竣工的这一建筑，是雷霆把布尔萨变为帝国都城之设想的最后环节之一。", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["帖木儿夷平锡瓦斯", "f4d79de6"], "d": ["在白羊王朝的卡拉尤吕克·奥斯曼贝伊和埃尔津詹埃米尔穆塔哈尔滕的引导下向锡瓦斯进军的帖木儿，围城十八天，在许诺不流任何人血之后接收了该城，随即进行了大屠杀；他下令把守军填入壕沟，活活掩埋。以城墙为首的城市重要建筑被毁，锡瓦斯在人口上崩溃。这是安卡拉战役前两年帖木儿对奥斯曼领土的第一次重大打击。", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["雷霆巴耶塞特收复埃尔津詹与凯马赫", "7047ca08"], "d": ["趁帖木儿出征叙利亚之机，雷霆巴耶塞特从隶属帖木儿的埃尔津詹埃米尔穆塔哈尔滕手中夺取了埃尔津詹与凯马赫。尽管他没有干预锡瓦斯的毁灭，这一举动仍意味着对帖木儿在东安纳托利亚势力范围的直接挑战。两位君主之间此后再无法修复。", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["帖木儿从大不里士发出的最后通牒——四项条件", "3e1ac50e"], "d": ["帖木儿通过自大不里士派出的使者提出四项条件：把凯马赫归还穆塔哈尔滕；把从安纳托利亚诸侯手中夺取的土地归还其主人；派一名奥斯曼王子作人质，并接受帽子与腰带作为臣服的标志；交出卡拉·优素福。巴耶塞特一条也未接受；尽管国务要员坚持并有穆塔哈尔滕的斡旋，谈判仍告破裂。帖木儿决心在出征中国之前彻底了结安纳托利亚问题。", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["萨鲁汗侯国重建——马尼萨脱离奥斯曼", "ac747b05"], "d": ["安卡拉溃败三周后，在帖木儿的支持下奥尔汗贝伊登上侯国之位，萨鲁汗地区重新独立。以马尼萨为中心的这一地区，在1390年被奥斯曼吞并十二年后，从地图上消失。这是帖木儿复兴侯国政策中日期确知的最早实例之一。", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["埃米尔苏莱曼携国库逃往鲁米利", "0a2b7363"], "d": ["带着布尔萨的国库、档案、家人和兄弟们的埃米尔苏莱曼，自盖姆利克乘船渡至居泽尔杰希萨尔（安纳托利亚要塞），由此抵达加利波利，并在埃迪尔内宣布称君主。国家档案与国库迁往鲁米利，是奥斯曼重心在一代人时间里移向巴尔干的开端。地图上，鲁米利自这一日期起以埃米尔苏莱曼自己的颜色绘制。", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["帖木儿重建安纳托利亚诸侯国——突厥统一瓦解", "15187774"], "d": ["安卡拉大捷之后，帖木儿把随行的诸侯送还其旧地。卡拉曼奥卢穆罕默德与阿里诸贝伊得卡拉曼地区及开塞利、克尔谢希尔、锡夫里希萨尔和贝伊谢希尔；杰尔米扬奥卢雅各布二世贝伊得屈塔希亚和杰尔米扬地区；坎达尔奥卢伊斯凡迪亚尔贝伊除卡斯塔莫努—锡诺普一线外又得昌克勒和卡莱吉克。艾登、门泰谢和特凯诸地也回到旧王朝手中。雷霆巴耶塞特十年间建立的安纳托利亚突厥统一，在一个夏天里瓦解；地图上这些侯国重新以各自的颜色出现。", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["帖木儿自圣约翰骑士团手中夺取伊兹密尔", "66dd1dd4"], "d": ["经屈塔希亚、代尼兹利、艾登、阿亚苏卢克和蒂雷向西而下的帖木儿，围攻并夺取了自1344年起在基督徒手中的沿海城市伊兹密尔。雷霆巴耶塞特多年未能攻下的这座要塞，被帖木儿在短期内攻克，在占领周边要塞之后，他把艾登地区留给旧主人并转向东方。该城此后进入艾登奥卢居奈德贝伊的管辖。", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["伊萨·切莱比占领布尔萨——安纳托利亚一份领地产生", "955128c1"], "d": ["安卡拉溃败之后退往卡拉西一带的伊萨·切莱比，在帖木儿身处伊兹密尔时占领了布尔萨。他在被帖木儿士兵劫掠焚烧的旧都宣布称君主，并以自己的名义铸造钱币；1403年1月，他在安纳托利亚已以“突厥人的君主”身份被承认。地图上，沿马尔马拉海亚洲海岸延伸的这份领地，以伊萨·切莱比自己的颜色显示。", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["帖木儿撤出安纳托利亚", "93a98839"], "d": ["得知雷霆巴耶塞特在阿克谢希尔去世的消息后，帖木儿认为自己在安纳托利亚的事务已毕，转向东方。身后留下表示臣服的诸侯国，以及彼此失和的奥斯曼王子们；锡瓦斯等一些城市被留给隶属帖木儿的穆济德贝伊等埃米尔。帖木儿没有再回安纳托利亚，但他建立的这种分裂格局持续了十年。", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["埃米尔苏莱曼渡往安纳托利亚：布尔萨落入其手", "9b27aa5f"], "d": ["听闻伊萨·切莱比失败的埃米尔苏莱曼，与昌达尔勒·阿里帕夏一起率强大军队渡往安纳托利亚并占领布尔萨；1404年3月的记录显示黑海埃雷利也在他的管辖之下。短时间内同时统治鲁米利和安纳托利亚大部分地区的苏莱曼，使切莱比穆罕默德无法抵抗。地图上，自这一日期到切莱比穆罕默德重新攻取布尔萨（1410年），两岸以同一颜色，即埃米尔苏莱曼的领地显示。", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["耶尼谢希尔平原之战——切莱比穆罕默德退往阿马西亚", "f1568288"], "d": ["失去布尔萨和安卡拉的切莱比穆罕默德，在耶尼谢希尔平原败于埃米尔苏莱曼，丧失了在西安纳托利亚的所有所得，退回托卡特—阿马西亚根据地。此次失败后他避免直接冲突，转而在安纳托利亚腹地巩固权威。空位时期最长的沉寂阶段就这样开始了。", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["埃米尔苏莱曼自切莱比穆罕默德手中夺取安卡拉", "d6a2acd6"], "d": ["帖木儿撤出安纳托利亚后，留在切莱比穆罕默德手中的安卡拉，于1406年被埃米尔苏莱曼围攻。要塞守将雅各布贝伊支持了一段时间，但经大维齐尔昌达尔勒·阿里帕夏的一个计谋，把要塞交给了苏莱曼。于是切莱比穆罕默德与卡拉曼奥卢穆罕默德贝伊结盟，对苏莱曼采取行动。", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["切莱比穆罕默德自帖木儿系的穆济德贝伊手中收复锡瓦斯", "90079b0c"], "d": ["帖木儿入侵之后，锡瓦斯的管理被留给隶属帖木儿的穆济德贝伊。阿马西亚的切莱比穆罕默德派其统帅巴耶塞特帕夏去攻取该城，经激烈抵抗后，锡瓦斯第二次落入奥斯曼王室之手。穆罕默德的领地由此在安卡拉战役六年之后，在东方达到旧有边界。", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["阿图格王朝的终结：马尔丁交给黑羊王朝", "15b06f33"], "d": ["自1106年起在马尔丁统治、属王朝最长寿一支的阿图格人，在白羊王朝的压力下无法立足。意识到无力守城的马利克·艾哈迈德，与黑羊王朝君主卡拉·优素福达成协议，把马尔丁交给了他。三个多世纪的阿图格统治由此终结；马尔丁及其周边在一个世纪后转入奥斯曼之前，一直是黑羊—白羊争斗的舞台。", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["扬博尔之战——穆萨·切莱比进入埃迪尔内", "8f978408"], "d": ["经瓦拉几亚渡往鲁米利的穆萨·切莱比，在瓦拉几亚和塞尔维亚的支持下于扬博尔击溃埃米尔苏莱曼的军队并进入埃迪尔内。空位时期中，鲁米利首次脱离埃米尔苏莱曼之手。但他的统治并不持久；四个月后他将在科斯米迪翁败北并退入巴尔干腹地。", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["因杰伊兹之战——切莱比穆罕默德在鲁米利的首次失败", "3c35cd43"], "d": ["乘拜占庭船只渡往鲁米利的切莱比穆罕默德，在因杰伊兹与穆萨·切莱比交战；穆萨以麾下七千近卫军击败穆罕默德，穆罕默德被迫返回安纳托利亚。这次失败使穆罕默德转向不是直接作战，而是争取鲁米利边地诸侯和塞尔维亚专制公国的策略。九个月后查姆尔鲁大捷的基础，正是以这种外交准备的。", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["围攻科尼亚与同卡拉曼奥卢的条约——哈米德地区、赛义德地区、贝伊谢希尔、塞伊迪谢希尔和阿克谢希尔被收回", "0996257e"], "d": ["针对空位时期进攻奥斯曼领土并围攻、焚烧布尔萨的卡拉曼奥卢，切莱比穆罕默德发动大规模远征，于穆哈兰姆818年围攻科尼亚。卡拉曼奥卢穆罕默德二世贝伊被迫求和；条约结果是，哈米德地区（伊斯帕尔塔一带）和赛义德地区重新并入奥斯曼领土，贝伊谢希尔、塞伊迪谢希尔和阿克谢希尔也被归还；帖木儿1402年给予卡拉曼奥卢的锡夫里希萨尔也回到奥斯曼手中。因安卡拉战役而瓦解的安纳托利亚统一开始被缝合的这次远征，是切莱比穆罕默德被视为“第二位创建者”的具体理由之一。", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["自艾登奥卢居奈德贝伊手中夺取伊兹密尔", "2377ca51"], "d": ["空位时期不断在王子之间改换阵营的艾登奥卢居奈德贝伊的中心伊兹密尔，经十天围攻被切莱比穆罕默德攻取；居奈德获赦并被派往尼科波利斯桑贾克贝伊之职。帖木儿1402年归还给艾登奥卢的这座城，由此在十三年后回到奥斯曼。居奈德将于1422年重新夺取该城，问题直到1424—1426年才由穆拉德二世了结。", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["处决托尔拉克·凯末尔——萨鲁汗最终归奥斯曼", "8a09dbf1"], "d": ["领导贝德雷丁谢赫运动在西安纳托利亚一翼的托尔拉克·凯末尔，在马尼萨一带被击败并处决。此后萨鲁汗地区最终进入奥斯曼控制，帖木儿1402年复兴的侯国成为历史。空位时期在西安纳托利亚最后的政治残余就这样被清除。", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["征服发罗拉、培拉特与卡尼纳", "1e1949b8"], "d": ["奥斯曼人于1417年把亚得里亚海岸的发罗拉连同内陆的培拉特城和卡尼纳要塞一并纳入统治。一年后威尼斯夺回该城的尝试告败，在此建立了桑贾克组织，奥斯曼权威遂得持久。发罗拉的攻取使奥斯曼首次直接拥有亚得里亚海的一个港口，面对意大利获得了一个海外跳板。", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["收复中安纳托利亚：开塞利与克尔谢希尔", "204eacb3"], "d": ["空位时期落入卡拉曼奥卢之手的中安纳托利亚城市，在切莱比穆罕默德重整国家的战役中重回奥斯曼管理。随着开塞利与克尔谢希尔并入，在安卡拉战役中丧失的克泽尔河流域大体得以收复。这一推进是四年前以围攻科尼亚开始的东向政策的延续。", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["马穆鲁克把开塞利交给杜尔卡迪尔的纳西鲁丁·穆罕默德", "aad4b00c"], "d": ["出征卡拉曼奥卢穆罕默德贝伊的马穆鲁克军队占领开塞利；马穆鲁克统帅把该城及其周边留给杜尔卡迪尔的纳西鲁丁·穆罕默德后返回本国。", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["穆罕默德一世去世与穆拉德二世登基", "98acac77"], "d": ["结束空位时代并使奥斯曼国土重新统一于一人之手的穆罕默德一世，于1421年6月25日在埃迪尔内去世，其子穆拉德在布尔萨登基。根据他去世前与拜占庭作出的安排，年幼的儿子们应作为人质送到皇帝处，而皇帝将不释放其手中的王位觊觎者穆斯塔法·切莱比；穆拉德二世拒绝将其兄弟送给皇帝。", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["最终清除特凯奥卢：攻取安塔利亚", "e65565b2"], "d": ["安卡拉战役之后因帖木儿复兴而重建的特凯奥卢侯国，随着哈姆扎贝伊统率的奥斯曼军队围攻安塔利亚而告终；侯国最后一位重要人物奥斯曼·切莱比被除掉。地中海沿岸的特凯地区由此在二十一年分离之后最终并入奥斯曼。该侯国作为从哈米德奥卢分出的一支，自1321年起一直在安塔利亚统治。", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["图拉汉贝伊远征摩里亚与六里长城被毁", "c6c2706d"], "d": ["因拜占庭支持敌对的王位觊觎者穆斯塔法·切莱比，穆拉德二世派图拉汉贝伊进攻摩里亚。图拉汉贝伊拆毁了自头至尾封闭科林斯地峡的六里长城，进入半岛并造成大规模破坏。和平以不得再重建城墙和缴纳年税为条件达成；摩里亚专制公国由此在军事上失去防御，为1460年的最终征服提前三十七年做好了准备。", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["阿索斯（圣山）修道院进入奥斯曼庇护", "562de5ea"], "d": ["在塞萨洛尼基被围的那些年里，哈尔基季基半岛东侧的阿索斯修道院共和国向穆拉德二世求取庇护，并接受了奥斯曼的统治。僧侣的财产权与礼拜权得到保证；修道院以纳税为代价，在内部事务上保持自由。这一安排成为奥斯曼与东正教机构所建庇护关系中最长久的范例，持续了五个世纪。", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["吞并塔杰丁奥卢侯国：尼克萨尔", "370ffd47"], "d": ["在阿马西亚总督约尔居奇帕夏的压力下，塔杰丁奥卢侯胡萨梅丁·哈桑贝伊于830年（1427年）交出了以尼克萨尔为中心的国土钥匙；他得到鲁米利的一个桑贾克。建立于十四世纪下半叶、疆界时而延伸到凯尔基特、阿马西亚、萨姆松、奥尔杜和吉雷松的侯国就此终结。同一年，属于哈吉埃米尔奥卢的领土也被登记入册并划归贾尼克桑贾克；中黑海诸侯国的时代结束。", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["贝尔格莱德让给匈牙利——《陶陶条约》", "62481183"], "d": ["塞尔维亚专制君主斯特凡·拉扎列维奇去世后，根据匈牙利国王西吉斯蒙德与其继承人格奥尔格·布兰科维奇之间签订的《陶陶条约》，贝尔格莱德城堡被移交给匈牙利。位于多瑙河与萨瓦河交汇处的这座城堡，此前一直在塞尔维亚专制公国手中，是奥斯曼通往中欧之门的锁钥。这一移交使贝尔格莱德在一百年间成为奥斯曼推进道路上最坚固的障碍：1440年和1456年的围攻均告失败，城堡直到1521年才陷落。", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["马尔丁由黑羊王朝守军转入白羊王朝卡拉尤吕克·奥斯曼贝伊", "d82bc97f"], "d": ["卡拉·优素福1409年攻取的马尔丁，由黑羊王朝以总督管理；被留下守城的埃米尔纳西尔于835年（1432年）把该城交给白羊王朝的卡拉尤吕克·奥斯曼贝伊。白羊王朝的统治持续到十六世纪初。", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["卡拉曼奥卢自杜尔卡迪尔手中夺取开塞利", "2b09e8e8"], "d": ["卡拉曼侯凭借对杜尔卡迪尔取得的胜利，把开塞利、于尔居普、代韦利卡拉希萨尔和乌奇希萨尔并入自己的国土。", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["布丘克泰佩事件——第一次近卫军叛乱与穆拉德二世重返王位", "6388dda1"], "d": ["在埃迪尔内爆发、史上已知的第一次近卫军叛乱布丘克泰佩事件，因要求提高半枚阿克切的军饷而起，结果是年轻的穆罕默德二世被废。穆拉德二世于850年萨法尔月8日从马尼萨匆匆启程，开始了第二次统治。这一事件是“苏丹奴仆”军团已成为在王位上有话语权的力量的第一个迹象，并塑造了征服者此后终生对近卫军的戒备。", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["并入伊庇鲁斯海岸：阿尔塔与普雷韦扎", "796f7ecf"], "d": ["在约阿尼纳于1430年投降十九年之后，伊庇鲁斯专制公国沿海地区的阿尔塔与普雷韦扎也进入奥斯曼管理。通向爱奥尼亚海的安布拉基亚湾由此被控制，约阿尼纳的出海联系完成。普雷韦扎是九十年后将因巴巴罗萨载入史册的胜利而得名的海湾要地。", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["穆拉德二世去世与穆罕默德二世第二次登基", "8f8256ad"], "d": ["在其子的婚礼之后患病的穆拉德二世，于855年穆哈兰姆月1日（1451年2月3日）在埃迪尔内去世。十九岁的穆罕默德二世于855年穆哈兰姆月16日（1451年2月18日）第二次登上奥斯曼王位——这一次是永久的。五年前在布丘克泰佩被废黜的年轻君主的回归，是两年后以征服君士坦丁堡加冕、并把奥斯曼侯国变为世界帝国的统治的开端。", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["奥斯曼—克里米亚联军第一次围攻卡法", "e346d163"], "d": ["1454年6月与征服者穆罕默德苏丹达成协议的克里米亚汗哈吉·吉莱，以七千骑兵自陆路围攻卡法；一支五六十艘桨帆船的奥斯曼舰队也在海面上布阵。热那亚人的卡法以缴纳贡赋解除了围攻，最终征服被推迟到二十一年后的1475年。这次首次联合行动，是奥斯曼—克里米亚军事合作的第一个范例，日后将在最终征服卡法时重演。", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["攻取爱琴海北部诸岛：博兹贾岛、伊姆罗兹与萨索斯", "76575895"], "d": ["君士坦丁堡的征服之后不久，征服者穆罕默德苏丹为保障新都的海路，转向恰纳卡莱海峡爱琴海口的诸岛；博兹贾岛和伊姆罗兹自拜占庭手中，萨索斯自热那亚裔的加蒂卢西奥家族手中夺取。封锁海峡两岸的这些岛屿，此后成为伊斯坦布尔粮食供给与防御线的第一环。由于教廷与威尼斯舰队的干预，统治一时反复，直到1459年才最终确定。", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["征服科索沃：攻取普里什蒂纳与新帕扎尔", "d7ed2345"], "d": ["向塞尔维亚专制公国进军的奥斯曼军队，夺取科索沃平原上的普里什蒂纳和拉什卡地区的中心新帕扎尔；同一战役中还攻占了以银矿闻名的诺沃布尔多。塞尔维亚南半部由此直接并入奥斯曼管理，斯梅代雷沃的专制公国被与其中心领土割裂。这一征服是通向四年后完全吞并塞尔维亚的决定性一步。", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["伊佩克（佩奇）进入奥斯曼管理——杜卡金桑贾克的中心之一", "19511588"], "d": ["1455年征服者穆罕默德苏丹出征塞尔维亚之后不久，塞尔维亚牧首区中心伊佩克转入奥斯曼管理；奥斯曼史料中没有关于这次转移的记录。该镇后来渐渐变成一座小型穆斯林城镇，成为杜卡金桑贾克中桑贾克贝伊的驻地之一。", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["征服埃内兹与萨莫色雷斯——西色雷斯海岸完成", "106e723b"], "d": ["位于马里查河入海处的埃内兹，自在此据守八十年的热那亚裔加蒂卢西奥家族手中夺取；隶属于它的萨莫色雷斯岛在同一次战役中被攻占。随着埃内兹陷落，西色雷斯海岸带自塞萨洛尼基至加利波利成为不间断的奥斯曼领土。加蒂卢西奥家族手中只剩米蒂利尼，而它也将在六年后被攻占。", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["围攻贝尔格莱德失败", "3d53a604"], "d": ["征服者穆罕默德苏丹在君士坦丁堡的征服之后，围攻被视为中欧之锁的贝尔格莱德；然而匈雅提·亚诺什自多瑙河运来的增援和十字军传教士卡皮斯特拉诺召集的志愿者，阻止了要塞陷落。苏丹尽管在围攻中表现出个人英勇，仍因负伤而被迫撤退。这次失败，将使匈牙利边界在六十五年间对奥斯曼的推进关闭；贝尔格莱德要到1521年才被立法者苏莱曼攻取。", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["征服北摩里亚：巴特拉（帕特雷）", "c08a8509"], "d": ["与吞并塞尔维亚同期转向摩里亚专制公国的征服者穆罕默德苏丹的军队，夺取了半岛西北部的巴特拉。扼守科林斯湾入口的这一港口，是陆路进入摩里亚的锁钥；它的攻取为两年后的最终征服打下基础。该城是拜占庭专制君主们与拉丁世界联系的最后一座大码头。", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["攻取西黑海海岸：阿马斯拉", "f43608fc"], "d": ["热那亚在西黑海的设防殖民地阿马斯拉，在征服者穆罕默德苏丹的舰队与陆军联合压力下，未经抵抗便投降。巴尔滕—宗古尔达克海岸的这座港口，曾作为夹在坎达尔奥卢与奥斯曼领土之间的一个拉丁飞地存在；它被攻占后海岸连成一片。阿马斯拉的陷落，是两年后（1461年）指向锡诺普和特拉布宗的黑海大远征的第一步。", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["征服米蒂利尼岛", "fe17aeba"], "d": ["征服者穆罕默德苏丹统率的奥斯曼军队，于866年都尔黑哲月，经短暂而激烈的围攻，自热那亚裔加蒂卢西奥家族手中夺取米蒂利尼并加以吞并。爱琴海北部最大岛屿的陷落，也清除了热那亚人在该地区最后一个重要基地。该岛因靠近安纳托利亚海岸，此后将为奥斯曼舰队担任前哨，同时作为巴巴罗萨兄弟成长之地载入航海史。", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["为期十六年的奥斯曼—威尼斯战争开始", "563ddb68"], "d": ["威尼斯人为阻止奥斯曼在摩里亚和爱琴海的推进，与卡拉曼和白羊王朝的统治者结盟，于1463年发动战争。东有乌宗·哈桑、西有威尼斯、中间有卡拉曼的这一包围策略，迫使征服者同时在多条战线作战。持续十六年的斗争涵盖了从奥特卢克贝利到阿尔巴尼亚战役的当时所有大型行动，直到1479年《伊斯坦布尔条约》才告结束。", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["征服黑塞哥维那大部：特雷比涅与莫斯塔尔", "f54c0100"], "d": ["与波斯尼亚分开建立管辖的黑塞哥维那公爵斯捷潘·武克契奇—科萨查的领土，在波斯尼亚王国覆灭三年后大体转入奥斯曼管理：南部的特雷比涅于1466年“连同几乎整个黑塞哥维那地区”被攻取。围绕内雷特瓦河桥两座小要塞兴起的莫斯塔尔，应当也是在黑塞哥维那中心布拉盖于1466—1468年被征服前不久被攻占的；在1468—1469年的波斯尼亚总括户籍调查中，它以“桥头要塞”之名登录。公国剩余要塞与黑塞哥维那的征服于1483年完成。", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["第二次阿尔巴尼亚战役——征服者亲征斯坎德培", "9cdd2bfa"], "d": ["为打破斯坎德培超过四分之一世纪的抵抗，征服者穆罕默德苏丹于1466—1467年间发动了亲自统率的大规模战役。奥斯曼军队围攻阿克切希萨尔，并修建了伊勒巴桑（埃尔巴桑）要塞以控制该地区。战役虽然打断了阿尔巴尼亚抵抗的脊梁，却未能攻下要塞；该地区的完全臣服要等到斯坎德培死后的十年。", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["白羊王朝先头部队从黑羊王朝手中夺取宾格尔城堡", "51b94cbc"], "d": ["在贾汉沙讨伐乌宗·哈桑的远征最后几周，白羊王朝先头部队攻占了宾格尔城堡；随着贾汉沙于1467年11月10日被杀，黑羊王朝在该地区的统治告终。", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["黑羊王朝崩溃：贾汉沙阿被杀", "30bc6358"], "d": ["在出征乌宗·哈桑途中因严冬压境而返回时遭袭击的黑羊王朝君主贾汉沙阿，在宾格尔与基伊之间逃跑时被杀。此次打击之后国家无法恢复；末代君主哈桑·阿里于1469年被乌宗·哈桑之子乌鲁·穆罕默德俘获并处死。在东安纳托利亚、阿塞拜疆和伊拉克统治了近一个世纪的黑羊统治，由此转入白羊王朝。", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["斯坎德培之死——阿尔巴尼亚抵抗的熄灭", "9158c35f"], "d": ["曾在奥斯曼宫廷中长大、1444年伊兹拉迪溃败之后起事并在阿尔巴尼亚抵抗了超过四分之一世纪的斯坎德培，死于避难之地莱什。在穆拉德二世与征服者时代多次牵制奥斯曼军队的这一抵抗，随他之死失去了核心领导。随着教廷与威尼斯所扶持的阿尔巴尼亚战线崩溃，奥斯曼人在十年内攻取阿克切希萨尔和斯库台，把该地区最终纳入领土。", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["奥斯曼统治在开塞利建立：盖迪克·艾哈迈德帕夏终结卡拉曼王朝", "33cf35fc"], "d": ["1474年盖迪克·艾哈迈德帕夏终结卡拉曼王朝之后，开塞利归入奥斯曼统治；该城在15世纪期间曾在杜勒卡迪尔王朝、拉马赞王朝与卡拉曼王朝之间易手。在奥斯曼统治下，开塞利成了卡拉曼贝勒贝伊区的桑贾克中心。", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["萨摩斯被遗弃：热那亚（马奥纳）所有权终结", "5bdc380c"], "d": ["据TDV，该岛在1475年之后被遗弃；1479年法提赫苏丹穆罕默德征服该岛并修建了城堡。", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["摩尔达维亚的拉科瓦（瓦斯卢伊）溃败", "a1a74bf7"], "d": ["摩尔达维亚总督大斯特凡把鲁米利总督阉人苏莱曼帕夏统率的奥斯曼军队引入沼泽地带，使其遭受惨败。作为征服者时代最沉重的陆战失败之一，这次溃败在欧洲引起巨大反响，并使斯特凡在十字军世界获得声望。苏丹将于次年亲自出征报复。", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["阿克德雷（白谷）大捷——摩尔达维亚战役", "45a66791"], "d": ["为报一年前拉科瓦溃败之仇而亲自出征的征服者穆罕默德苏丹，在阿克德雷一带使奥斯曼军队与摩尔达维亚部队遭受大败，并进入侯国中心苏恰瓦。然而要塞未能攻下；由于粮食短缺、近卫军中出现的瘟疫以及匈牙利人的筹备，军队被迫撤退。摩尔达维亚的最终归附，要到随后数年，并随1484年攻取基利亚和阿克尔曼才得以实现。", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["攻取阿克切希萨尔（克鲁亚）与阿尔巴尼亚的完成", "559a79b4"], "d": ["斯坎德培之死十年之后，1478年随着阿克切希萨尔、德里瓦斯托、莱什和亚比亚克被攻占，阿尔巴尼亚的征服大体完成。多年抵抗奥斯曼军队、成为斯坎德培抵抗象征的克鲁亚要塞的陷落，意味着该地区威尼斯—阿尔巴尼亚同盟的终结。剩下的斯库台则将在次年签订的《伊斯坦布尔条约》中让给奥斯曼。", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["并入塔曼半岛", "4ef917b8"], "d": ["1475年攻取卡法和刻赤之后，征服者穆罕默德苏丹派往高加索海岸的舰队，连同阿纳帕和科帕，一并攻占了塔曼半岛上的热那亚马特雷加（塔马塔尔汗）。海峡两岸由此都被控制，进入亚速海的通道变得完全可控。塔曼作为通向北高加索的门户，隶属卡法桑贾克。", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["萨摩斯归入奥斯曼统治（法提赫）", "c877bc14"], "d": ["法提赫苏丹穆罕默德征服了萨摩斯，修建了一座城堡并重新整理了人口登记；该城堡于1483年因政治原因被巴耶塞特二世下令拆毁。", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["围攻罗得岛失败", "35a85c28"], "d": ["依征服者穆罕默德苏丹之命，由梅西赫帕夏统率的160艘舰船的舰队于885年（1480年）春围攻罗得岛，该岛被封锁三个月之久。在大团长皮埃尔·多比松领导下的圣约翰骑士团，尽管损失惨重仍奋力抵抗；885年杰马迪伊勒拉瓦尔月20日发动的最后一次大规模进攻也被击退后，舰队于8月3日撤退。这次失败之后，该城城墙被彻底翻新，成为欧洲最坚固的要塞；该岛要到1522年才被立法者苏莱曼攻取。", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["尼卡里亚（伊卡里亚）归入罗得岛圣约翰骑士团管辖", "5cbc2669"], "d": ["位于萨摩斯与希俄斯之间的尼卡里亚，在1481年至1521年间由罗得岛圣约翰骑士团管辖。", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["耶尼谢希尔会战——杰姆苏丹的失败", "c35abee2"], "d": ["征服者去世之后为争夺王位而行动的两兄弟在耶尼谢希尔平原对阵，杰姆苏丹遭到决定性失败。在布尔萨统治十八天并以自己的名义宣读呼图白的这位王子，失败之后被迫先逃往科尼亚，再前往马穆鲁克领土避难。耶尼谢希尔开启了奥斯曼历史上最持久的王朝危机：杰姆问题将在十四年间使奥斯曼对欧洲的对外政策陷于瘫痪。", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["吞并黑塞哥维那", "bf247891"], "d": ["波斯尼亚于1463年被征服之后，尚存的黑塞哥维那公国领土逐步转入奥斯曼管理：特雷比涅和莫斯塔尔于1466年被攻取，黑塞哥维那桑贾克于1470年组建，公国在亚得里亚海岸的最后领土也连同赫尔采格诺维（Herceg Novi）于1482年初被征服并并入该桑贾克。亚得里亚海后方的山区由此完全归奥斯曼所有，波斯尼亚与黑塞哥维那成为一个行政地理单元。最后一位公爵进入奥斯曼宫廷的儿子，就是后来官至大维齐尔的黑塞克扎德·艾哈迈德帕夏。", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["扎金索斯（Zakynthos）以年贡为条件留给威尼斯", "268a691a"], "d": ["法提赫时代末期从托科家族手中夺得的伊奥尼亚群岛中的扎金索斯，被忙于杰姆苏丹问题、寻求西线安宁的新苏丹留给了威尼斯。该岛被移交给一个承认奥斯曼君主权威并每年缴纳五百杜卡特年贡的威尼斯管辖。这样，奥斯曼在伊奥尼亚海的直接统治只剩下阿亚马夫拉。", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["杰姆苏丹逃往罗得岛避难", "2228d6da"], "d": ["围攻科尼亚的尝试也无果而终的杰姆苏丹，带着三十来人从安纳托利亚逃出抵达罗得岛，受到圣约翰骑士团的隆重迎接。然而做客很快变成囚禁；王子先被转交给法国，随后转交教廷，成为欧洲政治手中的筹码。巴耶塞特二世为让其兄弟被扣留而被迫支付年金，奥斯曼针对西方的军事行动直到杰姆之死前一直被搁置。", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["奥斯曼—马穆鲁克战争开始（奇里乞亚战线）", "3fe3f0c7"], "d": ["对杜尔卡迪尔奥卢的影响力之争，以及杰姆苏丹逃入马穆鲁克领土所遗留的敌意，于1485年在两个逊尼派大国之间引发了一场将持续六年的战争。在奇里乞亚平原阿达纳和塔尔苏斯一带发生的交战中，双方都未能压倒对方；奥斯曼军队遭受了几次沉重打击。这场战争是奥斯曼—马穆鲁克关系破裂的第一阶段，也是三十年后以冷酷者塞利姆的马尔季达比克与里达尼耶战役而告终的进程的开端。", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["奥斯曼—马穆鲁克和约——突尼斯调停", "60dd6719"], "d": ["1485年开始的奥斯曼—马穆鲁克战争中，双方都未能取得决定性胜利；经突尼斯君主奥斯曼·哈夫斯的斡旋，于1491年达成协议。协议使边界基本回到战前状态，两个伊斯兰国家之间的清算被推迟了一代人。六年消耗性的斗争，是巴耶塞特二世审慎的对外政策以及他不转向东方而注重内部整顿的主要原因之一。", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["被逐出西班牙的塞法迪犹太人获准进入奥斯曼", "5c2b5c24"], "d": ["格拉纳达陷落之后，逃避西班牙宗教裁判所迫害的犹太人中有一部分投奔奥斯曼领土，并被安置在各个城市。在奥斯曼统治下，这些塞法迪社群获得了迄今未曾有过的自由：可居住在自己愿意的地方、过自己的信仰生活、开办教育机构、修建新的犹太会堂。他们带来的印刷、医学和财政知识改变了塞萨洛尼基与伊斯坦布尔的经济生活；这次移民成为奥斯曼宽容秩序在欧洲被谈论最多的范例。", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["杰姆苏丹之死——十四年人质生涯的终结", "f6588b70"], "d": ["自教廷转交给法国国王查理八世的杰姆苏丹，于1495年1月27日自罗马启程后，死于名为卡斯泰尔·卡普阿纳之处；史料记载他可能被教廷圈子毒死。十四年间作为对付奥斯曼的威胁筹码被欧洲诸国扣留的这位王子之死，终于使巴耶塞特二世腾出了手。果然，苏丹此后向威尼斯宣战，并使其舰队迎来首次大捷。", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["萨皮恩扎（宗奇奥）海战大捷——地中海上第一次大规模海军胜利", "9754aaef"], "d": ["随着杰姆问题的终结而腾出手的巴耶塞特二世，于1499年向威尼斯宣战；奥斯曼舰队在萨皮恩扎（宗奇奥）外海击败威尼斯舰队，赢得了在地中海的第一次大海战胜利。凭这一胜利，舰队宣告自己已能在海上抗衡威尼斯。", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["凯法洛尼亚与伊萨卡的丧失", "60f0f687"], "d": ["因莫东和科龙被攻占而受震动的威尼斯与西班牙联合发起反攻，围攻了1479年以来在奥斯曼手中的凯法洛尼亚。经过四十七天的抵抗，城堡陷落，该岛连同伊萨卡归威尼斯，三百年间再未回到奥斯曼统治之下。这一损失造成了在摩里亚所得于伊奥尼亚被还回的平衡。", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["金帐汗国的覆灭与克里米亚的崛起", "0d1dc515"], "d": ["末代君主谢赫·艾哈迈德汗（1481—1502）未能使国家摆脱陷入的危机，金帐汗国于1502年因克里米亚汗门格里·吉莱的一击而成为历史。由于王位之争与分裂，在旧金帐汗国领土上出现了克里米亚、喀山、诺盖、阿斯特拉罕和西伯利亚诸汗国。受奥斯曼庇护的克里米亚的这一胜利，使奥斯曼在黑海以北的影响无可争议，而该地区产生的真空将由莫斯科在随后的世纪里填补。", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["奥斯曼—威尼斯战争结束与和约", "125b1526"], "d": ["1499年开始、以萨皮恩扎、勒班陀、莫东与科伦的丧失使威尼斯震动的战争，于1502年以和约结束。威尼斯失去在摩里亚最重要的基地，为保住在东地中海的商业特权而被迫承认奥斯曼的优势。被视为审慎的巴耶塞特二世的统治，凭这场战争使奥斯曼首次升至严肃的海上强国地位。", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["沙赫库卢起义——自特凯地区延伸至锡瓦斯的红头军起事", "3beadca7"], "d": ["在萨法维宣传对安纳托利亚的影响下，于1510年公开起事的沙赫库卢·巴巴·特凯利，1511年3月攻入安塔利亚集市，4月在屈塔希亚及其周边击败了奥斯曼军队。在锡瓦斯附近与大维齐尔阉人阿里帕夏的最后交战中，双方都损失惨重；大维齐尔和起义首领都丧生。动摇了国家在安纳托利亚权威的这次起义，暴露了巴耶塞特二世晚年的权力真空，并成为王子塞利姆向王位进军的最有力理由。", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["巴耶塞特二世退位与冷酷者塞利姆苏丹登基", "c4cfab69"], "d": ["在与兄弟们的王位斗争中得到近卫军支持的塞利姆王子的压力下，巴耶塞特二世于1512年4月24日退位，塞利姆一世当天作为第九位奥斯曼君主登基。年迈的苏丹在前往出生地迪迪莫提乔途中，于918年拉比尔·敖外鲁月25日（1512年6月10日）在乔尔卢附近的阿巴拉尔村去世。三十一年谨慎内向的统治，被将在八年内使帝国疆域翻倍的“冷酷者”时代取代。", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["锡尼（Sinj）城堡的征服", "83271ea5"], "d": ["波斯尼亚边境的奥斯曼突袭部队，从匈牙利王国手中夺取了深入达尔马提亚内陆的锡尼（Sinj）城堡。这是九年后因加齐·胡斯雷夫贝伊征服克宁及其周边而扩展的达尔马提亚边境线的早期一环；该城堡将于1686年丧失给威尼斯。", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["耶尼谢希尔会战与艾哈迈德王子被除掉", "e2ed15dd"], "d": ["冷酷者塞利姆苏丹在布尔萨附近的耶尼谢希尔平原击溃了王位最强劲的对手——其兄艾哈迈德王子，并将其俘获除掉。自1511年起的兄弟之争由此终结，安纳托利亚的内部分裂结束。塞利姆稳固后方，获得了转向萨法维问题的自由。", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["冷酷者塞利姆苏丹进入大不里士", "dad2e227"], "d": ["查尔迪兰大捷之后，奥斯曼军队进入萨法维都城大不里士，该城呼图白以苏丹之名宣读。塞利姆在此停留一周，把一部分大不里士的艺匠和乌理玛迁往伊斯坦布尔；这次迁移将深刻影响奥斯曼宫廷艺术。因冬季临近和近卫军的不满，该城被放弃，但萨法维在东方的优势已被打破。地图上这一天转入奥斯曼的地方并不相连，而这是正确的：大不里士是九天的军队占领；埃尔津詹平原在战役期间未经战斗投降，其中的凯马赫要塞则在萨法维手中抵抗到1515年5月19日；锡尔特是由在大不里士从沙赫伊斯梅尔囚禁中获释的哈桑凯伊夫王哈利勒贝伊归顺奥斯曼，并从萨法维手中夺回的——其周边的迪亚巴克尔直到1515年，哈桑凯伊夫直到1517年一直属萨法维。", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["穆什与宾格尔（恰帕克楚尔）自萨法维人转入奥斯曼统治", "b0a53b5a"], "d": ["恰尔迪兰之后东安纳托利亚自萨法维人手中夺得，穆什于伊历921年／1515年归入奥斯曼统治；相邻的恰帕克楚尔（宾格尔）在同一进程中并入奥斯曼。", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["自萨法维手中征服凯马赫要塞", "73fd8671"], "d": ["从查尔迪兰返回途中在阿马西亚过冬的冷酷者塞利姆苏丹，委派比伊克勒·穆罕默德帕夏去征服扼守幼发拉底河渡口的设防的凯马赫要塞。在苏丹亲自参加的围攻后，要塞从萨法维手中夺得，东安纳托利亚的大门被打开。这一征服是把查尔迪兰胜利变为持久领土收获的第一个具体步骤。", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["图尔纳山大捷——杜尔卡迪尔侯国臣属奥斯曼", "fd879145"], "d": ["奥斯曼军队在居克孙与安德林之间的厄尔代克利一带，击败了在查尔迪兰战役期间态度暧昧的杜尔卡迪尔侯阿拉丁·博兹库尔特；阿拉丁在这场战斗中被杀。侯国并未在此日期被吞并：阿拉丁之后，冷酷者塞利姆苏丹让谢赫苏瓦尔奥卢阿里贝伊出任杜尔卡迪尔奥卢侯国之首，以马拉什—埃尔比斯坦为中心的国土作为臣属奥斯曼的侯国延续。马穆鲁克边界上的缓冲地带由此进入奥斯曼控制，两年后埃及战役之路打通；吞并则将在阿里贝伊被杀之后实现。", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["征服阿米德（迪亚巴克尔）与迪亚巴克尔总督区的建立", "a6867d5b"], "d": ["在伊德里斯·比特利西使该地区的逊尼派库尔德诸侯倒向奥斯曼之后，萨法维军队无法承受长期围攻，阿米德的钥匙被交给比伊克勒·穆罕默德帕夏。该城被定为新建的迪亚巴克尔总督区的中心。上美索不达米亚的行政核心由此落入奥斯曼之手。", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["征服哈尔普特——打开通往迪亚巴克尔之路", "564eb269"], "d": ["为解除萨法维对查尔迪兰之后所得的迪亚巴克尔的围攻而出发的卡拉曼总督胡斯雷夫帕夏，经三天围攻攻取了此前由切尔克斯·侯赛因贝伊夺取其周边的哈尔普特要塞。幼发拉底河以东通往迪亚巴克尔的道路由此得到保障。", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["科奇希萨尔（克泽尔泰佩）之战——卡拉汗战败", "9ea9e843"], "d": ["比伊克勒·穆罕默德帕夏统率的奥斯曼军队，在科奇希萨尔附近德德·加尔金旷野的科鲁克一带，以一场持续整日的会战击败了萨法维总督卡拉汗；卡拉汗被割下的首级被送往苏丹营帐。随后奥斯曼军队虽进入马尔丁城，却只停留数日便离开；萨法维守军据守的马尔丁要塞直到一年后才被接收。这一胜利保障了冷酷者的南部边界，使其得以转向埃及战役。同日并入的其他地方：帕卢、切米什盖泽克、锡维雷克。", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["冷酷者塞利姆苏丹自伊斯坦布尔出发远征埃及", "ac258b4b"], "d": ["冷酷者塞利姆苏丹表面上以筹备针对萨法维的新东征为名自伊斯坦布尔出发，经阿克谢希尔转向南方。马穆鲁克苏丹坎苏·高里与沙赫伊斯梅尔取得联系并威胁奥斯曼东翼，不久即导致目标改变。这次战役是将持续两年、并使奥斯曼变成中东帝国的大战役的开端。", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["攻取扎比德：奥斯曼海员首次进入红海", "38740e0c"], "d": ["面对葡萄牙在印度洋的压力，应马穆鲁克苏丹坎苏·高里之请派往红海的奥斯曼籍海员侯赛因贝伊与塞勒曼·雷斯，以其舰队夺取了扎比德。这次仍在马穆鲁克麾下进行的行动，是奥斯曼海军在红海—印度一线的第一次实际存在。一年后埃及转入奥斯曼，同一舰队将直接隶属伊斯坦布尔。", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["正式宣布战役目标为马穆鲁克与阿勒颇", "689e310d"], "d": ["因坎苏·高里与萨法维达成协议并将军队开向阿勒颇，冷酷者塞利姆苏丹公开宣布战役目标为马穆鲁克苏丹与阿勒颇。两个逊尼派国家之间多年的隐性竞争，由此转为公开战争。这一宣布开启了通向马尔季达比克的四周倒计时。", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["围攻亚丁失败：对葡萄牙在红海的首次尝试", "8ffd46f2"], "d": ["塞勒曼·雷斯与侯赛因贝伊为夺取通向印度洋的红海门户亚丁，进行了历时八天的围攻，但在该城坚固的防御面前被迫撤退。未能攻取亚丁，将使针对葡萄牙的南方战略多年受挫。这次尝试是奥斯曼在大洋政策上的第一次考验。", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["拉马赞奥卢侯国归属奥斯曼", "cfaa3754"], "d": ["马尔季达比克大捷之后进行的任命中，以阿达纳为中心的拉马赞奥卢侯国被交给马哈茂德贝伊，并置于奥斯曼统治之下。脱离马穆鲁克宗主权的这一侯国，并未被取消，而是以“世袭领地”（奥贾克勒克）的地位留给了该家族；拉马赞奥卢以奥斯曼桑贾克贝伊的身份继续管理奇里乞亚平原。这一特殊安排一直延续到皮尔·曼苏尔放弃侯位的1608年。同日并入的其他地方：马拉蒂亚、塔尔苏斯、摩苏尔、安泰普。", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["阿勒颇、拉卡与代尔祖尔进入奥斯曼统治", "2088eb6a"], "d": ["马尔季达比克之战四天后，冷酷者塞利姆苏丹未遇抵抗便进入阿勒颇，该城清真寺中的呼图白以他的名义宣读。被视为叙利亚商业与行政首都的阿勒颇如此迅速陷落，显示马穆鲁克权威在该地区已经崩溃。该城的占领使通往大马士革并由此通往埃及之路一下子打开。同日并入的其他地方：安条克、拉卡、代尔祖尔。", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["在阿勒颇格克梅丹会见阿拔斯哈里发穆塔瓦基勒三世", "22979f42"], "d": ["在马尔季达比克与马穆鲁克军队一同被俘的开罗阿拔斯哈里发穆塔瓦基勒三世，在阿勒颇格克梅丹被带到苏丹面前，冷酷者塞利姆苏丹对他表示了极大的尊敬。自1261年起在马穆鲁克苏丹阴影下作为象征性职位存在的开罗哈里发位，借这次会见事实上转入奥斯曼庇护。哈里发后来将与苏丹一同被带往伊斯坦布尔。", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["的黎波里（沙姆）与哈马进入奥斯曼管理", "a1e19a79"], "d": ["继阿勒颇和哈马之后，叙利亚海岸的的黎波里（沙姆）也未经抵抗而转入奥斯曼管理。作为东地中海最繁忙的港口之一，该城是大马士革通向大海的门户，也是丝绸与糖贸易的中心。它的攻取使沙姆地区的海岸带全部易手。", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["大马士革（迪马什克）进入奥斯曼统治", "2b844d91"], "d": ["继阿勒颇之后，哈马与霍姆斯投降，前路畅通的冷酷者塞利姆苏丹于9月27日抵达大马士革城下；他没有立即入城，而是在城外马斯塔巴一带扎下大帐，在到达后的第十二天以盛大仪式入城。他在大马士革长期停留，建立了叙利亚的行政秩序，并为穆希丁·伊本·阿拉比修建了陵墓。沙姆地区全部由此脱离马穆鲁克管理。同日并入的其他地方：贝鲁特。", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["图曼贝在开罗被宣布为马穆鲁克苏丹", "6020d90d"], "d": ["在马尔季达比克阵亡的坎苏·高里之后，马穆鲁克埃米尔们拥立了将成为国家末代苏丹的图曼贝登位。切尔克斯出身的新苏丹，接手的是一个已失去叙利亚、国库枯竭、缺乏火器的国家。尽管如此，他仍将在开罗城前建立防线，组织对奥斯曼推进的最后一次抵抗。", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["加沙（汗尤努斯）会战：詹贝尔迪·加扎利战败", "9f1eb8cb"], "d": ["冷酷者塞利姆苏丹派大维齐尔阉人锡南帕夏率四千人的先头部队前往加沙。被图曼贝任命为大马士革总督的詹贝尔迪·加扎利，试图在加沙—汗尤努斯一线阻挡奥斯曼先头部队，却遭到惨败并逃往埃及。随着巴勒斯坦最后一支马穆鲁克缓冲部队的溃散，通往西奈沙漠之路完全打开。", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["约旦河以东：安曼进入奥斯曼管理", "9db62667"], "d": ["加沙会战之后准备远征埃及的奥斯曼军队南下之际，约旦河以东的安曼也进入奥斯曼管理。巴勒斯坦的沿海与内陆城市（雅法、纳布卢斯、赛伊达、阿克、耶路撒冷）则在马尔季达比克之后的1516年秋季就已易手。这些城市在四个世纪里作为大马士革省的桑贾克被管理。", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["冷酷者塞利姆苏丹抵达耶路撒冷", "66d7bfad"], "d": ["加沙会战之后，冷酷者塞利姆苏丹率国家要员和军队来到马尔季达比克之后未经抵抗便转入奥斯曼统治的耶路撒冷。苏丹参拜了圆顶清真寺和阿克萨清真寺，确认了该城的神圣地位。耶路撒冷自此至1917年12月整整四个世纪都将留在奥斯曼管理之下。", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["冷酷者塞利姆苏丹进入加沙并转向西奈沙漠", "2106bfc7"], "d": ["詹贝尔迪·加扎利在汉尤努斯战败（1516年12月21日）之后，加沙掌握在先头部队手中。苏丹于1517年1月2日进入加沙，在此与统率先头部队的锡南帕夏会合，军队进行了渡往埃及的最后准备。自加沙至萨利希耶的无水卡提亚（西奈）沙漠中将行军八站，并以骆驼运水。这一渡越是战役中风险最大、后勤上最艰难的阶段。", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["攻取苏伊士——通往红海之门", "05f3324e"], "d": ["里达尼耶大捷之后，随着奥斯曼军队进入开罗，红海北端的苏伊士也转入奥斯曼管理。马穆鲁克曾由此向印度洋派遣舰队的这座船坞港口，成为针对葡萄牙的南方政策的基地。苏伊士是三个世纪后将开凿运河那条线路的北口。", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["奥斯曼军队首次进入开罗", "0a3f4f4d"], "d": ["里达尼耶大捷的次日，奥斯曼军队获准进入开罗，1月24日部队进驻该城。然而这次进入并不意味着完全控制该城；图曼贝已退入上埃及，马穆鲁克的抵抗尚未被打破。开罗的征服并非一日完成，而是在延续数周的血腥进程中完成的。", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["图曼贝突袭开罗与三天巷战", "b83b6ce6"], "d": ["退入上埃及的图曼贝，率约七千随从于1月27—28日夜晚突然进入开罗，在城内展开抵抗，使奥斯曼军队陷入极为困难的境地。在持续三天的激烈巷战中，马穆鲁克一度控制该城大部分地区。抵抗直到奥斯曼炮兵和援军投入才得以打破。", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["詹贝尔迪·加扎利投入奥斯曼麾下", "a94ea459"], "d": ["里达尼耶之后退往萨利希耶的前马穆鲁克埃米尔詹贝尔迪·加扎利，向苏丹求饶。冷酷者塞利姆苏丹认为他对埃及与叙利亚的秩序建立有益，遂收纳其为部下。这一选择是奥斯曼把马穆鲁克骨干纳入体系而非清除的政策的第一个重要范例。", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["冷酷者塞利姆苏丹隆重入开罗与宣读呼图白", "6d98080c"], "d": ["巷战被平息之后，苏丹于1517年2月15日以极为隆重的仪式进入开罗，各清真寺以他的名义宣读呼图白。呼图白在开罗以奥斯曼苏丹之名宣读，宣告自1250年起延续的马穆鲁克统治在法理上终结。这一日期被视为埃及实际征服在象征意义上完成的时刻。", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["末代马穆鲁克苏丹图曼贝在塔鲁杰被擒", "7058e6ad"], "d": ["离开开罗后躲藏在尼罗河三角洲的图曼贝，被曾给他提供庇护的贝都因人告发，在塔鲁杰一带被俘。他的被擒消除了马穆鲁克抵抗的有组织中心。末代苏丹此后被奥斯曼扣留了十四天。", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["图曼贝在巴布祖维拉被处决与马穆鲁克国家的终结", "ad9820be"], "d": ["被擒十四天后，图曼贝在开罗著名的城门巴布祖维拉被绞死；遗体后来被安葬在其叔父修建的经学院。自1250年起统治埃及与叙利亚的马穆鲁克国家就此正式成为历史。抵抗被打破后，上埃及（赛义德）的艾斯尤特和阿斯旺等城市也归入奥斯曼管理。", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["葡萄牙舰队进攻吉达与塞勒曼·雷斯的防守", "52322cf5"], "d": ["由约三十艘桨帆船和大帆船组成的葡萄牙舰队进攻吉达；塞勒曼·雷斯指挥该城防守，阻止敌人登陆并击沉了数艘葡萄牙船。这一防守避免了麦加的港口、从而朝觐之路落入一个基督教国家之手。吉达数月后将随汉志宣誓效忠而正式并入奥斯曼管理。", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["亚历山大以舰队接收——埃及征服完成", "386878fe"], "d": ["自里达尼耶之战整整四个月、图曼贝被处决三十六天之后，随着贾法尔贝伊统率的奥斯曼舰队抵达港口，亚历山大转入奥斯曼管理；拉希德和达米埃塔等三角洲港口也在同一进程中并入。埃及这座通向地中海的大港口是在开罗陷落数月之后、且不是自陆路而是自海路被接收，清楚地表明征服不是靠一场战役，而是分区域完成的。亚历山大此后将成为连接伊斯坦布尔与开罗的命脉港口。同日并入的其他地方：拉希德（罗塞塔）。", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["汉志不战而并入：麦加谢里夫之子艾布·努迈伊宣誓效忠", "c13b98c7"], "d": ["冷酷者塞利姆苏丹起初考虑派兵夺取麦加及其周边，但在麦加埃米尔谢里夫·巴拉卡特表示顺服后放弃了此念。巴拉卡特十二岁的儿子艾布·努迈伊携父亲的礼物和麦加的钥匙来到开罗，被接见于苏丹面前。于是汉志并非作为里达尼耶的自动结果，而是在五个半月之后、未发一枪、以和平并宣誓效忠的方式并入奥斯曼。同日并入的其他地方：塔伊夫。", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["接受“两圣地仆人”称号与在麦地那宣读呼图白", "63b32b59"], "d": ["在麦加使团第二次受接见之后，冷酷者塞利姆苏丹正式担负起两圣地的庇护，并开始使用“两圣地之仆”称号。谢里夫·巴拉卡特穿上送给他的礼袍，以苏丹之名宣读呼图白；随着麦地那使团也前往伊斯坦布尔，巴拉卡特的埃米尔之位由敕书确认。苏丹向两圣地居民送去二十万金币和大量粮食，开启了每年重复的苏尔礼赠传统。同日并入的其他地方：延布、泰布克。", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["塞勒曼·雷斯投入奥斯曼麾下与红海政策的移交", "771da99a"], "d": ["曾在吉达抵御葡萄牙人的塞勒曼·雷斯来到开罗，被带到冷酷者塞利姆苏丹面前；虽被扣留了一段时间，1519年被召往伊斯坦布尔，并承诺准备三十艘桨帆船和数艘大帆船对付葡萄牙威胁。这次会见是红海与印度洋政策从马穆鲁克遗产中被接收并直接隶属伊斯坦布尔的开端。奥斯曼此时已不仅是地中海国家，也是奉行大洋政策的力量。", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["冷酷者塞利姆苏丹离开开罗与海尔贝伊出任总督", "8cd4fb23"], "d": ["在埃及停留约八个月并建立了行政、财政与军事秩序的冷酷者塞利姆苏丹离开开罗；在马尔季达比克撤出左翼而加速马穆鲁克溃败的前阿勒颇代理总督海尔贝伊，作为埃及第一位奥斯曼总督，自山岳堡垒开始管理。选择马穆鲁克出身的总督，是使新政权不致令当地民众感到陌生的有意过渡政策。苏丹在返程途中，把末代阿拔斯哈里发穆塔瓦基勒三世以及埃及杰出的艺匠与学者一并带往伊斯坦布尔。", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["开罗阿拔斯哈里发位的终结——“交接仪式”传说", "1d357640"], "d": ["冷酷者塞利姆苏丹占领埃及后，把在马尔季达比克被俘的末代哈里发穆塔瓦基勒三世·阿拉拉带往伊斯坦布尔；自1261年起在马穆鲁克苏丹阴影下无实权地延续的开罗阿拔斯哈里发位由此终结。至于哈里发位在圣索菲亚以正式仪式交给冷酷者的著名传说，最早出现在十八世纪末多松的著作中，冷酷者时代的任何史料都没有。TDV伊斯兰百科全书因没有记载仪式的原始史料而视该传说为杜撰；但同时指出，哈里发位的转移在教法上并不需要这样一种交接仪式。", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["埃尔祖鲁姆并入奥斯曼管理——萨法维在东安纳托利亚的影响被打破", "78d1be02"], "d": ["查尔迪兰大捷（1514年）之后，该地区的奥斯曼影响虽有增长，但埃尔祖鲁姆的完全攻占一直推迟到伊朗影响被打破；该城直到埃及战役之后的1518—19年才并入奥斯曼管理。埃尔祖鲁姆于1502年随沙赫伊斯梅尔终结白羊侯国而进入萨法维统治；这十六年的时期由此结束。1534年伊拉克战役期间将建立埃尔祖鲁姆总督区。1518—1519年间，阿什卡莱与埃尔祖鲁姆地区一同并入奥斯曼管理（日期未经证实）。", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["杰拉里起义的开端：博佐克的谢赫杰拉勒起事", "99bd8a99"], "d": ["在博佐克一带，一位名叫谢赫杰拉勒的人宣布自己是马赫迪，在托卡特周边起事；起义虽被镇压，其名字却在一个世纪里成为安纳托利亚一切匪帮和起义运动的称谓。杰拉里现象在十六世纪末与提马尔制度的瓦解及人口压力相结合，变成帝国持续最久的内部治安问题。起义在安纳托利亚引发了称作“大逃亡”的大规模迁移。", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["阿尔及尔归属奥斯曼国家", "b8eba4c1"], "d": ["在北非抵抗西班牙压力的海雷丁·雷斯，为求立足向伊斯坦布尔呈请，把阿尔及尔献给苏丹，呼图白以冷酷者塞利姆苏丹之名宣读。阿尔及尔由此正式并入奥斯曼领土，海雷丁以总督的称号获派兵员和火炮。这次归属奠定了奥斯曼在西地中海延续数个世纪的海上统治的基础。同日并入的其他地方：君士坦丁、舍尔沙勒（Cherchell）、梅迪亚（提泰里）、塞提夫。", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["冷酷者塞利姆苏丹在乔尔卢去世", "9fe83744"], "d": ["八年间把国土扩大一倍多的塞利姆一世，于1520年7月18日为新的出征离开伊斯坦布尔；因背上长出的大肿瘤而无法越过乔尔卢继续前进。尽管医生施救，病情仍加重，经两个月的无望治疗后，于926年10月8—9日（1520年9月21—22日）在此去世。他以查尔迪兰、马尔季达比克和里达尼耶阻止了伊朗并消灭了马穆鲁克国家，把哈里发位和两圣地的庇护权带给了奥斯曼。身后只留下一个儿子：苏莱曼。", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["尼卡里亚（伊卡里亚）岛并入奥斯曼统治", "6afa972b"], "d": ["位于萨摩斯与希俄斯之间的尼卡里亚，在1481年至1521年间由罗得岛圣约翰骑士团管辖；该岛的第一个奥斯曼时期始于1522年，持续到1822年。这一时期税收的征收和缴纳由卡伊马卡姆负责；与其他爱琴海诸岛一样，地方长老会议（demogerontia）也继续存在，并不时与奥斯曼当局发生冲突。", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["杜勒卡迪尔地区的并入——以马拉什为中心的杜勒卡迪尔行省", "595c3c30"], "d": ["1515年图尔纳达格溃败之后作为奥斯曼属国存续的杜勒卡迪尔地区，在谢赫苏瓦尔奥卢阿里贝伊在阿尔图科瓦连同其子女一起被杀之后，被直接并入奥斯曼领土，并设为以马拉什为中心的行省。该侯国的博佐克地区作为单独的桑贾克归属奥斯曼管辖。这样，马拉什、埃尔比斯坦、格克孙、居伦、扎曼特和达伦德约两个世纪的杜勒卡迪尔王朝时期结束；位于马穆鲁克边界的缓冲侯国彻底消失。", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["克宁的征服", "a46d3117"], "d": ["通过波斯尼亚桑贾克贝伊加齐·胡斯雷夫贝伊于伊历927至928年（1521至1522年）的突袭，以克宁、斯克拉丁和奥斯特罗维察为首的一系列威尼斯城堡归入奥斯曼统治；边界被推进到第二道山脉之外。这一征服链奠定了十五年后因攻占克利斯而完成的达尔马提亚桑贾克的基础。", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["骑士团的撤出：博德鲁姆、科斯和十二群岛的移交", "ea01666e"], "d": ["根据罗得岛的投降条件，圣约翰骑士团不仅撤出岛屿中心，还撤出了他们占据两百年的全部据点。安纳托利亚海岸的博德鲁姆（圣彼得）城堡以及科斯、卡利姆诺斯和莱罗斯等岛屿，由此未经战斗归入奥斯曼统治。在罗得岛陷落两周后完成的这一移交，使拉丁人在爱琴海东南角的存在彻底终结。", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["埃及的叛徒艾哈迈德帕夏起事", "b18bb805"], "d": ["期待出任大维齐尔却被派往埃及总督之职的艾哈迈德帕夏，在开罗自称“马利克·曼苏尔苏丹艾哈迈德”并宣告独立。起义很快被镇压，帕夏被杀，然而这一事件显示出帝国最富庶行省中央控制的脆弱。为此，易卜拉欣帕夏前往埃及，命人制定了重新整顿行省管理的著名的《埃及法典》。", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["北波斯尼亚的并入：亚伊采与巴尼亚卢卡", "8ec86cfa"], "d": ["莫哈奇之后匈牙利防线崩溃，波斯尼亚桑贾克贝伊加齐·胡斯雷夫贝伊向弗尔巴斯河谷进军，夺取了匈牙利王国手中最后的波斯尼亚城堡。随着亚伊采和巴尼亚卢卡的陷落，波斯尼亚省在北面抵达萨瓦河，克罗地亚战线随之产生。巴尼亚卢卡很快成为该省的第二个中心。", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["攻取布达并交给扎波利亚", "fba4f89b"], "d": ["在远征维也纳的途中，奥斯曼军队围攻落入斐迪南手中的布达并将其收回，把该城交给奥斯曼庇护下的匈牙利国王约翰·扎波利亚（János Szapolyai）。于是在匈牙利之上，哈布斯堡—奥斯曼竞争中的缓冲藩属王国模式得以建立。这一秩序将延续到1541年，扎波利亚死后布达将被改为直接的奥斯曼行省。", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["立法者苏莱曼出征德意志——向查理五世挑战", "7c3d7055"], "d": ["维也纳围攻无果、斐迪南重新围攻布达之后，苏丹这一次自伊斯坦布尔出发，意在把皇帝查理五世直接引入会战。大军将在8月因小要塞京斯的抵抗而被牵制，皇帝不出战，战役遂仅限于袭击。这次战役为次年与哈布斯堡的第一次和平奠定了基础。", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["德意志战役与围攻京斯（克塞格）", "8aec937a"], "d": ["立法者苏莱曼为迫使查理五世进行会战，率军向奥地利进军；小要塞京斯抵抗了二十五天，拖延了大军的推进。皇帝不出战，袭击部队打击了维也纳周边，随着季节推移而回师。战役没有带来领土收获，却使哈布斯堡坐上谈判桌，为次年的和平奠定了基础。", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["《伊斯坦布尔条约》——同哈布斯堡的第一次和平", "b085767a"], "d": ["苏丹接见斐迪南的使者科尔内利乌斯并同意停火，奥斯曼与奥地利之间第一份正式的和约文本由此产生。依条约，斐迪南同意为其手中的匈牙利领土缴纳年税，奥地利大公在礼仪上被视同大维齐尔。这种不平等地位，是十六世纪奥斯曼外交优越主张的明确表达。", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["卡尔斯的攻占与东北边界的打开", "742e3101"], "d": ["两伊拉克远征的先头部队从埃尔祖鲁姆向东进发之际，由格鲁吉亚阿塔贝格国掌握、自帖木儿以来一直荒废的卡尔斯城堡，未遇抵抗便被接收。该城因控制阿拉斯河弯与奇尔德尔之间的通道，被视为通往伊朗的北门之钥。这一收获成为三十年后将建立的卡尔斯贝勒贝伊区和高加索防线的第一环。", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["首次进入大不里士——两伊拉克远征的开端", "cf7ed4e3"], "d": ["以总司令之名率先出发的易卜拉欣帕夏，在沙赫塔赫马斯普避免会战、退入内地之后，未遇抵抗地进入萨法维都城大不里士。苏莱曼大帝也于九月抵达该城；但由于冬季来临和补给线过长，军队转向巴格达方向，大不里士未能长期据守。这座自恰尔迪兰之后第二次被攻占的城市，成为奥斯曼认识到在东方攻占容易、据守困难的地方。", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["巴巴罗萨征服突尼斯", "d8754216"], "d": ["海军大臣巴巴罗萨·海雷丁帕夏，以舰队打击意大利海岸之后转向突尼斯，赶走哈夫斯王朝君主穆莱·哈桑并进入该城。以其控制西西里海峡的位置，突尼斯的攻取使西地中海的力量对比一下子转向有利于奥斯曼。然而这一统治并未持久，查理五世次年将以大舰队作出回应。", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["突尼斯丧失于查理五世", "a691f0f8"], "d": ["查理五世以得到热那亚和教廷舰队支持的大规模远征攻取古莱特之后夺取突尼斯，并使穆莱·哈桑在西班牙庇护下复位。该城驻扎了西班牙守军，奥斯曼在中地中海的推进被暂时阻止。突尼斯的最终征服要到四十年后的1574年才得以实现。", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["加齐·胡斯雷夫贝伊的萨瓦河沿线行动：波斯尼亚布罗德与亚塞诺瓦茨", "3740ec83"], "d": ["1528年攻占亚伊采和巴尼亚卢卡之后，萨瓦河沿岸的城堡又有一段时间留在隶属哈布斯堡王冠的克罗地亚—斯拉沃尼亚边境。1536年第三次出任波斯尼亚桑贾克贝伊的加齐·胡斯雷夫贝伊，当年攻占波热加及其周边的同时，也将萨瓦河畔的布罗德和亚塞诺瓦茨城堡并入奥斯曼统治。这样，波斯尼亚的北部边界抵达萨瓦河；该地区在两年后因攻占杜比察而得以完成。", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["马克布尔·易卜拉欣帕夏被处决", "348aa7b8"], "d": ["任大维齐尔十三年、作为立法者苏莱曼最亲密的朋友和国家事实上的二号人物的易卜拉欣帕夏，在被召去参加开斋饭的宫中未说明任何理由便被勒死处决。他在伊拉克战役中的作风、使用“统帅苏丹”称号以及宫内的平衡，被视为其死亡的原因。处决是奥斯曼中央管理中表明大维齐尔们并无绝对安全的转折点。", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["征服克利斯要塞与建立达尔马提亚桑贾克", "6ffd4ebf"], "d": ["加齐胡斯雷夫贝伊的总管、克罗地亚裔皈依者穆拉德贝伊，自威尼斯手中夺取了斯普利特以北的战略要塞克利斯。征服之后，克利斯随即被定为涵盖其周边的新桑贾克与县的中心；该桑贾克的边界在很大程度上勾勒出奥斯曼克罗地亚的框架。这次征服在克宁之后十五年到来，完成了达尔马提亚内陆的行政骨架。", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["围攻科孚岛与对威尼斯的战争", "11af95bd"], "d": ["继普利亚战役之后，奥斯曼军队在科孚岛登陆，围攻该岛坚固的威尼斯要塞。由于要塞地势险峻、损失惨重和季节条件，9月6日解除封锁撤退。围攻虽无结果，但与威尼斯展开的战争，以爱琴海和亚得里亚海众多岛屿并入奥斯曼以及次年的普雷韦扎大捷告终。", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["巴巴罗萨的爱琴海远征：威尼斯直辖诸岛的攻占", "1b32ed96"], "d": ["从科孚围攻返回的舰队，利用对威尼斯已经宣战之机，在爱琴海逐一接收不隶属于公国而直接隶属于威尼斯的岛屿。埃伊纳岛在激烈抵抗后被攻陷，奎里尼家族手中的阿斯蒂帕莱亚以及卡尔帕索斯和卡索斯投降，由修道院管辖的帕特莫斯也接受了奥斯曼的保护。纳克索斯公国则被课以贡赋并留在原地；对它的吞并要等到1566年。", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["巴巴罗萨的北爱琴海远征：斯基罗斯与北斯波拉泽斯群岛的攻占", "20ab688e"], "d": ["在前往普雷韦扎的途中，舰队逐一接收了伊斯坦布尔被征服之后避往威尼斯的北爱琴海诸岛。埃维亚以北的斯基罗斯，以及扼守萨洛尼卡湾口的斯基亚索斯、斯科派洛斯和阿洛尼索斯由此归入奥斯曼统治。这些岛屿填补了最后一块北爱琴海空缺——尽管埃维亚已于1470年被攻占，这些岛屿仍在威尼斯手中又留了六十八年。", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["亚丁的攻占与也门海岸的并入", "e7d46d8f"], "d": ["为印度远征从苏伊士出发的舰队，因不先确保红海安全就无法驶入大洋，故先转向也门海岸。哈德姆·苏莱曼帕夏于1538年8月3日进入亚丁港；倾向葡萄牙人的塔希尔王朝统治者阿米尔·本·达乌德被带到船长门前处决，城内留下500名守军。同一次远征期间，摩卡以及控制海峡的卡马兰岛和法拉桑岛也被接收，也门贝勒贝伊区的基础就此奠定。这样，奥斯曼国家首次拥有了曼德海峡北岸的全部；而萨那和内陆地区则不得不再等九年。", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["摩尔达维亚战役与布贾克（本德尔）地区被吞并", "90a88a56"], "d": ["在针对不履行奥斯曼义务的摩尔达维亚总督彼得鲁·拉雷什的战役中，苏恰瓦被攻占，雅西城被克里米亚汗萨希卜·吉莱劫掠。苏丹任命蝗虫斯特凡为总督，并把本德尔连同布贾克（南比萨拉比亚）地区直接并入奥斯曼领土。这次吞并是使黑海西北海岸成为奥斯曼内海的诸环节之一。摩尔达维亚本就是臣属于奥斯曼的公国；这次战役并未自外国夺取土地，只是把本德尔与布贾克的内部管理自总督手中收回并直接隶属苏丹；公国其余部分仍保持藩属地位。同样的结构还将在1484年的基利亚与阿克尔曼以及1713年的霍京重现：边境要塞直属，内陆领土藩属。", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["纳夫普利翁（Nauplion）根据条约移交", "104d0937"], "d": ["普雷韦扎之后持续三年的威尼斯战争，以共和国同意放弃其在摩里亚的最后两座城堡而结束。围攻未能攻下的纳夫普利翁和莫奈姆瓦夏，在三十万杜卡特战争赔款之外，在谈判桌上移交给了奥斯曼。摩里亚半岛由此完整合一，不再留下一处威尼斯的足迹。", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["塞格德并入奥斯曼统治与塞格德利瓦的设立", "019aa000"], "d": ["1541年奥斯曼在布达的统治完全确立之后，塞格德的显贵们接受了斐迪南一世的统治，并准备武装防御。布达贝勒贝伊小巴利帕夏于1543年初召来该城的管理者们，以叛变为由将其处决，随后派兵前去攻占该城。此时塞格德利瓦被设立，第一任桑贾克贝伊由巴利帕夏之子德尔维什贝伊担任；该利瓦起初延伸于多瑙河与蒂萨河之间。", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["瓦尔波、希克洛什与佩奇的征服", "2ca030a3"], "d": ["在吞并布达两年后展开的匈牙利远征，第一个目标是确保新行省在德拉瓦河与多瑙河之间的南翼。攻占瓦尔波和希克洛什城堡之后，巴兰尼亚的中心佩奇投降。该城将成为奥斯曼匈牙利人口最稠密、建设最多的中心，历史学家易卜拉欣·佩楚伊鲁（佩奇人）即由此得名。", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["征服埃斯泰尔戈姆与塞克什白堡", "efca9e05"], "d": ["在立法者苏莱曼亲自出征的匈牙利战役中，经两周半的围攻，匈牙利王国的宗教中心、大主教驻地埃斯泰尔戈姆进入奥斯曼管理。随后匈牙利国王加冕之城塞克什白堡也被攻取，布达省的防御带得以完成。埃斯泰尔戈姆将作为多瑙河一线的关键要塞留在奥斯曼手中，直到1595年。", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["布达的北部和西部防御带：瓦茨、哈特万和希莫恩托尔尼亚", "733ee5ce"], "d": ["在攻占埃斯泰尔戈姆和伊斯托尔尼·贝尔格勒之后，布达贝勒贝伊为完成环绕都城的城堡圈，在没有苏丹出征的情况下行动。多瑙河湾的瓦茨、阿尔弗尔德之门哈特万以及肖河线上的希莫恩托尔尼亚被逐一接收。这一寂静年份的收获，使布达不再只是边境城市，而成为将维持一百四十年的行省中心。", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["巴士拉的并入与进入波斯湾", "02f87c11"], "d": ["巴格达征服期间（1534年），巴士拉统治者拉希德·本·马加米斯向苏莱曼大帝表示臣服，1538年送来了城市的钥匙。继任的谢赫叶海亚对奥斯曼人采取敌对态度后，巴格达贝勒贝伊阿亚斯帕夏自陆路、摩苏尔桑贾克贝伊率120艘船沿幼发拉底河进军；阿亚斯帕夏于1545年12月26日进入巴士拉，该城成为一个贝勒贝伊区的中心。位于阿拉伯河口的这个港口，是奥斯曼进入葡萄牙从霍尔木兹控制的海湾的门户；1555年《阿马西亚条约》中，伊朗也承认了这一状况。", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["萨那与也门内陆的征服", "d31ded85"], "d": ["继塔伊兹之后萨那也被攻占，全境都隶属于贝勒贝伊区。然而由于地势险峻和教派差异，这种统治从未稳固；也门对奥斯曼来说成了一条不断消耗兵力的战线。", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["塔伊兹的征服", "d4509df9"], "d": ["在九年前仅满足于沿海地带的也门，由于栽德派伊玛目在山区内陆日渐壮大，厄兹德米尔帕夏的部队登上高原攻占了塔伊兹。", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["《伊斯坦布尔条约》——同哈布斯堡的五年和平", "41f81773"], "d": ["奥斯曼与哈布斯堡之间签署了为期五年的和约；斐迪南同意为其手中的匈牙利领土每年缴纳30000杜卡特。条约从法律上确认了匈牙利一分为三的事实状态。西线由此得到保障，使立法者苏莱曼得以对伊朗发动新的战役。", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["第二次伊朗远征与大不里士的再度攻占", "e82365df"], "d": ["在反叛沙赫塔赫马斯普并避难于伊斯坦布尔的其弟埃尔卡斯米尔扎的怂恿下发动的远征中，军队第二次进入大不里士。萨法维人再度不进行会战，而是焦土后撤，因此在城中仅能停留几周。这次远征使人们确信大不里士无法据守，并使奥斯曼的战略转向建立持久的边界线，即巩固凡城。", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["凡城的征服与东部边界的确定", "fc8f930b"], "d": ["从大不里士返回途中受到围攻的凡城城堡，凭借其耸立于湖东岸岩石之上的位置，是该地区毫无争议的锁钥，经短暂围困后投降。该城立即被设为贝勒贝伊区中心；埃尔吉什、阿迪尔杰瓦兹和哈卡里诸桑贾克划归于此。与大不里士不同，凡城得以据守，并在四百年间一直是奥斯曼在东部最前沿的永久据点。", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["哈萨和盖提夫的并入——海湾的阿拉伯半岛海岸", "f6701e60"], "d": ["巴士拉被攻占之后，已成为葡萄牙在海湾西岸前哨的盖提夫被占领，并与内陆的哈萨绿洲一起建立了一个新的贝勒贝伊区。这里是对巴林和霍尔木兹行动的出发点。奥斯曼国家由此同时在阿拉伯半岛的红海和波斯湾两岸都有了发言权。", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["舍赫里佐尔的丧失——埃尔德兰贝伊苏赫拉布倾向萨法维人", "5600efc9"], "d": ["在两伊拉克远征期间（1535年）承认奥斯曼统治的舍赫里佐尔地区，由驻守扎尔姆城堡的埃尔德兰埃米尔比盖贝伊治理。1550年比盖贝伊去世后，占据扎尔姆城堡并掌控该侯国的其弟苏赫拉布倾向萨法维人，脱离了对奥斯曼的服从；舍赫里佐尔地区由此脱离奥斯曼的影响。该地区直到纳希切万远征期间的1554年，随着扎尔姆城堡被围攻攻占才得以收回。", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["阿尔达汉与瑟尔德尔盆地的攻占", "14c9eb76"], "d": ["埃尔祖鲁姆贝勒贝伊在与萨法维人持续作战期间，向格鲁吉亚阿塔贝格们位于库拉河弯的领土进军，将阿尔达汉和瑟尔德尔周边纳入奥斯曼统治。卡尔斯—阿尔达汉一线由此连成一体，东北方通往格鲁吉亚的高原也被控制。该地区最终的行政安排，将由二十七年后建立的瑟尔德尔行省来完成。", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["索科鲁·穆罕默德帕夏渡过多瑙河——特兰西瓦尼亚战争开始", "38fde931"], "d": ["由于特兰西瓦尼亚国王幼主亚诺什·西吉斯蒙德的监护人修士马尔蒂努齐引发的混乱，以及特兰西瓦尼亚将巴纳特诸城堡交给斐迪南，人们认为有必要再度出征；指挥权交给了鲁米利亚贝勒贝伊索科鲁·穆罕默德帕夏。军队不顾马尔蒂努齐的拖延努力渡过多瑙河，攻占了贝切、贝奇凯雷克、恰纳德和利波瓦；但对泰梅什瓦尔的围攻于11月16日因严寒而撤销。这样，在匈牙利，一场新的奥斯曼—哈布斯堡战争就此展开。", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["利波瓦（Lippa）城落入卡斯塔尔多的奥地利军队之手——城堡于12月5日投降", "a0e1ff0d"], "d": ["索科鲁·穆罕默德帕夏于1551年10月攻占的利波瓦，11月4日遭到卡斯塔尔多将军的军队围攻；两天后该城落入奥地利人之手。乌拉马帕夏率五千名守军又守卫了城堡九天，于1551年12月5日经协议撤出。直到1552年泰梅什瓦尔陷落，利波瓦一直在哈布斯堡手中。", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["自泰梅什瓦尔派出的部队占据巴纳特南部堡寨——韦尔谢茨、哈拉姆、凯韦", "edca0921"], "d": ["泰梅什瓦尔向奥斯曼军队投降之后，自围攻军队分出的部队转向巴纳特的小堡寨；据班拉基的叙述，韦尔谢茨、法切特、梅哈迪亚、察科瓦尔、哈拉姆瓦尔和凯韦的堡寨由这些部队占据。于是多瑙河畔的哈拉姆也落入奥斯曼之手。", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["索尔诺克的征服与埃格尔围攻的失败", "a7156e8f"], "d": ["泰梅什瓦尔被攻占后会合的两支奥斯曼军队，因雇佣守军弃堡而几乎未经战斗便占领了蒂萨河畔的索尔诺克。随后被围攻的埃格尔城堡，面对多布·伊什特万指挥的两千人守军三十八天的抵抗而未能攻下，军队因冬季来临而撤退。同一次远征中一座城堡轻易陷落而另一座坚守不下，是匈牙利边界已不再自动朝有利于奥斯曼方向推进的第一个明确迹象。", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["奥斯曼—法国同盟——法国舰队归奥斯曼指挥", "a8e01b22"], "d": ["依1553年2月1日的条约，法国舰队被置于奥斯曼舰队指挥之下；规定在西地中海对西班牙联合行动。条约之后，图尔古特·雷斯于1553年6月15日率四十五艘桨帆船出征支援法国。这是把1536年治外法权的商业基础推向军事合作的第一份正式同盟条约。", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["穆斯塔法王子在科尼亚埃雷利被处决", "dec36858"], "d": ["为参加为纳希切万战役集结的军队而进入父亲大帐的穆斯塔法王子，在将被接见之际遇上刽子手，被勒死。在军中备受爱戴的这位储君候选人被杀，在近卫军中引起了深深的愤怒，吕斯泰姆帕夏被免去大维齐尔之职。该事件作为奥斯曼王子政治最具争议的断裂之一，进入文学和民间记忆。", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["易卜里姆与努比亚边界南移", "c57d5d77"], "d": ["埃及贝勒贝伊区的南部边界，随着屹立于尼罗河岩石岬角上的易卜里姆城堡经厄兹德米尔贝伊之手得到加固，以及下努比亚被完全并入奥斯曼埃及，而被推进到第二瀑布以外。（奥斯曼在易卜里姆的行政组织是在征服埃及之后建立的；地图上易卜里姆自1517年起显示为奥斯曼领土。此年份是约数，来源未给出年份。）该城堡既是抵御来自努比亚袭击的屏障，也是通往森纳尔的黄金和奴隶之路的控制点。驻扎在此的波斯尼亚卫戍部队是如此持久，以至于其后裔三百年后仍留在城堡里。关于易卜里姆归入奥斯曼统治的时间，各来源给出了两种不同说法：TDV的“苏丹”条目将下努比亚并入奥斯曼埃及系于16世纪中叶厄兹德米尔帕夏的行动，而“努比亚”条目则写明直到哈勒法谷地的地区以及易卜里姆的行政组织是在1517年征服之后立即建立的。易卜里姆桑贾克于1573年7月26日划归哈巴沙省。", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["贝贾亚（Bougie）从西班牙人手中夺取", "49691cda"], "d": ["被西班牙占据四十三年、将阿尔及尔与君士坦丁之间的海岸一分为二的贝贾亚，在受到陆海围攻之后投降。随着城堡陷落，阿尔及尔军团的海岸一直到瓦赫兰连成一片。在西班牙，这一损失引起如此巨大的愤慨，以至交出城堡的指挥官阿隆索·德·佩拉尔塔在家乡被处决。", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["泽拉并入哈巴沙省", "7bbf369a"], "d": ["位于哈巴沙省南端、亚丁湾非洲海岸的泽拉港被纳入奥斯曼统治。作为阿达尔苏丹国通向海洋之门的这座城市，是驶出曼德海峡的船只的最后补给点。随着泽拉并入，奥斯曼国家在非洲的边界到达了最南端。", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["科尼亚王子们会战", "1c8de387"], "d": ["卷入王位斗争的巴耶塞特王子率约30000人来到科尼亚城下，在持续两天的交战中败于其兄弟塞利姆王子。溃败的巴耶塞特经阿马西亚逃往伊朗，投奔沙赫塔赫马斯普。会战使立法者苏莱曼晚年的继位危机变成了对外政策问题。", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["杰尔巴海战大捷", "c7b905c1"], "d": ["皮亚莱帕夏统率的奥斯曼舰队，以一次分兵机动，在杰尔巴前打散了为夺回的黎波里而集结的西班牙—热那亚—马耳他联军舰队。联军失去大部分舰队，岛上的要塞也很快陷落。杰尔巴被视为继普雷韦扎之后巩固奥斯曼在地中海优势的第二次大海战胜利。", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["巴耶塞特王子在加兹温被处决", "a759de14"], "d": ["逃往伊朗的巴耶塞特王子，经长期讨价还价，被沙赫塔赫马斯普交给奥斯曼使团，并与四个儿子一同被勒死。作为交出的回报，萨法维获得了重要的物质让步和边界保障。这次处决消除了塞利姆二世登基道路上最后的障碍，《阿马西亚条约》的和平秩序得以维持。", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["希俄斯从热那亚人手中夺取", "a4559b96"], "d": ["两百年来作为热那亚朱斯蒂尼亚尼家族的商业殖民地受其管辖、并向奥斯曼缴纳贡赋的希俄斯，以延误缴纳贡赋和为敌舰提供港口为由，被皮亚莱帕夏不发一弹地接收。随着希俄斯与伊普萨拉，爱琴海东岸最后的热那亚势力也被清除。希俄斯人的乳香生产及其特权得到保留，该岛划归白海群岛行省。", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["纳克索斯公国的并入——整个基克拉泽斯群岛", "68f0ec0b"], "d": ["自1207年存在、自1537年起向奥斯曼纳贡的拉丁纳克索斯公国，因末代公爵贾科莫·克里斯波压迫民众引来的申诉，以此为由被废除。纳克索斯、帕罗斯、安蒂帕罗斯、安德罗斯、锡罗斯、米科诺斯、伊奥斯、阿莫尔戈斯及其周围的全部基克拉泽斯诸岛，以一道决定直接归入奥斯曼管辖。苏莱曼大帝将诸岛的管理交给雅塞夫·纳西一段时间；三个半世纪的拉丁统治就此在爱琴海中央终结。", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["也门起义与科贾·锡南帕夏的也门战役", "c8218d8e"], "d": ["栽迪派伊玛目穆塔哈尔以强征赋税为由起事，把奥斯曼的管理从也门大部分地区驱逐。自伊斯坦布尔派出的科贾·锡南帕夏，于1568—1570年间的战役中，经长期围攻攻取凯夫凯班，重新建立了奥斯曼在该地区的统治。这次战役对保住红海南门和印度洋贸易路线的控制至关重要。", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["同亚齐苏丹国的防御同盟与印度洋援助", "8e835f24"], "d": ["面对葡萄牙进攻向立法者苏莱曼求援的亚齐使者，在苏丹于锡盖特瓦尔去世之后，把效忠献给了塞利姆二世，并与其签署了防御条约。苏丹下令自亚历山大送去火炮、步枪、弹药和工匠；十七艘战舰被准备派往印度海域。也门起义的扩大阻止了舰队启航，然而抵达亚齐的奥斯曼炮兵和工匠在该地区留下了持久的印记。", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["塞浦路斯登陆：利马索尔的攻占", "9074ccc9"], "d": ["登陆该岛的奥斯曼军队未遇多少抵抗便占领了利马索尔，次日转向拉纳卡。由于当地居民对威尼斯统治不满并协助奥斯曼部队，在拉纳卡也未遇严重抵抗；图兹拉码头被设为部队和装备的登陆基地。威尼斯将防御集中在尼科西亚和法马古斯塔；帕福斯的总督直到尼科西亚陷落之后才向统帅表示服从。", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["征服尼科西亚", "413d866b"], "d": ["自1570年7月25日开始、持续四十五天的围攻之后，塞浦路斯由威尼斯统治的首府尼科西亚向奥斯曼军队投降。该岛中心的陷落，使威尼斯的抵抗被压缩到法马古斯塔要塞。征服在西方引起巨大反响，并加速了在教皇领导下组建神圣同盟舰队的进程。", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["凯里尼亚的投降——塞浦路斯北岸", "39fdeea5"], "d": ["尼科西亚于9月9日在屠杀中陷落，粉碎了塞浦路斯北部的抵抗。位于五指山后的凯里尼亚城堡，得知首都的下场后八天，有条件地投降，守军被允许离岛。岛上的威尼斯旗帜只剩在法马古斯塔；而它也将再坚持十一个月。", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["勒班陀之后舰队的重建", "db51fe44"], "d": ["勒班陀惨败之后出任海军大臣的克勒奇·阿里帕夏，首要之务是重建遭受重创的舰队；船坞在1571—1572年冬季不停运转。1572年6月，由约250艘桨帆船和300艘志愿船长桨帆船组成的新舰队驶入地中海。这一迅速恢复表明，勒班陀并未持久地摧毁奥斯曼的海上力量。", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["同威尼斯的《伊斯坦布尔条约》——承认塞浦路斯", "4d08ef50"], "d": ["神圣同盟瓦解后陷于孤立的威尼斯，与奥斯曼单独媾和，正式承认塞浦路斯属于奥斯曼，并接受支付战争赔款。条约清楚表明，勒班陀的胜利并未给基督教世界带来政治上的收获。威尼斯此后七十年里避免与奥斯曼直接开战。", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["塞利姆二世去世", "c289f5ee"], "d": ["塞利姆二世跌倒之后约两个月未能临朝，随后去世。其死讯被宫中隐瞒了十二天，直到马尼萨的长子穆拉德抵达伊斯坦布尔。关于死亡日期，史料各异：塞拉尼基说12月15日；格拉赫、穆罕默德·本·穆罕默德和杰纳比说12月13日。", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["宣布塞利姆二世之死与穆拉德三世登基", "84334d70"], "d": ["塞利姆二世之死和自马尼萨召来的穆拉德三世的登基，于1574年12月22日被正式宣布。新苏丹将在位二十一年，其统治将以东方的长期伊朗战争、西方长期战争的前夜以及国内的阿克切贬值而著称。直到索库鲁·穆罕默德帕夏1579年去世之前，国家管理中的旧秩序一直延续。", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["瓦迪塞伊勒（大宫殿）之战——奥斯曼支持的阿卜杜勒·马利克歼灭葡萄牙军队", "21280dac"], "d": ["在奥斯曼支持下登上摩洛哥王位的阿卜杜勒·马利克，在瓦迪塞伊勒歼灭了葡萄牙国王塞巴斯蒂安的大军；因战斗中三位君主同时丧生，在西方史料中称作“三王之战”。葡萄牙的军事力量崩溃，该国不久后落入西班牙之手。阿卜杜勒·马利克也在战斗中去世；继位的其弟艾哈迈德·曼苏尔派使团向伊斯坦布尔通报了胜利。两国关系仍停留在互派使节和礼品的层面，而不是纳贡或臣属，不久后又因礼品问题而趋于紧张。", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["杰尔宾特民众向拉拉·穆斯塔法帕夏表示效忠——铁门并入奥斯曼统治", "9c55aeff"], "d": ["希尔万远征期间，一个由七人组成的杰尔宾特民众代表团前往位于埃雷什的统帅拉拉·穆斯塔法帕夏处表示效忠。封闭高加索山脉与里海之间狭窄通道的杰尔宾特（铁门），作为北方陆路的必经隘口，在希尔万的据守中起了关键作用。奥斯曼的统治在此持续到1607年。", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["希尔万的征服：沙马基的攻占", "9afae4c1"], "d": ["继瑟尔德尔胜利之后进军高加索的军队，进入了萨法维人在里海岸最富庶的省份希尔万，并攻占了中心城市沙马基。厄兹德米尔奥卢奥斯曼帕夏被任命为该地的贝勒贝伊，丝绸之路北线由此置于奥斯曼控制之下。希尔万将成为持续十二年的东方战争中易手最多、代价最高的战线。", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["巴库的攻占——抵达里海岸", "eb5adab8"], "d": ["作为希尔万行动的最后一环，里海西岸的巴库港被攻占。该城周边的石油井在当时就已是人所共知的收入来源，该港是经里海运来的伊朗丝绸的出口点。奥斯曼国家由此在其历史上第一次也是唯一一次成为里海的沿岸国。", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["埃里温（Erivan）的征服与城堡的修建", "7f623b7b"], "d": ["在卡尔斯接到前往埃里温并在那里修建城堡之命的费尔哈德帕夏向埃里温进军，该城于伊历991年斋月初（1583年9月中旬）被置于奥斯曼控制之下。在守住阿拉斯河谷北门的埃里温，一座新的大型城堡被修建起来；该城被设为贝勒贝伊区中心。位于卡尔斯与大不里士之间军路中途的埃里温，是东线后勤的脊梁。城堡修建得如此坚固，以至成为其后两百年奥斯曼—伊朗战争中不变的目标。", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["卡拉巴赫与占贾的并入", "29abaead"], "d": ["作为十年东方战争的最后收获，费尔哈德帕夏于1588年向占贾进军并于9月1日入城；库拉河与阿拉斯河之间的卡拉巴赫地区及其中心占贾被纳入奥斯曼统治。这样，希尔万、埃里温和卡拉巴赫连成一片，在高加索形成了一条不间断的奥斯曼战线。1590年签订的《费尔哈德帕夏条约》将确认这一边界，但这一收获仅能据守二十年。", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["攻取比哈奇", "651a7275"], "d": ["波斯尼亚总督泰利·哈桑帕夏于1591年11月攻取比哈奇的前沿要塞里帕奇之后，于1592年又夺取该城和要塞本身；经十日围攻后，指挥官兰贝格投降。这次征服把波斯尼亚边界沿乌纳河向前推进，也是一年后因泰利·哈桑帕夏在库尔帕前殉职而爆发的长期战争前夜奥斯曼最后一次重大收获。", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["奥斯曼—奥地利“长期战争”开始", "bd22c392"], "d": ["因波斯尼亚总督泰利·哈桑帕夏在库尔帕（锡萨克）前溃败殉职，奥斯曼国家向奥地利宣战，将持续十三年的长期战争开始。火器步兵起决定性作用的这场战争，加速了奥斯曼军队编制中塞克班和持枪士兵的使用，加深了提马尔西帕希的衰落。战争将于1606年以《吉特瓦托罗克条约》结束。", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["科贾·锡南帕夏出征奥地利——长期战争的第一次出征", "d4a2f46d"], "d": ["波斯尼亚总督哈桑帕夏在锡斯卡（锡萨克）前溃败殉职之后，大维齐尔科贾·锡南帕夏以华丽辞藻和许诺说服苏丹开战，率12000名近卫军及其他部队出发。将持续十三年的奥斯曼—奥地利战争的第一次出征由此展开。", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["征服亚诺什堡（杰尔）", "14b75207"], "d": ["大维齐尔科贾·锡南帕夏经一个多月的围攻，接收了被视为通往维也纳之路之锁的亚诺什堡。要塞陷落在欧洲引发巨大恐慌，并成为奥斯曼在长期战争中最辉煌的收获。然而该要塞只保住了四年。", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["穆拉德三世去世", "1b62e886"], "d": ["二十一年统治之后，穆拉德三世在瓦拉几亚军队焚烧布勒伊拉并延伸到锡利斯特拉的日子里去世，葬于圣索菲亚陵园。自马尼萨召来的其子穆罕默德三世十天后抵达伊斯坦布尔并登基（1595年1月27日）。", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["埃斯泰尔戈姆丧失于奥地利", "f420d333"], "d": ["在卡尔·冯·曼斯费尔德指挥的围攻中得不到足够援助的埃斯泰尔戈姆守军，把要塞交给了马蒂亚斯大公。随着五十二年的奥斯曼统治终结，多瑙河一线的防御链被打断，布达直接受到威胁。要塞要到十年后的1605年才得以收回。", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["征服埃格尔要塞", "3e511629"], "d": ["经三周的争夺，奥斯曼人此前一直未能攻下的坚固的埃格尔要塞，因守军投降而陷落。苏丹亲临的这次征服，在一定程度上弥补了丧失埃斯泰尔戈姆造成的士气，并建立了埃格尔省。随两周后取得的哈奇奥瓦大捷，1596年成为长期战争中奥斯曼最成功的一年。", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["丧失亚诺什堡（杰尔）", "b4ccc679"], "d": ["米克洛什·帕尔菲与阿道夫·冯·施瓦岑贝格统率的部队，以突袭炸开要塞城门，夺回了亚诺什堡。四年前科贾·锡南帕夏历尽辛苦所得的要塞的丧失，使奥斯曼在匈牙利的前沿阵线崩溃。同一年围攻布达的敌军虽被击退，战争的平衡渐渐变成消耗战。", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["卡拉亚泽吉·阿卜杜勒哈利姆起义", "30493b0d"], "d": ["召集长期战争中自军队逃亡的塞克班和勒文德的卡拉亚泽吉·阿卜杜勒哈利姆，控制了中安纳托利亚的广大地区，攻取乌尔法要塞（1599年11月），并以“哈利姆沙阿”的称号宣布称苏丹，发出带有自己花押的敕令。被视为大杰拉里浪潮第一位首领的卡拉亚泽吉死于1602年，运动由其弟疯子哈桑继续。起义是安纳托利亚农民大批放弃土地的“大逃亡”时期的开端。", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["蒂里亚基·哈桑帕夏防守卡尼萨", "d56a5e6a"], "d": ["想要夺回一年前被征服的卡尼萨的斐迪南大公及其盟军围攻该要塞两个多月；蒂里亚基·哈桑帕夏以9000人的兵力抵抗。尽管得不到外来援助，他击退了总攻，并以突围行动使敌人损失惨重而被迫撤退。这次防守在奥斯曼史学中成为史诗，“卡尼萨之围”本身成为一种文学体裁。", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["穆罕默德三世去世与艾哈迈德一世登基", "da735fde"], "d": ["穆罕默德三世于12月20日去世后，十四岁的其子艾哈迈德一世登上王位。作为幼年且未出任桑贾克而登位的第一位苏丹，表明王子在行省中培养的惯例事实上已经终结。艾哈迈德一世统治时期，放弃了杀兄弟的做法，转向“长者继承”（最年长男性成员继位）的原则。", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["收复埃斯泰尔戈姆", "7330f273"], "d": ["大维齐尔拉拉·穆罕默德帕夏围攻十年前丧失的埃斯泰尔戈姆，使其重新并入奥斯曼管理。同一次战役中佩斯和瓦茨也被解救，奥斯曼重整了在匈牙利的阵线。这一成就使次年在吉特瓦托罗克得以相对有力地坐上谈判桌；埃斯泰尔戈姆将留在奥斯曼手中直到1683年。", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["奥鲁奇平原大捷与镇压詹博拉特奥卢起义", "30f93532"], "d": ["在阿勒颇建立独立侯国并寻求与托斯卡纳结盟的詹博拉特奥卢阿里帕夏，被大维齐尔库尤朱·穆拉德帕夏在奥鲁奇平原彻底击溃。随着叙利亚中央权威重建，杰拉里浪潮最危险的一支被打破。库尤朱·穆拉德帕夏持续两年的残酷清洗，暂时保障了安纳托利亚的治安。", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["阿拉查伊尔大捷与镇压卡伦德尔奥卢起义", "55db0485"], "d": ["向马尼萨和布尔萨一带征收贡赋的杰拉里首领卡伦德尔奥卢，被库尤朱·穆拉德帕夏在阿拉查伊尔击溃，被迫逃往伊朗。凭这一胜利，安纳托利亚最后一支大型杰拉里军队被打散。据传库尤朱·穆拉德帕夏把被杀的叛乱者填入命人挖的井里，这种严酷清洗虽在短期内带来秩序，却无法弥补安纳托利亚的人口与生产损失。", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["首次授予荷兰特许状", "5d9d117e"], "d": ["荷兰联省共和国使节科内利斯·哈加，成功从艾哈迈德一世处获得与授予法国和英国范围相同的特许状。荷兰由此获得在伊斯坦布尔设使馆、在奥斯曼码头设领事馆并以自己的旗帜通商的权利。这份特许状象征着在地中海贸易中取代威尼斯的北方海上强国进入奥斯曼市场。", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["艾哈迈德一世去世与穆斯塔法一世登基——长者继承制", "9901c09e"], "d": ["在经历五十一天的胃病之后，二十八岁的艾哈迈德一世去世，其弟穆斯塔法一世取代其子被推上王位。由此，父传子的继承方式被放弃，事实上转入王朝最年长男性成员继位的“长者继承”制度。持续九十六天的这第一次统治，也是王子们在“笼子”中成长时代的开端。", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["穆斯塔法一世被废与年轻的奥斯曼（奥斯曼二世）登基", "e0f552f2"], "d": ["以精神状态不佳为由，穆斯塔法一世在九十六天后被废，艾哈迈德一世十四岁的儿子奥斯曼二世成为苏丹。据哈桑贝伊扎德的转述，在这一废黜决定中，黑人宦官总管穆斯塔法阿加起了作用。年轻的奥斯曼以废除近卫军军团并建立新军的方案，被视为奥斯曼改革争论中第一位激进的人物。这一方案四年后将使他丢了性命。", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["《萨拉夫条约》——与伊朗的和平续订", "e778aca8"], "d": ["普勒·舍凯斯泰溃败之后与伊朗达成的《萨拉夫条约》，在很大程度上确认了1612年《纳苏赫帕夏条约》的条件；萨法维每年送交的丝绸数量由二百驮减为一百驮。1603年以来的东方战争的第二阶段由此结束。和平并不长久，随着1623年巴格达的丧失，战争将重新燃起。", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["霍京战役与《霍京条约》", "bc4c823c"], "d": ["面对奥斯曼二世亲自指挥的大军，霍德凯维奇在霍京前建立的设防营地未能攻破，数月的进攻没有结果。依10月9日签署的条约，德涅斯特河被接受为边界，波兰人承诺阻止哥萨克袭击。尽管被宣称为胜利，却未能取得成果的这次战役，加深了年轻苏丹对近卫军的不信任和清洗军团的意图。", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["霍尔木兹自葡萄牙人手中夺取", "93e5f6cf"], "d": ["萨法维军队围攻并夺回了自1515年起在葡萄牙人手中的霍尔木兹；盖什姆岛以及沿海的甘伦（阿巴斯港）也归入萨法维统治，海湾贸易转移到新港口。", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["穆斯塔法一世第二次被废与穆拉德四世登基", "1b3a9e74"], "d": ["奥斯曼二世被杀之后第二次被推上王位的穆斯塔法一世，一年零三个月后再次被废，十一岁的穆拉德四世被宣布为苏丹。最初九年国家事实上由其母柯塞姆苏丹和宫廷要员管理。穆拉德四世自1632年起亲自接管政务，开启了严酷集权的时期。", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["巴格达丧失于萨法维", "db81be0c"], "d": ["在巴格达起事的贝基尔·苏巴什，经与萨法维的讨价还价，由守卫内堡的其子德尔维什·穆罕默德把该城交给了沙阿阿巴斯的军队。哈里发遗产的象征城市之一以及伊拉克大部分地区的丧失，在伊斯坦布尔引起极大愤慨。夺回巴格达，将在十五年间成为奥斯曼东方政策唯一的目标。", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["镇压阿巴扎·穆罕默德帕夏以埃尔祖鲁姆为中心的起义", "e6da2729"], "d": ["声称要为奥斯曼二世被杀报仇而反抗近卫军的埃尔祖鲁姆总督阿巴扎·穆罕默德帕夏，多年里控制东安纳托利亚并对抗中央。在大维齐尔胡斯雷夫帕夏围攻埃尔祖鲁姆之下被迫投降，获赦并被任命到波斯尼亚。起义的结束，是穆拉德四世得以出征伊朗的先决条件。", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["首位大穆夫提被处决：艾希扎德·侯赛因埃芬迪", "a60a58c5"], "d": ["以在军事动乱中进行调解、并向苏丹发出关于司法程序的书面警告为由，大穆夫提艾希扎德·侯赛因埃芬迪在比于克切克梅杰附近被处决。作为被处决的第一位奥斯曼大穆夫提，这打破了对乌理玛成员最重处罚是流放的悠久传统。该事件被视为穆拉德四世日趋严厉的权威以及国家—乌理玛平衡遭破坏的象征。", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["穆拉德四世征服埃里温", "b65a9b73"], "d": ["1635年3月28日自伊斯坦布尔出发的穆拉德四世，于7月28—29日围攻埃里温，8月8日接收要塞；随后进入已被放弃的大不里士，命人将该城毁坏。苏丹为纪念胜利，在托普卡帕宫修建了埃里温亭。这次战役是苏丹亲自指挥军队、隔三十年后第一次东方大战役。", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["埃里温丧失于萨法维", "fbb8dd25"], "d": ["奥斯曼军队撤走后，沙阿萨菲的军队围攻埃里温，在八个月内将其夺回。要塞如此迅速丧失，显示了在高加索实现持久统治在后勤上多么困难。埃里温也将依1639年《卡斯尔·希林条约》留给伊朗，奥斯曼将放弃对阿塞拜疆的主张。", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["重新征服巴格达", "4d2f27f3"], "d": ["1638年5月8日自伊斯坦布尔出发的穆拉德四世，经四十天的激烈围攻，夺回了十五年来处于萨法维手中的巴格达；围攻中维齐尔泰亚尔·穆罕默德帕夏殉职。该城的征服使奥斯曼统治在伊拉克得以重建，苏丹获得“巴格达征服者”称号。这次征服以次年的《卡斯尔·希林条约》而持久化，奠定了今日土耳其—伊朗边界的基础。", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["穆拉德四世去世与苏丹易卜拉欣登基", "e2ca1ca0"], "d": ["二十七岁（按回历为二十八岁）去世的穆拉德四世之后，王朝仅存的男性成员其弟易卜拉欣登上王位。多年生活在笼中的新苏丹统治期间，宫廷开支与宫内势力斗争动摇了国家秩序。八年后他被废黜并被杀，奥斯曼历史上第二次发生杀害苏丹之事。", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["自哥萨克手中收复亚速要塞", "e5fcf160"], "d": ["1637年被顿河哥萨克夺取的亚速要塞，在苏丹扎德·穆罕默德帕夏与克里米亚汗穆罕默德四世·吉莱的联合行动面前被放弃；哥萨克焚烧要塞后撤走。黑海北门的收复，结束了哥萨克袭击一直延伸到伊斯坦布尔海峡的危险时期。该要塞将于1696年被俄国沙皇彼得一世夺走。", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["克里特战役开始与征服干尼亚", "a1b0c77f"], "d": ["以马耳他海盗袭击奥斯曼朝觐船并躲入克里特为借口，向威尼斯宣战，由优素福帕夏统率的舰队在岛上登陆。经五十四天围攻后干尼亚要塞被攻占，在克里特建立了第一个持久的奥斯曼基地。奥斯曼历史上持续最久的战争由此开始；该岛要到二十四年后的1669年才被完全征服。", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["雷西姆诺的征服——克里特岛一分为二", "8f2c4353"], "d": ["哈尼亚被攻占一年之后，岛屿中部的雷西姆诺城堡也告陷落，克里特岛的西半部完全归入奥斯曼统治。威尼斯手中只剩首府干地亚和东端；该岛在二十三年间处于一分为二的状态。雷西姆诺的攻占成为开启干地亚围攻的一步——历史上最长的围攻就从这里开始。", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["克利斯丧失于威尼斯", "5473c22c"], "d": ["在克里特（干地亚）战争的达尔马提亚战线上，威尼斯指挥官莱昂纳多·福斯科洛的反攻也涉及自1537年起为桑贾克中心的克利斯；要塞转入威尼斯。奥斯曼倾全力于克里特，使达尔马提亚边界上的这一损失无法收回——克利斯再未回到奥斯曼管理之下；桑贾克中心迁往利夫诺。", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["围攻干地亚开始", "13016b10"], "d": ["攻取干尼亚和雷特蒙之后，奥斯曼军队围攻威尼斯在岛上最后的大据点干地亚。将持续二十一年的这次封锁，作为世界军事史上最长的围攻之一载入史册。围攻期间，威尼斯舰队封锁恰纳卡莱海峡的企图，把战争推向爱琴海的腹地。", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["太后柯塞姆苏丹被杀", "9d763f79"], "d": ["约六十二岁的柯塞姆苏丹，被依穆罕默德四世之母图尔汉苏丹之命行动的首席宦官乌宗·苏莱曼阿加及其手下，在后宫的一间屋中发现并杀害。在三位苏丹时期主导国家政策的这位强势王朝女性之死，被视为所谓“女人苏丹国”时期事实上的终结。空出的权威，为五年后柯普吕律·穆罕默德帕夏以非常权限出任大维齐尔开辟了道路。", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["恰纳卡莱溃败与丧失博兹贾岛及利姆诺斯", "e01a1f7e"], "d": ["威尼斯海军上将莫琴尼戈于1656年6月在恰纳卡莱海峡前取得的大海战胜利，几乎全歼了奥斯曼舰队；随后博兹贾岛、利姆诺斯和萨莫色雷斯被占领。随着海峡陷入威尼斯封锁，伊斯坦布尔的食品价格飞涨，对首都遭袭的恐惧蔓延。这一灾难，是1656年9月柯普吕律·穆罕默德帕夏以附带条件的非常权限出任大维齐尔的直接原因。", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["恰纳卡莱大捷与收复博兹贾岛", "603da863"], "d": ["柯普吕律·穆罕默德帕夏动员的舰队于1657年7月19日在海峡前击溃威尼斯舰队；随后库尔德帕夏统率的部队于8月25日收回博兹贾岛，8月30日威尼斯人完全撤出该岛。11月利姆诺斯也被解救，恰纳卡莱封锁被打破，伊斯坦布尔的粮食通道重新打开。柯普吕律亲自渡往该岛命人修复防御工事；这一成就是柯普吕律时代的第一次重大军事收获。", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["利姆诺斯自威尼斯手中收回", "a4c3c69b"], "d": ["1656年7月被威尼斯攻占的利姆诺斯，于1657年11月回到奥斯曼手中。", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["征服雅诺（伊内乌）与特兰西瓦尼亚战役", "d1089616"], "d": ["为惩罚擅自出征波兰、违背奥斯曼庇护的特兰西瓦尼亚亲王乔治二世·拉科齐而出征的柯普吕律·穆罕默德帕夏，经贝尔格莱德行进，攻取战略要塞雅诺。向特兰西瓦尼亚任命了新亲王，藩属关系被严厉地重申。这次战役是奥斯曼重建在中欧权威尝试的第一环。特兰西瓦尼亚本就是臣属于奥斯曼的公国；雅诺的攻取并非自外国夺取之征服，而是把臣属的特兰西瓦尼亚的这座要塞自公国管理中取出，直接隶属奥斯曼桑贾克；公国其余部分仍保持藩属地位。", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["镇压阿巴扎·哈桑帕夏起义", "4ba74321"], "d": ["针对柯普吕律·穆罕默德帕夏严厉的清洗，得到安纳托利亚总督和塞克班首领们支持的阿巴扎·哈桑帕夏，要求撤换大维齐尔，发动了一场大规模起义。起义在阿勒颇被镇压，首领被除掉；这是各地帕夏对抗中央的最后一次集体抵抗。柯普吕律的权威由此无可争议，大维齐尔之职重新升为国家真正的执行中心。", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["征服瓦拉德（奥拉迪亚）", "0e6ad300"], "d": ["在对向奥斯曼宣战的特兰西瓦尼亚亲王乔治二世·拉科齐的战役框架内，瓦拉德要塞和城市被攻占。随着特兰西瓦尼亚关键要塞之一陷落，该地区建立了新的奥斯曼行省（瓦拉德省）。征服使哈布斯堡警觉，成为三年后开始的奥斯曼—奥地利战争的直接原因之一。同日并入的其他地方：瓦拉特。这里同样没有自外国夺取土地：特兰西瓦尼亚本就是臣属的奥斯曼公国；瓦拉德成为行省，只是把该城的管理自臣属公国手中取出并直接隶属苏丹，正如两年前的雅诺一样。", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["圣哥达会战", "61ebc1f2"], "d": ["渡过拉布河的奥斯曼军队，被蒙特库科利统率的欧洲联军拦阻，损失惨重。会战因首次明确展示纪律严明的火器步兵齐射对奥斯曼骑兵冲锋的优势，被视为军事史上的转折点。尽管失败，奥斯曼仍在九天后签署的《瓦斯瓦尔条约》中争取到了有利条件。", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["《瓦斯瓦尔条约》", "089c978c"], "d": ["尽管有圣哥达的溃败仍签署的条约，规定乌伊瓦尔与瓦拉德留在奥斯曼，特兰西瓦尼亚在奥斯曼庇护下保持中立，奥地利支付20万库鲁什的“礼物”。这一为期二十年的和平，是战败一方在谈判桌上获益的少见范例。条约在哈布斯堡舆论中引起的不满，将助长中匈牙利运动，并间接助长1683年出征维也纳。", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["阿尔及尔开始“代伊”统治", "e99faa51"], "d": ["阿尔及尔军团与海盗船长团体（塔伊法·雷伊斯）废黜了最后一位阿加，选举哈吉·穆罕默德为终身代伊。此后统治阿尔及尔的不是伊斯坦布尔任命的总督，而是本地军团从内部选出的代伊；奥斯曼的联系仅限于在呼图白中诵读苏丹之名、军旗和出征义务。阿尔及尔由此从行省变成军团辖地——突尼斯在1705年随侯赛因王朝、的黎波里塔尼亚在1711年随卡拉曼利王朝经历了同样的转变。", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["波兰战役开始——穆罕默德四世与法吉勒·艾哈迈德帕夏统军", "75e15a39"], "d": ["针对进入奥斯曼庇护的乌克兰盖特曼彼得罗·多罗申科，波兰的进攻持续，伊斯坦布尔要求波兰国王放弃进攻；没有得到肯定答复，遂决定出征波兰。大维齐尔法吉勒·艾哈迈德帕夏率有苏丹同行的军队于1672年6月4日向波兰进发。战役将以征服卡缅涅茨与《布恰奇条约》告终。", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["征服卡缅涅茨与建立波多利亚省", "c3f4f6d0"], "d": ["经九天围攻后，被视为波兰东部最强要塞的卡缅涅茨被接收；穆罕默德四世于9月2日在由大教堂改建的清真寺中做了第一次聚礼。要塞被定为中心，建立了波多利亚省，奥斯曼旗帜在今日乌克兰土地上抵达最北端。卡缅涅茨将在1699年《卡尔洛维茨条约》之前一直是帝国的西北端。", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["卡拉·穆斯塔法帕夏自波兰接收乌曼", "0d3543a0"], "d": ["被派去对付波兰的卡拉·穆斯塔法帕夏，接收了波兰手中的要塞乌曼；该城在奥斯曼管理下留到卡尔洛维茨。", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["征服奇赫林要塞", "a17cedd0"], "d": ["继前一年梅莱克·易卜拉欣帕夏未获结果的行动之后，大维齐尔梅尔济丰卢·卡拉·穆斯塔法帕夏亲自指挥围攻设防的奇赫林要塞（7月19/21日），并于8月21日攻占。作为乌克兰哥萨克盖特曼国之上奥斯曼—俄国竞争之象征的要塞陷落，迫使俄国求和。这一成就也是梅尔济丰卢转向维也纳的自信的来源之一。", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["《巴赫奇萨赖条约》——同俄国的第一次正式和平", "df82bc0b"], "d": ["继奇赫林战役之后，经克里米亚汗斡旋的谈判最终，以第聂伯（厄泽）河为界，奥斯曼国家与俄国之间签署了二十年的和约。这是两国之间第一份全面的条约，被视为奥斯曼—俄国关系的起始文献。凭借和平，东线得到保障，军队得以转向中欧。", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["授予特克利·伊姆雷中匈牙利王国敕书", "3cd8d51d"], "d": ["为反抗哈布斯堡压力而起事的新教匈牙利贵族特克利·伊姆雷，自1682年4月起开始被视为“中匈牙利当选国王”，9月16日布达总督易卜拉欣帕夏向他献上了亲王的标志。奥斯曼庇护之下由此建立了一个新的藩属匈牙利国家。这一干预使与奥地利的战争无法避免，开启了通往次年第二次围攻维也纳的链条。", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["阿亚毛夫拉（莱夫卡斯）丧失于威尼斯", "e6905fee"], "d": ["加入神圣同盟的威尼斯舰队，炮击该城之后占领了爱奥尼亚海中的阿亚毛夫拉岛。同一年随着普雷韦扎也告陷落，奥斯曼在亚得里亚海口的控制被打破。这些损失是莫罗西尼三年内夺取整个摩里亚的战役的开端步骤。", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["科伦丧失于威尼斯", "2ed762bc"], "d": ["莫罗西尼统率的威尼斯军队夺取摩里亚半岛西南端的科伦要塞；该城此后将在威尼斯管理下留三十年。科伦陷落是威尼斯夺取摩里亚战役的第一个重大收获。要塞直到1715年才由希拉赫达尔·阿里帕夏统率的奥斯曼军队收回。", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["雅典的收复——威尼斯的撤出", "03393b46"], "d": ["1687年9月炮击卫城并炸毁帕特农神庙的莫罗西尼，在雅典度过冬天之后意识到无法在该城立足。由于瘟疫、补给困难以及奥斯曼军队的恢复，威尼斯守军撤出该城，退往摩里亚。雅典由此未经战斗重新回到奥斯曼统治之下，但帕特农神庙所遭受的毁坏无法挽回。", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["利波瓦（Lippa）向卡拉法投降——落入奥地利之手", "7f0a8d38"], "d": ["经安东尼奥·卡拉法三天的围攻后，利波瓦于1688年6月12至22日间投降，落入奥地利之手。奥斯曼人后来夺回该城，奥地利于1691年再度占领；1695年的远征中奥斯曼重新夺得控制。同日在地图上自奥斯曼转归哈布斯堡的其他居民点：阿拉德和维拉戈什（Şiria）。关于阿拉德，来源只给出年份（MKL，阿拉德：1551至1688年间在奥斯曼手中）；日期取自利波瓦，维拉戈什沿袭阿拉德的链条（声明为近似）。", "0dfcf5af"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["击退威尼斯对埃维亚的围攻", "aae7e6a0"], "d": ["夺取摩里亚之后转向爱琴海的莫罗西尼，试图以持续三个多月的围攻攻取埃维亚；但在1687—1688年冬季加固的防御工事和守军的抵抗面前，他损失惨重而被迫撤退。这次失败阻止了威尼斯在爱琴海的推进，并动摇了莫罗西尼的军事威望。埃维亚在卡尔洛维茨也将留在奥斯曼手中。", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["卡尼萨要塞丧失于奥地利", "553b45f3"], "d": ["自1690年1月起处于6万人哈布斯堡军队严密封锁之下的卡尼萨，在数月得不到援助的抵抗之后，凭最后一任守将穆斯塔法帕夏签署的投降协议而丧失。曾因蒂里亚基·哈桑帕夏史诗般的防守而得名的这座要塞，九十年的奥斯曼统治就此终结。卡尼萨的丧失，是奥斯曼在匈牙利西部最后一个大据点的崩溃。", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["苏莱曼二世去世", "d2478080"], "d": ["在笼中度过约四十年后于1687年登基的苏莱曼二世，在带病观看军队准备之际，于1691年6月22日星期五中午前后在埃迪尔内去世；其统治持续三年八个月零两天。大维齐尔预先下达了一旦苏丹去世便拥立其弟艾哈迈德登基所需的指示。葬礼祈祷当天在阿莱宫亭举行；其遗体被运往伊斯坦布尔，安葬于苏莱曼大帝陵墓中他的右侧。", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["艾哈迈德二世登基", "52947b14"], "d": ["苏莱曼二世去世后，四十九岁的其弟艾哈迈德二世在埃迪尔内登基。其统治恰逢神圣同盟战争最艰难的年头；登基两个月后，在萨兰卡门大维齐尔法吉勒·穆斯塔法帕夏殉职。与此同时，其时期开始实施的终身包税制，成为改变奥斯曼财政长期结构的最重要措施之一。", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["穆罕默德四世在埃迪尔内去世", "17388b7e"], "d": ["1687年被废黜的猎人穆罕默德，在苏莱曼二世1689年的匈牙利远征期间被带到埃迪尔内，并目睹了另一位兄弟艾哈迈德二世的统治。他在这座他十分喜爱的城市去世。其遗体被运回伊斯坦布尔，安葬于其母图尔汉苏丹在新清真寺旁的陵墓。", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["艾哈迈德二世在埃迪尔内去世", "c6306c08"], "d": ["统治四年均在战争中度过的艾哈迈德二世，在五十二岁时因水肿（istiskā）在埃迪尔内去世。其遗体被运回伊斯坦布尔，安葬于苏莱曼大帝陵墓。其侄穆斯塔法二世继位。", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["巴士拉被伊朗人占领", "a9cdf3a3"], "d": ["当奥斯曼国家在西线忙于神圣同盟战争时，巴士拉在1690年瘟疫之后，先是遭到穆坦非克谢赫马尼的洗劫，随后又遭到胡韦泽汗费雷丘拉的洗劫。伊朗人利用这一混乱，于1696年占领该城，并在巴士拉留下一支守军。", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["《伊斯坦布尔条约》——把亚速让给俄国", "79db4724"], "d": ["在卡尔洛维茨与俄国只能订立两年的停战；持久和平是在伊斯坦布尔经一年半艰难谈判后签署的。奥斯曼国家把1696年丧失的亚速要塞及其周边土地正式让给俄国，放弃了克里米亚汗每年从莫斯科获得的贡赋。作为回报，俄国获得在伊斯坦布尔设常驻使节的权利；俄国在黑海北岸的存在由此在法理上得到登记。", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["达尔塔班·穆斯塔法帕夏收复库尔内和巴士拉", "7adb777d"], "d": ["《卡尔洛维茨条约》之后被任命为巴格达总督和巴士拉塞尔阿斯凯尔的达尔塔班·穆斯塔法帕夏，率领阿勒颇、拉卡、锡瓦斯和卡拉曼的部队以及从比雷吉克顺流而下的河上舰队向南进军。周边的部落谢赫们一个个臣服，伊朗的巴士拉守将达乌德汗弃城而去，库尔内和巴士拉重新归入奥斯曼统治。", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["穆斯塔法二世去世", "626c394d"], "d": ["因埃迪尔内事件把王位让给其弟艾哈迈德三世的穆斯塔法二世，在被废黜约五个月之后，在他十分喜爱的埃迪尔内去世。其病情又添了对近来事态的忧伤。一些西方来源记述，民间普遍认为他是被毒死的。", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["巴格达开始马穆鲁克（奴隶军）统治", "abe52618"], "d": ["随着格鲁吉亚裔的哈桑帕夏出任巴格达总督，伊拉克由中央任命的总督，转入自己奴隶出身的统治阶层主导的时期。随着苏莱曼帕夏1749年出任总督，该体制得到进一步稳固，奥斯曼朝廷不再能任命自己想要的人，而是不得不任命已掌握实力的奴隶出身者之一。这一半自治结构虽在防御伊朗边界方面发挥了作用，却在一个半世纪里削弱了中央权威对伊拉克的控制。", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["突尼斯建立侯赛因王朝", "cb1a98f9"], "d": ["在阿尔及尔军队入侵突尼斯所引发的权威真空中，突厥裔西帕希总管侯赛因·本·阿里夺取了贝伊之位，并表示效忠奥斯曼苏丹以获得合法性。他所建立的王朝在1705—1735年与1756—1957年间统治突尼斯；贝伊世袭制取代了军团管理。由此，西部诸军团辖地中隶属中央而事实自治的王朝结构的第一个范例诞生。", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["自西班牙人手中攻取瓦赫兰（奥兰）与米尔斯克比尔", "b67ce06a"], "d": ["阿尔及尔军团总督的军队，经长期围攻，夺取了两个世纪来在西班牙守军手中的瓦赫兰及其港口米尔斯克比尔。这是西地中海奥斯曼庇护下的西部军团辖地对西班牙取得的最大成就，保障了阿尔及尔的西翼。该城将在1732年再度遭西班牙占领，而在1792年被最终收回。", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["《普鲁特条约》——收回亚速与塔甘罗格", "bac5d2a1"], "d": ["随着在普鲁特河畔被围的俄军投降而签署的七条条约，规定亚速要塞连同其土地和军需一并归还奥斯曼。塔甘罗格、卡缅卡和耶尼卡莱诸工事将被拆毁，双方不得在这些地区再建新要塞。彼得一世十六年间在沃罗涅日和亚速所建立的舰队与基地体系崩溃；俄国出海的进程推迟了约五十年。", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["的黎波里塔尼亚建立卡拉曼利王朝", "e1105d4a"], "d": ["在为军团阿加们的争斗所困的的黎波里塔尼亚，骑兵军官艾哈迈德·卡拉曼利夺取了管理权，并凭自伊斯坦布尔获得的总督敕书使地位正式化。经艾哈迈德帕夏、其子穆罕默德帕夏和其孙优素福帕夏之手，产生了一个延续于1711—1835年间的王朝；出现了建立自己舰队、同欧洲国家直接签约的半独立结构。这一时期要到1835年行省被直接隶属中央才告结束。", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["同俄国的《埃迪尔内条约》", "14901a70"], "d": ["因普鲁特所许诺的事项未能履行，又两次宣战，最终在俄国接受承诺之后，在埃迪尔内签署了持久和平。条约确认了普鲁特的条件；俄国将不干预波兰事务，将自哥萨克土地撤出，并不得阻挠瑞典国王铁头查理返回本国。北线由此结束，使奥斯曼国家得以把目光转向摩里亚和威尼斯战线。同日并入的其他地方：霍京。", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["向威尼斯宣战——准备摩里亚战役", "d970b122"], "d": ["以威尼斯支持黑山叛乱者、扣押奥斯曼商船以及以重税压榨在卡尔洛维茨所得的摩里亚为由，在御前会议上作出开战决定。大维齐尔希拉赫达尔·达马德·阿里帕夏所准备的这次战役，将于次年在不到一百天内收回整个摩里亚半岛。然而这一成就将促使奥地利行动，并为1716年更为沉重的战争打开大门。", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["伊斯滕迪尔（蒂诺斯岛）：威尼斯在爱琴海最后一个岛屿的投降", "4abec891"], "d": ["出征摩里亚的舰队，在途中停泊在威尼斯在爱琴海仅剩的一个岛屿伊斯滕迪尔之前。尽管纳克索斯公国于1566年陷落，该岛凭借拉丁人口又悬挂了一百五十年的威尼斯旗帜，经短暂围困后不流血投降。这样，威尼斯在爱琴海的最后足迹被抹去，该海完全成为奥斯曼的内海。", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["纳夫普利翁的征服——摩里亚的关键城堡", "62a5808a"], "d": ["威尼斯在摩里亚的首府和最强大的要塞纳夫普利翁，在帕拉米迪堡垒经九天炮击后被攻占而陷落。城堡如此迅速的陷落粉碎了半岛其余地方的抵抗。在卡尔洛维茨丧失的摩里亚的收复，实际上在此完成。同日在地图上从威尼斯转至奥斯曼的另一处居民点：阿尔戈斯——沿袭纳夫普利翁的“兄长中心”链条（TDV anabolu；声明为近似）。", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["莫东的投降", "43faa909"], "d": ["纳夫普利翁陷落之后，位于摩里亚西南端的莫东城堡，遭到陆上军队和海上舰队的围攻，很快投降。威尼斯在东地中海远航中使用了两百年的这个港口，是船只取水和补给的必经停靠点。它的丧失终结了威尼斯舰队在爱琴海的机动能力。", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["科龙的投降——摩里亚远征的完成", "e4b9c8a4"], "d": ["随着扼守梅塞尼亚湾口的科龙城堡投降，威尼斯在摩里亚半岛的统治彻底终结。在卡尔洛维茨丧失的半岛，在远征开始仅三个月后便被完全收复。在同一次远征的延续中，1715年9月伊奥尼亚海上的阿亚马夫拉（莱夫卡达）岛也从威尼斯手中夺取。这一速度迫使威尼斯把奥地利拉入战争，三年后通向帕萨罗维茨的道路由此打开。", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["丘哈岛（基西拉岛）的攻占", "494de6c6"], "d": ["位于摩里亚南端的丘哈岛，在半岛完成之后被舰队接收。监视伊奥尼亚海与爱琴海之间通道的这座岛屿，是威尼斯用来控制这片海域的前哨。然而它并未成为长期据守的唯一奥斯曼岛屿：三年后在帕萨罗维茨被还给了威尼斯。", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["奥地利与威尼斯结盟——1716—1718年奥斯曼—奥地利战争的大门", "99511ca2"], "d": ["奥斯曼自威尼斯手中收回摩里亚之后，奥地利声称《卡尔洛维茨条约》遭到违反，与威尼斯签订了同盟条约；欧根亲王在致大维齐尔的信中要求归还从威尼斯夺取的地方。在达乌德帕夏营地的商议中，在大维齐尔阿里帕夏的压力下，对奥地利宣战，并为此自大穆夫提处取得了教令。", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["大维齐尔阿里帕夏出征奥地利", "2fbdce42"], "d": ["对奥地利宣战之后，大元帅阿里帕夏以超过10万人的军队出征奥地利；舰队则于同年夏季转向科孚岛。军队将自贝尔格莱德向瓦拉丁进军，大维齐尔将在8月初的溃败中殉职。", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["瓦拉丁（彼得罗瓦拉丁）溃败——达马德·阿里帕夏殉职", "265c1d81"], "d": ["经贝尔格莱德渡过多瑙河的奥斯曼军队，在瓦拉丁前同欧根亲王统率的奥地利军队遭遇；起初近卫军的冲锋冲击了敌人的壕沟，但随着骑兵翼的崩溃，阵线溃散。大维齐尔希拉赫达尔·达马德·阿里帕夏额头中弹殉职，营地和炮兵全部落入敌手。奥斯曼编年史称之为“瓦拉丁之年”的这场溃败，是通向泰梅什瓦尔丧失以及次年贝尔格莱德丧失的链条的第一环。", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["围攻科孚岛以失败告终", "b2aa7011"], "d": ["摩里亚统帅卡拉·穆斯塔法帕夏自陆路、海军大臣詹姆·霍贾·穆罕默德帕夏以舰队自海路攻打科孚岛；该岛是威尼斯在亚得里亚海的关键基地。然而要塞极为坚固的工事、威尼斯舰队带来的增援以及自多瑙河战线传来的溃败消息，导致围攻解除。未能攻取科孚岛，浇灭了因再次征服摩里亚而高涨的气氛，并使战争重心转向匈牙利。", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["泰梅什瓦尔（蒂米什瓦拉）丧失于奥地利", "27fe1365"], "d": ["瓦拉丁溃败之后，欧根亲王直接向泰梅什瓦尔进军，要塞在持续四十多天的围攻之后，以炸药方式被迫交出。1552年在立法者时代被征服、作为总督区中心一百六十四年来被视为匈牙利防御东部支柱的这座城市，就此丧失。随着泰梅什瓦尔陷落，巴纳特地区全部转入奥地利，奥斯曼边界被推向多瑙河以南。同日地图上由奥斯曼转入哈布斯堡的其他定居点：察科瓦尔、法切特和卡兰塞贝什（Caransebeş）——随泰梅什瓦尔省的转移（TDV timisvar；地点层面的日期史料中没有，沿用“大哥中心”链条，有声明的近似）。", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["哈拉姆（新帕兰卡）要塞交给奥地利——巴纳特多瑙河沿岸丧失", "38ee4c6d"], "d": ["泰梅什瓦尔陷落之后受命夺取巴纳特其余地区的奥地利骑兵上将梅尔西，于11月14日向多瑙河畔的哈拉姆（新帕兰卡）进军；16日抵达要塞时，200人的奥斯曼守军以升白旗、自由撤出为条件投降。于是自1552年起在奥斯曼手中的南巴纳特的多瑙河一线也转入奥地利。同日地图上由奥斯曼转入哈布斯堡的另一定居点：韦尔谢茨——沿用哈拉姆这一“大哥中心”的链条（班拉基0019/1703；有声明的近似）。", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["《帕萨罗维茨条约》——摩里亚得到，贝尔格莱德和巴纳特丧失", "d46aa216"], "d": ["摩里亚已从威尼斯手中收回，但参战的奥地利凭借在彼得罗瓦拉丁和贝尔格莱德取得的胜利在谈判桌上占了上风。在英国和荷兰调停下签订的条约把摩里亚留给奥斯曼，作为交换，北塞尔维亚连同贝尔格莱德、巴纳特和小瓦拉几亚被让给奥地利；用TDV的话说“北波斯尼亚完全让给了奥地利”——萨瓦河沿线的波斯尼亚杜比察和波斯尼亚布罗德等城堡，在地图上自此日起转归奥地利（确切边界由委员们逐一划定，TDV并未逐一列出这些城堡的名称）；而威尼斯则保留了伊奥尼亚海岸的普雷韦扎和丘哈等据点。同日签订的通商敕约，使奥地利货物所缴关税由百分之五降为百分之三。条约确认了奥斯曼国家在中欧的退却，同时它所开创的二十七年和平为郁金香时代（1718至1730年）奠定了基础：在内夫谢希尔的达马德·易卜拉欣帕夏主政下的首家奥斯曼印刷所（1727年，易卜拉欣·穆特费里卡）、翻译委员会、天花接种观察和新的宫廷文化生活，都是这些和平岁月的产物。同日在地图上易手的其他居民点：克拉约瓦（Craiova）、拉姆尼库沃尔恰（Râmnicu Vâlcea）和塞维林堡（小瓦拉几亚／奥尔泰尼亚，自奥斯曼转归奥地利），以及阿亚马夫拉（莱夫卡达）（自奥斯曼转归威尼斯；TDV ayamavra：1718年根据《帕萨罗维茨条约》该岛被让给威尼斯）。在小瓦拉几亚还有特尔古日乌（Târgu Jiu）转归奥地利；沃尼察（Vonitsa，TDV pasarofca-antlasmasi）和丘哈岛（基西拉岛，TDV cuka-adasi：《帕萨罗维茨条约》第3条）转归威尼斯。", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["东方战役：攻取第比利斯与伊朗战争开始", "78343dc2"], "d": ["随着萨法维国家因阿富汗人入侵而崩溃以及俄国向里海沿岸推进，奥斯曼国家为使真空不完全落入俄国势力，向东派出军队。第比利斯被攻取，格鲁吉亚并入奥斯曼管理；随后向占贾、埃里温和纳希切万方向的推进继续。在郁金香时代和平外表之后进行的这次战役，成为将持续十三年、并最终以所得之地全部归还而告终的长期东方征战的开端。", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723年伊朗远征：进入希尔万和格鲁吉亚", "c81189fc"], "d": ["萨法维国家因阿富汗入侵而崩溃之后，以防止俄国下到里海沿岸为由向东出征。埃尔祖鲁姆军队经格鲁吉亚进入第比利斯，希尔万一路则进入沙马基，收回了一百三十年前丧失的土地。这次远征成为奥斯曼在高加索的最后一次大规模推进。", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["克尔曼沙汗的攻占——扎格罗斯之门", "ad14799f"], "d": ["巴格达军队越过扎格罗斯山口，占领了被视为伊朗西门的克尔曼沙汗。该城位于从巴格达通往伊斯法罕的商队和军队道路上，其攻占保障了伊拉克省的东部安全。这次推进在瓦解的萨法维国土上开启了奥斯曼与俄国之间的瓜分竞赛。", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["《伊斯坦布尔分割条约》——与俄国瓜分伊朗", "fce8eec2"], "d": ["为避免奥斯曼与俄国在崩溃的萨法维国土上对峙，经法国使节斡旋签署了一份瓜分条约。里海的西岸与南岸留给俄国，格鲁吉亚、设尔凡、阿塞拜疆和西伊朗城市留给奥斯曼国家。这一在纸面上看似巨大收获的瓜分，不久之后因纳迪尔沙阿的崛起而事实上失效。依条约，沙卜兰和穆什库尔等设尔凡的富庶土地留在俄国一方（恰伊乔卢，DergiPark）。", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["纳希切万的攻占", "bdf14d0a"], "d": ["沿阿拉斯河推进的奥斯曼部队攻占了纳希切万和奥尔杜巴德；朱尔法也并入纳希切万利瓦。该城作为伊朗的西北之门，被划归新建的埃里温行省。这样，奥斯曼边界重新抵达了苏莱曼大帝时代的最东线。", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["哈马丹的征服", "e1339a97"], "d": ["从克尔曼沙汗向东进军的军队，经长期围攻后攻占了位于伊朗高原西缘的哈马丹。该城是通往伊斯法罕之路的最后一个大站，而伊斯法罕是奥斯曼军队自两伊拉克远征以来所能抵达的最东点。同年与俄国签订的《伊斯坦布尔协定》，将瓦解的伊朗在奥斯曼与俄国之间的瓜分形诸纸面。", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["埃里温的再度征服", "88acabef"], "d": ["经过持续九十天的艰苦围攻，阿拉斯河谷的关键城堡埃里温重新归入奥斯曼统治。1583年修建、1604年丧失的这座城堡，这次以更强的守军加固。围攻之漫长，表明奥斯曼军队已不再轻易推进。卡尔皮（乌奇克利塞）、舍吕尔、马库和许雷盖尔诸纳希耶也划归埃里温行省。", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["攻占大不里士——占领阿塞拜疆", "e502a4f7"], "d": ["一年前尝试失败之后再次被围攻的大不里士，经逐街持续的激烈会战，向奥斯曼军队投降。隶属大不里士省的马兰德、马拉盖和苏武克布拉克（马哈巴德）也进入奥斯曼管理。同一年洛里、占贾、阿尔达比勒和胡拉马巴德也被攻取，《伊斯坦布尔分割条约》中分给奥斯曼的地区被事实占领。在东方达到的这一广度，是费尔哈德帕夏条约时代之后最远的边界；然而保住它给军队与国库带来了沉重负担。", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["占贾的征服——高加索远征的终结", "875bca7a"], "d": ["作为高加索行动最后目标的占贾，作为库拉河与阿拉斯河之间卡拉巴赫的中心被接收。随着希尔万、埃里温、纳希切万和占贾一线的完成，奥斯曼国家在高加索达到了1590年时的版图。然而这一收获是短命的：纳迪尔沙的崛起将在十年内夺回整个地区。", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["《哈马丹条约》——西伊朗并入奥斯曼", "94a29dc3"], "d": ["依与阿富汗君主阿什拉夫沙阿签署的条约，持续四年的战争结束，奥斯曼国家所占的西伊朗土地在法理上得到承认。阿什拉夫沙阿作为回报接受奥斯曼苏丹的哈里发地位，并承担在伊朗以苏丹之名宣读呼图白。这一外交胜利是短命的；纳迪尔沙阿1730年发动的反攻，几年内便抹去了条约的所得。", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["哈基姆奥卢·阿里帕夏攻占鲁米耶", "eac7f64d"], "d": ["在伊朗远征中，哈基姆奥卢·阿里帕夏先攻占乌尔米耶（鲁米耶），随后于1731年11月15日攻占已让给奥斯曼的大不里士。TDV未给出乌尔米耶的攻占日期；只知其年份且在大不里士之前。", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["《艾哈迈德帕夏条约》——归还西伊朗大部", "590d839f"], "d": ["纳迪尔沙阿在梅拉耶尔取得的胜利和接连而来的伊朗进攻之后，巴格达总督艾哈迈德帕夏未与中央商议便签署了一份和约。依条约，阿拉斯河被接受为边界；哈马丹、克尔曼沙赫、阿尔达兰、阿尔达比勒和大不里士等西伊朗城市归还伊朗，占贾和第比利斯留在奥斯曼。在伊斯坦布尔遭到反对的这份文本，也被纳迪尔沙阿认为不够，1732年尚未过完战争便重新燃起。地图还把沿用霍伊链条的科图尔视为在这一天由奥斯曼转入萨法维（TDV hoy；科图尔具体的日期史料中没有——有声明的近似）。", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["瓦赫兰（奥兰）再度丧失于西班牙", "20485027"], "d": ["西班牙国王腓力五世派出的大登陆舰队，在蒙特马尔伯爵指挥下抵达瓦赫兰城下，击溃阿尔及尔军团的军队并夺回该城。二十四年前被征服的这座港口，又将在西班牙守军手中留六十年。显示西部军团辖地力量局限的这一损失，直到1792年最终征服瓦赫兰才得以弥补。", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["按欧洲方式改革炮兵军团与建立炮兵工厂", "d980cf2a"], "d": ["进入奥斯曼服务的法国裔炮兵艾哈迈德帕夏，在大维齐尔赫基姆奥卢·阿里帕夏的支持下，把炮兵军团改为领薪并按欧洲方式编制的部队。对自波斯尼亚征募的三百名士兵，以算学和几何为基础施以正规训练；为组织、装备和退休制定了新章程，以现代技术制造了一百门炮弹炮和五万枚炮弹。教授几何学的炮兵工厂，被视为奥斯曼现代军事工程教育的第一个核心。", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["艾哈迈德三世去世", "455f7fba"], "d": ["因1730年帕特罗纳·哈利勒起义被废黜的艾哈迈德三世，在托普卡珀宫专供被废黜苏丹居住的寓所度过了生命的最后六年，在六十三岁时去世。他被安葬于巴赫切卡普新清真寺旁其祖母图尔汉苏丹的陵墓。", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["《伊斯坦布尔条约》——南高加索让给伊朗", "8c205aab"], "d": ["持续四年的第二次伊朗战争，在阿尔帕恰伊溃败和占贾与第比利斯丧失之后，以签署的条约告终。奥斯曼国家自1723年以来夺取的全部南高加索与西伊朗土地中撤出，边界回到1639年《卡斯尔·希林》一线。十三年东方战役的遗产是沉重的财政负担和空虚的国库；而对于与俄国开始的新战争而言，东线的关闭是一项至关重要的收获。", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["奥奇夫（奥恰科夫）要塞丧失于俄国", "f93e61f3"], "d": ["明尼希元帅统率的俄军围攻第聂伯河口的奥奇夫要塞；随着军火库爆炸，防御崩溃，要塞在大量伤亡中陷落。被视为黑海西北岸之锁的奥奇夫丧失，使通往克里米亚之路向俄国人敞开，并在伊斯坦布尔引起巨大恐慌。要塞将在次年因疫病和补给困难被俄国人放弃而重新转入奥斯曼。", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["巴尼亚卢卡大捷——解救波斯尼亚", "f603865a"], "d": ["奥地利军队进入波斯尼亚并围攻巴尼亚卢卡后，波斯尼亚总督赫基姆奥卢·阿里帕夏率自当地民众召集的部队赶来增援，使人数占优的敌人遭到惨败。这一胜利使奥地利占领波斯尼亚的计划在第一步就告破产，该省北部被完全收回。巴尼亚卢卡成为1683年之后面对奥地利不断后撤的奥斯曼军队士气得以振作的转折点之一。", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["赫萨尔奇克（格罗茨卡）大捷——打开通往贝尔格莱德之路", "2101cdff"], "d": ["为保卫贝尔格莱德而前进的奥地利军队，在多瑙河畔的狭窄隘口中伏，在持续整日的会战中损失惨重。瓦利斯元帅的部队不成队形地退回贝尔格莱德，奥斯曼军队抵近要塞前并开始围攻。赫萨尔奇克是卡尔洛维茨以来对奥地利取得的最决定性的会战胜利，直接使贝尔格莱德得以收回。", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["《尼什条约》——与俄国和平、亚速中立化与阻止克里米亚袭击", "674f974e"], "d": ["随着奥地利在贝尔格莱德同意和平而陷于孤立的俄国，在法国使节维伦纽夫的斡旋下被迫结束战争。亚速要塞的工事被拆毁，该地区被宣布为两国之间的中立地带；俄国接受不在黑海保有战舰和商船的条件。于是俄国出海的目标又被推迟了一代人，而奥斯曼国家在十八世纪最后一次满意地离开谈判桌。", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["奥奇夫自俄国占领下返回：1739年和约后要塞被拆毁后交还", "7ecc2bef"], "d": ["俄国人于1737年7月11日攻占奥奇夫。依1739年与俄国的和约，要塞工事被拆毁之后重新交给奥斯曼人；奥斯曼把奥奇夫保留到雅西条约之前的1788年。", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["摩苏尔防御战——击退纳迪尔沙阿", "c03ffbc1"], "d": ["夺取基尔库克和埃尔比勒之后抵达摩苏尔城下的纳迪尔沙阿，四十天里炮击该城并连续发动总攻。总督侯赛因帕夏·杰利利武装城中居民所进行的防御，迫使伊朗军队付出沉重代价而解除围攻。摩苏尔的坚守避免了整个伊拉克的丧失，并在一个世纪里巩固了杰利利家族在该城的势力。", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["迪里耶同盟——内志第一沙特埃米尔国的建立", "188751bf"], "d": ["把被乌耶奈驱逐的学者穆罕默德·本·阿卜杜勒·瓦哈卜庇护于迪里耶的埃米尔穆罕默德·本·沙特，与他结成了把政治权威用于宗教召唤的同盟。这一协议为沙特家族开启了新的历史，并把内志分散的绿洲埃米尔国集中在一场运动周围。在半个世纪内延伸至卡尔巴拉、麦加和麦地那的这一力量，将迫使奥斯曼国家捍卫其在汉志的统治。", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["《克尔登条约》——奥斯曼—伊朗战争的终结", "1d3a919e"], "d": ["持续四年的最后一次战争之后签署的条约，原样重申了1639年《卡斯尔·希林》边界；双方都未获得领土收益。纳迪尔沙阿坚持要求承认贾法里派为第五教法学派的要求未得回应，作为回报，决定伊朗朝觐者可自由朝觐并互派使节。延续两个多世纪的奥斯曼—伊朗战争由此事实上结束；这一边界直到今天大体得以保持。", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["马哈茂德一世去世与奥斯曼三世登基", "30203700"], "d": ["在其二十四年统治中收回了《贝尔格莱德条约》所失土地、并支持炮兵军团改革的马哈茂德一世，在聚礼礼拜后返回途中去世。继位的是其弟、过了五十八年笼中生活的奥斯曼三世。一段短暂而不安的统治开始；在奥斯曼三世三年内更换六任大维齐尔的时期，国家事务明显陷入停滞。", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["奥斯曼三世去世与穆斯塔法三世登基", "3ac10f85"], "d": ["三年统治之后随着奥斯曼三世去世，对改革思想持开放态度并密切关注国事的穆斯塔法三世登上王位。新苏丹依靠大维齐尔科贾·拉吉卜帕夏的经验，试图整顿财政并更新军队；德·托特男爵的快速炮兵在这一时期建立。然而1768年卷入的俄国战争，将使十七年统治的所有成就黯然失色。", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["对俄宣战——巴尔塔事件与1768—1774年战争的开始", "9c6aabe0"], "d": ["追击波兰巴尔联盟的俄国与哥萨克部队攻入并焚烧奥斯曼边界上的巴尔塔镇，御前会议因此作出开战决定，俄国使节被关入七塔堡。在没有认真军事准备、并提前六个月宣布的情形下投入的战争，一开始就进展不佳。持续六年的这场斗争，将以切什梅袭击、卡古尔溃败和克里米亚被占，变成奥斯曼历史上最沉重的一连串失败之一。", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["霍京要塞丧失于俄国", "66d43ea4"], "d": ["在戈利岑亲王统率的俄军两次尝试被击退之后，大维齐尔在卡缅涅茨与霍京之间遭遇溃败，军队撤退，守军放弃了要塞。多瑙河以北最强的奥斯曼工事未经抵抗便丧失，使瓦拉几亚与摩尔达维亚的大门向俄国人敞开。两个公国同年被占领；霍京要到1774年才凭《库楚克凯纳尔贾条约》得以收回。", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["卡古尔（卡尔塔尔）平原溃败", "6f408eaf"], "d": ["在切什梅舰队被焚三周后，多瑙河畔的奥斯曼主力军在卡古尔平原，在鲁缅采夫元帅人数远少却纪律严明的部队面前溃散。营地、辎重和数百门火炮落入敌手；逃跑的部队在渡过多瑙河时损失惨重。同一个夏天里舰队和陆军接连被歼，导致基利亚、阿克尔曼、伊兹梅尔和本德尔相继陷落以及克里米亚被占。", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["俄国占领克里米亚半岛", "217837b0"], "d": ["一年前夺取布贾克的俄国军队，在多尔戈鲁科夫亲王统率下越过佩列科普地峡，侵入整个克里米亚半岛。汗被废黜，亲俄的萨希卜·吉莱被扶上位，使汗国脱离奥斯曼迈出了第一步。三个世纪来作为奥斯曼北方盾牌的克里米亚的丧失，是1774年独立、1783年直接吞并进程的开端。", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["穆斯塔法三世去世与阿卜杜勒哈米德一世登基", "42cba8e2"], "d": ["在俄国战争最危急之时去世的穆斯塔法三世，由在宫中笼内度过四十三年的其弟阿卜杜勒哈米德一世于四十九岁登基取代。接手国家最艰难时期之一的新苏丹，被迫面对同年将签署的《库楚克凯纳尔贾条约》的苛刻条件。其十五年统治将在克里米亚的丧失和新的俄国战争中度过，并将在1789年读到奥奇夫陷落消息时的中风中终结。", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["科兹卢贾溃败——通向库楚克凯纳尔贾的失败", "8e0542f9"], "d": ["集结在舒门前的奥斯曼军队，在科兹卢贾败于苏沃洛夫与卡缅斯基的联合各路，军队大部溃散。这次溃败之后，巴尔干再无可抵抗的力量；俄国先头部队围攻舒门，大维齐尔的大本营受到威胁。不到一个月便在库楚克凯纳尔贾坐上谈判桌并接受极为苛刻的条件，直接是这次失败的结果。", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["布科维纳（北摩尔达维亚）让给奥地利", "190f9caa"], "d": ["利用库楚克凯纳尔贾所致衰弱的奥地利，要求联系摩尔达维亚与特兰西瓦尼亚的布科维纳地区，并未参战，凭威胁与贿赂获得了这块土地。位于霍京西南的这一富庶而具战略意义地区的丧失，事实上把摩尔达维亚公国一分为二。未发一枪的这次割让，被视为奥斯曼国家已丧失威慑力的最明显迹象之一。1775年随布科维纳的割让，苏恰瓦和切尔诺夫策转入奥地利（日期未经证实）。", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["巴士拉遭伊朗占领", "0161e709"], "d": ["桑德王朝君主凯里姆汗之弟萨迪克汗，在持续一年的围攻之后夺取巴士拉，奥斯曼国家失去了其在波斯湾最重要的港口。占领直接动摇了印度贸易路线、椰枣和珍珠收入以及伊拉克的南部防御。该城直到1779年凯里姆汗去世、伊朗爆发王位之争时才得以收回。", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["《艾纳勒卡瓦克协议书》——就克里米亚的临时妥协", "9b3b0468"], "d": ["因克里米亚汗国由谁继位而濒临开战的两国，在法国斡旋下于艾纳勒卡瓦克宫签署了一份说明文本。俄国同意自克里米亚撤军，奥斯曼国家则同意承认亲俄的沙欣·吉莱的汗位；苏丹对克里米亚的宗教哈里发权利得到确认。将持续四年的这一脆弱平衡，将在1783年俄国直接吞并半岛时彻底崩溃。", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["阿纳帕城堡的修建——高加索防线", "be92a80f"], "d": ["随着《库楚克—凯纳尔贾条约》和克里米亚的丧失，为维护奥斯曼在高加索的影响，开始在库班河口修建一座新城堡。建于热那亚殖民地遗址之上的阿纳帕，凭借集市、浴场和两百五十多家店铺，不久成为与切尔克斯部落保持联系的城市。该城堡在四十八年间一直是奥斯曼对抗俄国南下高加索的最前沿哨所。", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["大维齐尔哈利勒·哈米德帕夏被罢免与处决", "c44001ca"], "d": ["阿卜杜勒哈米德一世曾多次表示对其服务满意的改革派大维齐尔哈利勒·哈米德帕夏，于1785年3月31日凌晨被突然罢免，流放到加利波利，全部财产被没收。先是授予他哈巴沙省、吉达桑贾克和麦加谢赫哈拉姆之职；1785年4月在博兹贾阿达为启程做准备期间，他又被罢免了这一总督职位，并凭发出的死刑敕令，被阿尔及利亚人加齐·哈桑帕夏的手下卡拉凯赫亚扎德·阿里杀害。其首级被送往伊斯坦布尔，在奥尔塔卡普示众。据TDV所述，这一突然失势虽被解释为以图废黜苏丹、改立塞利姆王子的阴谋为罪名，但真正的原因应是对其在克里米亚被吞并时保持沉默所引起的愤慨、其改革所触犯的圈子的敌意以及加齐·哈桑帕夏的反对。", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["对俄宣战——1787—1792年奥斯曼—俄国战争开始", "3bfb870c"], "d": ["鉴于叶卡捷琳娜二世炫耀性的克里米亚之行及其把格鲁吉亚纳入庇护，御前会议以扭转吞并为目的作出开战决定，俄国使节再度被关入七塔堡。然而军队未准备好，国库空虚，寻求盟友也没有结果。持续五年的战争，将以奥奇夫在屠杀中陷落、伊兹梅尔丧失以及《雅西条约》的苛刻条件告终。", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["奥地利参战——两线斗争", "ae912290"], "d": ["依1781年与俄国所订秘密同盟，奥地利皇帝约瑟夫二世向奥斯曼国家宣战，并向贝尔格莱德和波斯尼亚方向行动。奥斯曼军队顷刻间被迫同时在两条战线上作战：北面对俄国，西面对奥地利。尽管在拉扎雷特哈内、穆哈迪耶和舍贝什取得了对奥地利的胜利，1789年随着贝尔格莱德丧失，西线也将崩溃。", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["奥斯曼—普鲁士同盟", "03b88e51"], "d": ["一登基就在欧洲寻求盟友的塞利姆三世，与普鲁士签署了规定互相援助的同盟条约；普鲁士承诺对俄国与奥地利宣战，奥斯曼国家也承诺在未收回克里米亚前不媾和。这是奥斯曼历史上同一个欧洲国家签署的第一份真正的互惠同盟文本，显示出“与异教徒无同盟”这一传统观念的被放弃。普鲁士未参战，却迫使奥地利求和，为《锡斯托瓦条约》扫清了道路。", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["伊兹梅尔要塞陷落与屠杀", "6a296b0c"], "d": ["被视为多瑙河三角洲最强工事的伊兹梅尔要塞，被苏沃洛夫将军发动的一场血腥总攻在一日内攻取；守军和城中居民大部遭到屠杀。这场在欧洲引起广泛反响的屠杀，在奥斯曼舆论中造成深深的震撼，并打断了多瑙河防线的脊梁。要塞一年后将依《雅西条约》收回，然而战争的命运早已注定。", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["《锡斯托瓦条约》——奥地利战线结束", "58741f1d"], "d": ["凭借普鲁士的压力和法国大革命在西方牵制奥地利，两国以战前边界为基础达成和平。奥地利把包括所占贝尔格莱德在内的一切地方交还；奥斯曼国家只接受了克罗地亚边界上的小调整。西线以这些条件结束，使奥斯曼国家得以把全部力量集中对付俄国，并限制了《雅西条约》中的损失。依克罗地亚边界上的这些调整，采蒂恩（采蒂格勒）和德雷日尼克格勒由奥斯曼转入哈布斯堡（TDV zistovi-antlasmasi；科里奇2016，注118，第4条）。奥尔绍瓦（旧奥尔绍瓦）则是唯一未被归还的地方（班拉基0019/1796）；地图把法理上的割让记在这一天（事实占领为1790年4月16日）。", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["《雅西条约》——克里米亚最终丧失与德涅斯特河边界", "a56fd194"], "d": ["依五年战争末所签条约，德涅斯特河被接受为边界；河左岸归俄国，右岸留给奥斯曼，奥奇夫及其周边最终丧失。奥斯曼国家完全放弃了收回克里米亚的希望，并在法理上承认1783年的吞并；瓦拉几亚与摩尔达维亚以两年免税归还。同时接受了一千二百万库鲁什的战争赔款义务，黑海以北由此被永久让给俄国。同日并入的其他地方：伊兹梅尔。", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["瓦赫兰（奥兰）被西班牙人撤空并移交阿尔及尔", "9f95cee6"], "d": ["1790年地震使城堡和城市大部分被毁之后，已无力再承担三个世纪来耗费巨大的驻军的西班牙，与阿尔及尔军团达成协议，不战而移交了瓦赫兰和梅尔斯克比尔。这样，北非海岸最后一个欧洲据点也被清除。奥斯曼的阿尔及利亚在直到法国占领之前的三十八年间，一直掌控着整个海岸。", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["帕兹万多奥卢·奥斯曼在维丁事实称王", "0ce70361"], "d": ["反抗新秩序改革的帕兹万多奥卢·奥斯曼，驱逐维丁总督并夺取该城，并沿多瑙河以深壕加固。1797年势力鼎盛时，他召集近八万兵力，控制尼科波利斯、锡斯托瓦、鲁塞、索非亚和尼什；他把自己宣称为改革者而非叛乱者。奥斯曼朝廷1798—1799年持续数月的围攻无果，他一直到1807年去世都在北保加利亚半独立统治。", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["陆军皇家工程学校开办", "e9a3a34b"], "d": ["为给新秩序军队培养炮兵、工兵和测绘军官，在哈斯科伊开办了陆军工程学校；它是1773年建立的海军工程学校在陆军中的对应者。课程中教授代数、几何、力学、工事和弹道学，从欧洲语言翻译了数学和炮兵书籍。被视为土耳其现代工程教育根源的这所学校，被认为是今日伊斯坦布尔技术大学的开端。", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["对法宣战与同俄国、英国结盟", "80e95bd7"], "d": ["拿破仑入侵埃及之后，奥斯曼国家打破了两个半世纪的传统法国友谊，对法国宣战。同一进程中，它在历史上第一次与俄国结盟，并允许俄国舰队通过海峡进入地中海；随后又与英国签署同盟。凭借这些同盟，爱奥尼亚诸岛自法国人手中夺取，然而把海峡对外国舰队开放，为未来树立了一个代价沉重的先例。", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["普雷韦扎从法国人手中夺取——尼科波利斯战役", "d8e5e892"], "d": ["1797年威尼斯共和国覆灭后，伊奥尼亚群岛以及陆上的普雷韦扎、帕尔加和沃尼察落入法国之手。约阿尼纳总督特佩德伦利·阿里帕夏，利用法国入侵埃及所引发的战争，向普雷韦扎进军，在该城外的尼科波利斯废墟上使法国守军遭到惨败。这样，在帕萨罗维茨留给威尼斯的这个港口，在八十年后归入奥斯曼统治。布特林特（Butrinto）在法国守军炸毁工事并撤往科孚之后于10月25日陷落（Curlin，Preveza B，2010；地图日期取自普雷韦扎），并归入奥斯曼统治。", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["阿克防御战——击退拿破仑", "56b5c45b"], "d": ["自埃及向叙利亚推进的拿破仑围攻阿克，两个月里连续发动进攻；该城由杰扎尔·艾哈迈德帕夏在英国舰队支持和自伊斯坦布尔派来的新秩序部队协助下防守。被迫解除围攻并退回埃及的拿破仑，把东进的梦想埋葬在这些城墙前。消息在伊斯坦布尔受到极大欢庆，并被视为新建的受训军队通过第一次严肃考验的证明。", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["瓦哈比派袭击卡尔巴拉", "522341ed"], "d": ["自内志出发的瓦哈比军队进入卡尔巴拉，劫掠该城，毁坏侯赛因陵墓，并杀害三千多人。奥斯曼国家在伊拉克的马穆鲁克总督们未能阻止袭击；该事件在伊朗和伊斯坦布尔都引起巨大反应。这次袭击宣告沙特运动已不再是一个绿洲埃米尔国，而是变成威胁奥斯曼圣城的地区性力量。", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["卡尔特利—卡赫季（东格鲁吉亚）被并入俄国", "3b650c5e"], "d": ["1783年接受俄国保护、1795年遭受伊朗毁灭性远征的卡尔特利—卡赫季王国被废除；依1801年9月12日的敕令被宣布为俄国的一个省，俄国的行政体系开始在此建立。格鲁吉亚自此日起丧失独立；数年之内，明格列利亚（1803年）、伊梅列季和古里亚（1804年）也归入俄国统治，俄国抵达奥斯曼的高加索边界。通过这一事件，哥里、杜谢季（卡尔特利）和泰拉维（卡赫季）转归俄国。", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["自法国人手中收复埃及", "00cfdc8c"], "d": ["奥斯曼与英国军队自陆路和海路联合行动的结果，先是开罗、随后是亚历山大被接收，法国军队乘船被送回本国。持续三年的占领结束时，埃及在纸面上回到奥斯曼管理，但马穆鲁克贝伊们与阿尔巴尼亚部队之间的统治权争夺使国家陷入混乱。这一真空，将在数年内为卡瓦拉的穆罕默德·阿里的崛起奠定基础。", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["《巴黎条约》——重建与法国的和平", "1b76991f"], "d": ["依埃及撤军之后签署的条约，奥斯曼国家与法国之间的战争状态正式结束，旧治外法权得以续订。法国商船获准进入黑海；作为回报，法国承认奥斯曼领土完整。和平的建立，使被夹在俄国与英国之间的塞利姆三世的对外政策重新获得回旋余地。", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["瓦哈比派攻占塔伊夫", "7b791359"], "d": ["在沙特·本·阿卜杜勒阿齐兹统率下的瓦哈比军队，在针对汉志的第一次行动中围攻并劫掠塔伊夫；该城作为通向圣地的第一扇门陷落。对具有两圣地庇护者称号的奥斯曼苏丹而言，这是直接动摇统治合法性的一击。两个半月后同一支军队将向麦加进军。", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["瓦哈比派首次攻占麦加", "21157c05"], "d": ["塔伊夫陷落两个半月后，瓦哈比军队进入麦加，拆毁陵墓，并依其理解建立秩序；谢里夫加利卜被迫退往吉达。朝觐之路被切断，在整个伊斯兰世界引起反响，迫使伊斯坦布尔向埃及总督穆罕默德·阿里求取军事援助。这第一次统治仅持续了三个月。", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["谢里夫加利卜收复麦加", "83d08dff"], "d": ["退往吉达的谢里夫加利卜，以召集的部队围攻麦加，经二十五天围攻后自瓦哈比派手中夺回该城；奥斯曼之名的呼图白重新宣读。这第二次统治也不会持久，沙特军队将在1806年再度夺取该城。", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["第一次塞尔维亚起义开始", "0f6e8767"], "d": ["在贝尔格莱德夺取管理权的叛乱近卫军达伊们集体屠杀塞尔维亚显贵之后，在卡拉乔尔杰领导下开始了武装抵抗。起初对苏丹保持忠诚、仅对抗达伊们的这一运动，很快变成要求自治和独立的民族起义。塞尔维亚军队于1806年夺取贝尔格莱德；这次起义成为巴尔干民族主义独立运动的第一环。", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["瓦哈比派占领麦地那", "84e310d7"], "d": ["继麦加之后，麦地那也落入瓦哈比军队之手；先知清真寺的宝库被分发，城中带穹顶的陵墓被拆毁。两座圣城由此同时脱离奥斯曼控制，来自大马士革与埃及的朝觐队伍多年无法启程。麦地那直到七年后的1812年才由穆罕默德·阿里帕夏之子托松帕夏统率的埃及军队收回。", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["对俄战争开始（1806—1812年奥斯曼—俄国战争）与封闭海峡", "ea170804"], "d": ["在拿破仑奥斯特利茨大捷之后向法国靠拢的塞利姆三世，不顾俄国压力撤换瓦拉几亚和摩尔达维亚总督，俄国军队遂占领两个公国，战争开始。奥斯曼国家对俄国舰队封闭了海峡；对此，英国也站在俄国一边，向伊斯坦布尔派出一支舰队。持续六年的这场战争，与卡巴克乔起义和塞利姆三世被废交织在一起，将以1812年《布加勒斯特条约》丧失比萨拉比亚告终。", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["英国舰队抵达伊斯坦布尔前（达克沃思行动）", "195bb58f"], "d": ["想迫使奥斯曼国家断绝与法国联系的英国，派达克沃思海军上将统率的舰队穿过恰纳卡莱，在伊斯坦布尔前抛锚。在法国使节塞巴斯蒂亚尼的引导下，伊斯坦布尔居民动员起来，海岸炮台在数日内得到加强，舰队在城市尚未遭炮击之前被迫撤退；归途中在恰纳卡莱损失惨重。首都首次受到外国舰队如此近距离的威胁，使海峡问题进入欧洲外交的中心。", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["穆斯塔法四世被勒死", "eeb75c20"], "d": ["在阿勒姆达尔·穆斯塔法帕夏遭袭身亡、叛乱者企图向宫内进军之际，被废黜的穆斯塔法四世奉其弟马哈茂德二世之命被勒死。其遗体安葬于巴赫切卡普其父阿卜杜勒哈米德一世的陵墓；叛乱者中流传着灵柩是空的传言。", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["《卡莱·苏丹尼耶条约》——与英国和平与海峡规则", "fe282117"], "d": ["在达克沃思行动失败之后与英国签署的条约，结束了两国间的战争，并归还英国商人的旧特权。文本中称作“古老规则”的条款，记载了和平时期任何外国军舰都不得通过海峡。这一原则成为塑造十九世纪整个海峡制度的所有国际安排的法律依据。", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["斯洛博奇亚溃败——多瑙河军队被围", "54b60fd1"], "d": ["在鲁塞前渡过多瑙河的奥斯曼军队大部，被库图佐夫自河对岸的包围机动困在斯洛博奇亚，并被弃于饥饿之中。数千名士兵被迫投降；大维齐尔手中的兵力事实上消融，奥斯曼朝廷一个月后被迫求停战。这次失败，是1812年《布加勒斯特条约》中同意割让比萨拉比亚的直接原因。", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["收复贝尔格莱德与镇压第一次塞尔维亚起义", "06f56f52"], "d": ["因《布加勒斯特条约》而失去俄国支持的塞尔维亚起义者，在来自波斯尼亚和鲁米利的部队联合行动面前无法支撑；胡尔希德·艾哈迈德帕夏进入贝尔格莱德，持续九年的起义被完全镇压。卡拉乔尔杰逃往奥地利，斯梅代雷沃桑贾克重新直接隶属奥斯曼管理。然而采取的严厉措施，两年后将引发米洛什·奥布雷诺维奇领导的第二次、也是持久的起义。", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["第二次塞尔维亚起义与米洛什·奥布雷诺维奇出任首席公", "e6e82ad2"], "d": ["在第一次起义被镇压后所采取的严厉措施之下，米洛什·奥布雷诺维奇领导下爆发了新的起义；这一次，奥斯曼朝廷选择了妥协而非武力。依达成的协议，米洛什以“首席公”之名获承认，征税与处理内部事务的权限留给塞尔维亚诸公。事实自治的这一最初核心，成为通向1830年敕令和1878年独立的进程的起点。", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["瓦拉几亚起义——伊普西兰蒂渡过普鲁特河与弗拉迪米雷斯库起事", "67d46a98"], "d": ["在俄军中任将军的亚历山大·伊普西兰蒂，以友谊社之名渡过普鲁特河，企图在瓦拉几亚和摩尔达维亚发动一场希腊人的全面起义；同一时期，图多尔·弗拉迪米雷斯库也发动了当地农民。两场运动未能会合：对伊普西兰蒂共同对抗土耳其人的号召，弗拉迪米雷斯库回答“我起事不是反对土耳其人，而是反对希腊人”，不久后被伊普西兰蒂的手下杀死。起义于5月被奥斯曼军队镇压，然而法纳尔人总督制度终结，起义之火蔓延到摩里亚。", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["第二沙特国家在利雅得建立", "34dad3bd"], "d": ["在1818年迪里耶陷落、第一沙特国家覆灭六年之后，图尔基·本·阿卜杜拉把埃及驻军逐出内志，建立了以利雅得为中心的新沙特埃米尔国。新结构避免伸向汉志，选择留在内志，并远离同奥斯曼—埃及军队的直接冲突。这第二个国家将延续到本世纪末，并构成通向今日沙特阿拉伯建立的链条的第二环。同日丧失的其他定居点：迪里耶（内志）。", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["《阿克尔曼条约》——对塞尔维亚与公国的让步", "c75f15d0"], "d": ["废除近卫军军团之后立即陷于无军境地的奥斯曼国家，在俄国最后通牒面前被迫接受苛刻条件的条约。许诺给塞尔维亚的自治得到确认，瓦拉几亚和摩尔达维亚总督未经俄国同意不得撤换得到承认，俄国商船在海峡获得完全自由。两年后因希腊问题而宣布不承认条约时，俄国将以此作为开战理由。", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["提马尔制度的清除", "84d5d1d6"], "d": ["废除近卫军军团一年后，鲁米利和安纳托利亚五十三个桑贾克中约5200名领提马尔的西帕希，连同其提马尔收入被改编为“穆罕默德常胜军”骑兵。奥斯曼土地、税收和军队制度四个世纪的骨干——提马尔制度——由此事实上终结。空出的提马尔移交国库，并为转向中央领薪军队与货币税制扫清了道路。", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["皇家医学校的建立——现代医学教育的开端", "ac3e57c0"], "d": ["为给新建的穆罕默德常胜军培养医生和外科医生，依御医穆斯塔法·贝赫切特埃芬迪的建议，在谢赫扎德巴什开办了皇家医学校。课程依欧洲教学大纲安排，起初以法语授课；数年后又建立了皇家外科学校，两所机构合并。被视为土耳其现代医学教学开端的这所学校，被认为是今日伊斯坦布尔医学院的根源。", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828—1829年奥斯曼—俄国战争开始", "9dff4e05"], "d": ["因纳瓦里诺舰队被焚以及奥斯曼朝廷宣布不承认《阿克尔曼条约》，俄国同时从两条战线开战。近卫军军团刚被废除，新军尚在组建阶段，奥斯曼的防御一开始就薄弱；俄国人渡过多瑙河，在东方攻取卡尔斯和阿哈尔齐赫。一年内推进到埃迪尔内的俄军，将强加1829年《埃迪尔内条约》的苛刻条件及希腊的独立。", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["同美利坚合众国的第一份条约", "d737516f"], "d": ["经多年接触后签署的商业与航运条约，使美国在奥斯曼国土上获得最惠国地位和经海峡的商业通行权。另一项秘密条款规定，奥斯曼在其愿意时可在美国船坞造船，并购买现成船只和木材；美国参议院批准了条约，但以18票对27票否决了这一秘密条款。造船之路仍未关闭：亨利·埃克福德1831年把带来的船只卖给了奥斯曼，在艾纳勒卡瓦克工作的美国工匠使舰队获得了新型船只。这份条约成为奥斯曼国家同欧洲之外一个国家建立的第一个全面关系的文件。", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["终结巴格达的马穆鲁克统治", "7e1d38a3"], "d": ["奉行集权政策的马哈茂德二世，宣布不送所要之款并杀害中央来员的巴格达总督达乌德帕夏为叛逆。阿里·里扎帕夏统率的部队经九十天围攻后攻取该城，马穆鲁克几乎全部被清除。自1704年起延续的半独立马穆鲁克统治由此终结，伊拉克重新直接隶属中央。", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["在马奇卡兵营创办军事学校", "bf31c7d9"], "d": ["为给穆罕默德常胜军提供按欧洲方式培养的军官，在马奇卡兵营开办了军事科学学校。学生被教授数学、地图、工事和外语；不久后向维也纳和巴黎派出学生，使骨干得到加强。这所学校，是奥斯曼军队中科班出身军官传统，从而十九世纪末将出现的新一代军人知识分子诞生之处。", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["的黎波里塔尼亚直接隶属中央——卡拉曼利王朝的终结", "faabcb96"], "d": ["在卡拉曼利家族内部的王位之争以及法国1830年占领阿尔及尔之后日益增加的欧洲压力下，奥斯曼朝廷对的黎波里塔尼亚直接干预。自伊斯坦布尔派出的舰队进入该城，末任卡拉曼利贝伊被撤换并带往伊斯坦布尔，行省被交给中央任命的总督。随着124年的王朝时期结束，奥斯曼国家在北非直接管理的最后一块土地得到了巩固。", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["废除财政官职并设立财政部", "89f8125e"], "d": ["作为古典奥斯曼财政制度之首的财政官一职被废除，设立了欧式的部——财政部，分散的国库集于一手。同一年，奥斯曼朝廷的其他部门也在“部”的名义下重新整顿，转入现代内阁结构。这一整顿，是为一年后将宣布的《坦志麦特敕令》准备行政基础的最重要步骤之一。", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["英国人在亚丁定居", "ddbd556b"], "d": ["英国依据1802年与拉赫季苏丹艾哈迈德·本·阿卜杜勒·卡里姆所订商业与友好协议，在亚丁港登陆并控制该城。扼守红海入口的这一港口，作为通往印度之路的煤炭补给基地，变为英帝国战略的关键点。尽管奥斯曼国家对也门的主张在纸面上延续，其在南海岸的事实统治此后再未恢复。", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["返回提哈马海岸：攻取荷台达、扎比德与摩卡", "353982d2"], "d": ["1840年埃及军队撤走后成为无主之地的也门海岸，由麦加谢里夫监督下的陶菲克帕夏统率的部队登陆，把荷台达、扎比德和摩卡港口并入奥斯曼管理。虽想一直推进到萨那，但因居民的抵抗而退回荷台达；于是高地仍留在栽迪派伊玛目手中，奥斯曼统治二十三年间只延续于提哈马地带。内也门直到1872年才随艾哈迈德·穆赫塔尔帕夏的战役得以收回。", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["《巴尔塔利曼协定》：奥斯曼—俄国对瓦拉几亚和摩尔达维亚的共同庇护", "d3bb22e9"], "d": ["1848年革命蔓延到瓦拉几亚和摩尔达维亚之后，奥斯曼与俄国军队共同占领了这两个公国。依在巴尔塔利曼签署的协定，决定总督不经选举而由苏丹任命七年任期，两国在该地区建立共同控制。协定在纸面上保全了奥斯曼的宗主权，却给予俄国事实上的共管权，并加速了多瑙河公国脱离奥斯曼。", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["匈牙利难民问题：科苏特及其同伴逃入奥斯曼", "1c7d7ef4"], "d": ["1848—1849年匈牙利革命被俄奥干预镇压之后，拉约什·科苏特及数千名匈牙利—波兰难民逃入奥斯曼领土。奥地利与俄国强硬要求引渡难民；奥斯曼朝廷在英国和法国支持下拒绝引渡，并把该群体安置在屈塔希亚。科苏特的圈子在此停留了约十八个月，数百名难民皈依伊斯兰教并进入奥斯曼服务。该事件被视为提高坦志麦特时代奥斯曼在欧洲舆论中声望的少有的外交胜利之一。", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["创设学者会：伊斯坦布尔的第一个奥斯曼科学院", "6fda1365"], "d": ["依公共教育会议决定设立的学者会，是为编写土耳其语科学与教科书而组建的第一个奥斯曼科学院。1851年7月18日在教育厅大楼举行仪式开幕；其本地与外国成员中有艾哈迈德·杰夫代特帕夏。虽然存世短暂，杰夫代特帕夏的《历史》和《奥斯曼语法》等著作是这一机构的成果，被视为使土耳其语成为学术语言的基石。", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["奥尔泰尼察大捷：多瑙河战线上奥斯曼的首次胜利", "a660ad2f"], "d": ["在克里米亚战争开局阶段，大元帅奥马尔·吕特菲帕夏渡过多瑙河，在奥尔泰尼察以沉重损失击退俄军。胜利一开始就阻止了俄国的推进，并向欧洲显示了奥斯曼军队因坦志麦特之后训练而获得的力量。这一成就为英国和法国作出站在奥斯曼一边参战的决定准备了心理基础。", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["在伊斯坦布尔与英国、法国订立同盟条约", "04809278"], "d": ["在克里米亚战争中针对俄国，奥斯曼国家与英国和法国之间签署的同盟条约，规定三国共同行动，盟国在战争结束前不得单独媾和。奥斯曼国家由此在历史上第一次以平等一方的身份，同欧洲大国缔结军事同盟。这份条约也为两年后在巴黎正式接纳奥斯曼进入欧洲国家体系奠定了法律基础。", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["设立伊斯坦布尔市政府：第一个现代市政机构", "be4af27f"], "d": ["克里米亚战争期间涌入伊斯坦布尔的盟军士兵和不断增长的人口所引发的基础设施危机，暴露了以卡迪为中心的古典城市管理的不足。依欧洲范例建立的市政府，把清洁、定价、市场监管和建设事务集于一手；次年在贝伊奥卢—加拉塔组建了第六市政区作为试点区。这一步被视为奥斯曼现代市政的开端。", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["《巴黎条约》：克里米亚战争的结束与奥斯曼被接纳入欧洲国家体系", "4aee0e2a"], "d": ["随结束克里米亚战争的《巴黎条约》，奥斯曼国家被宣布为欧洲国际法的平等成员，其领土完整被置于大国的共同保证之下。黑海被中立化，俄国自《库楚克凯纳尔贾条约》以来取得的对东正教臣民的庇护主张被宣告无效，南比萨拉比亚（基利亚、卡胡尔、伊兹梅尔和博尔格勒诸县）划给摩尔达维亚。然而同一条约把《改革诏书》变为国际承诺，也为干预内政打开了大门。", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["多尔马巴赫切宫开放：行政中心自托普卡帕迁出", "71ad26d0"], "d": ["阿卜杜勒迈吉德于1842年向巴良家族订造的宫殿，经十四年施工后开放，国家的行政中心从有四个世纪历史的托普卡帕迁到博斯普鲁斯海峡畔。凭借欧洲风格、水晶楼梯和典礼大厅，该宫成为坦志麦特西化主张的石头表达。其巨额造价则成为奥斯曼财政陷入外债螺旋的那些年里最受批评的项目之一。", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["瓦拉几亚与摩尔达维亚在库扎治下合并：罗马尼亚的诞生", "baef4da5"], "d": ["在《巴黎条约》之后举行的选举中，两个公国都选举亚历山德鲁·扬·库扎上校为总督，实现了事实上的合并。奥斯曼朝廷和奥地利虽表示反对，但在法国支持下，只得接受既成事实。纸面上仍隶属奥斯曼的这一联合，将于1862年定名罗马尼亚，1877年单方面宣布独立；这是多瑙河畔奥斯曼统治瓦解的转折点。", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["库莱利事件：伊斯坦布尔针对阿卜杜勒迈吉德的首次政变企图", "e3653b21"], "d": ["对坦志麦特政策以及《改革诏书》给予非穆斯林的平等心怀不满的、由军人与平民混合组成的秘密社团，在策划废黜苏丹时，于克勒奇·阿里帕夏清真寺集会之际被突击。因被告在库莱利兵营受审，事件以此名称得名；死刑被改为流放。它被视为奥斯曼历史上以意识形态理由组建的组织所进行的第一次宫廷政变企图。", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["黎巴嫩山德鲁兹—马龙派内战与大马士革事件", "5595fdd6"], "d": ["1860年5月在赛伊达附近因两名德鲁兹人被杀而爆发的冲突，演变为山区最血腥的德鲁兹—马龙派内战，并于7月蔓延到大马士革，造成数千名基督徒死亡。法国出兵之后，奥斯曼朝廷派富阿德帕夏以非常权限前往该地区；进行了严厉的镇压行动。事件成为欧洲干预的借口，也是黎巴嫩获得特殊地位的直接原因。", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["《时事译者报》开始出版：伊斯坦布尔第一份私营土耳其语报纸", "24792957"], "d": ["由阿加赫埃芬迪创办、希纳西负责编务的《时事译者报》，是未经国家支持而出版的第一份土耳其语报纸。创刊号序言中为民众对自己事务发表意见的权利辩护，该报连载希纳西的《诗人的婚礼》，也为现代土耳其文学打开了大门。奥斯曼舆论概念和反对派报刊的诞生，被追溯到这一日期。", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["《黎巴嫩山条例》：给予黎巴嫩享有特权的穆塔萨里夫地位", "bf375603"], "d": ["1860年屠杀之后在大国压力下起草的条例，使黎巴嫩山成为直接隶属奥斯曼朝廷、由按教派平衡组成的行政会议管理的享有特权的穆塔萨里夫辖区。规定穆塔萨里夫须为奥斯曼籍的天主教基督徒，其任命须提交大国同意；首任穆塔萨里夫是达乌德帕夏。这一秩序将持续到1915年，并构成现代黎巴嫩国家的核心。", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["阿卜杜勒迈吉德去世与苏丹阿卜杜勒阿齐兹登基", "27204d7c"], "d": ["在其二十二年统治中签署《坦志麦特》与《改革》诏书的阿卜杜勒迈吉德，因肺结核去世，其弟阿卜杜勒阿齐兹登上王位。新苏丹最初几年以节约措施和朴素生活带来希望；他使舰队成为世界屈指可数的力量之一。然而其统治末期，沉重的外债、1875年的破产与巴尔干起义的积累，将为1876年的废黜行动奠定基础。", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["合并公国定名罗马尼亚", "d960e3fc"], "d": ["1859年因库扎双重当选而事实合并的瓦拉几亚与摩尔达维亚，于1862年把议会和政府集中于布加勒斯特一个屋檐下，正式定名罗马尼亚。奥斯曼国家虽在法理上保留宗主身份和年贡，却事实上失去了对公国的控制。多瑙河以北有四个世纪历史的奥斯曼影响的终结，以这一日期为标志。", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["萨瓦金、马萨瓦与达赫拉克并入埃及", "a0924860"], "d": ["1846年被苏丹阿卜杜勒迈吉德作为“岁入”（收入分配）连同萨瓦金授予埃及总督穆罕默德·阿里帕夏的马萨瓦，在赫迪夫伊斯梅尔帕夏时期连同达赫拉克和萨瓦金被纳入埃及产业，并以卡伊马卡姆地位组建。红海非洲海岸的这三个港口由此虽在法理上仍是奥斯曼领土，却在管理上直接由奥斯曼朝廷转到开罗——与其邻居埃及和苏丹进入同一个藩属层。", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["克里特起义开始（1866—1869）", "3679b861"], "d": ["在希腊明确支持下于岛上爆发的大规模起义，使克里特希腊人的“恩诺西斯”（并入希腊）要求第一次成为国际问题。持续三年的艰苦山地战使奥斯曼军队损失惨重，在欧洲舆论中引起巨大反响。起义直到1868年阿里帕夏亲赴该岛并实施给予广泛特权的条例才得以平息。", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["撤出贝尔格莱德与塞尔维亚要塞中最后的奥斯曼驻军", "b34217db"], "d": ["在大国压力和米哈伊洛亲王坚持要求之下，奥斯曼朝廷同意撤出在塞尔维亚剩余的最后军事据点；1867年4月18日，贝尔格莱德要塞的奥斯曼军旗被降下，钥匙交给亲王。自1521年起延续的事实奥斯曼军事存在由此结束，塞尔维亚走向独立之路上的最后一大障碍被移除。苏丹的宗主权仅被降为象征性的旗帜与年贡问题。", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["授予埃及总督赫迪夫称号", "09e10c12"], "d": ["凭卡瓦拉王朝第三代伊斯梅尔帕夏的大力游说和向伊斯坦布尔流入的钱财，授予埃及总督强调其高于其他总督的赫迪夫称号。同一时期，继承方式也被改为父传子，并授予埃及对外借款、授勋、设领事等具宗主性质的权限。这些步骤是加速埃及在法理上脱离奥斯曼的链条的第一环。", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["《克里特条例》：给予该岛广泛行政特权", "12052262"], "d": ["为结束三年的起义，大维齐尔阿里帕夏亲赴该岛，依苏丹批准颁布的条例，给予克里特人混合行政会议、地方法庭、官方事务中使用希腊语以及赋税减免。这一安排使奥斯曼统治在岛上又维持了三十年。然而给予基督教人口的特权削弱了穆斯林克里特人的地位，并埋下了1896—1898年危机的种子。", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["国务会议开幕：奥斯曼国务院成立", "70b16497"], "d": ["依1868年3月5日的诏令，司法判决会议一分为二，行政—立法事务归国务会议，司法事务归司法判决院；该机构在奥斯曼朝廷隆重开幕，首任主席为米德哈特帕夏。受命起草法案、解决行政纠纷并办理官员审判。凭借穆斯林与非穆斯林混合的成员结构，它被视为奥斯曼分权思想的第一次制度化实践。", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["苏伊士运河开通：经埃及的印度之路缩短", "377ccd04"], "d": ["始于1859年的施工持续了十年，连接地中海与红海的163公里运河在盛大仪式中投入使用。联系欧洲与印度的航路缩短了数千英里，埃及顿时成为世界贸易的关键点。这一地缘战略价值，将成为运河开通十三年后英国占领埃及的主要原因；运河加在埃及身上的债务，则将使赫迪夫政权陷于破产。", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["保加利亚督主教区的建立：保加利亚教会脱离法纳尔", "33a8272c"], "d": ["根据苏丹敕令，一个独立于希腊牧首区的保加利亚教会（督主教区）得以建立，哪些卡扎划归督主教区则交由民众投票决定。高门此举本意在于削弱希腊人的影响，结果却适得其反：该教会成了保加利亚民族认同和保加利亚人对马其顿主张的有组织中心。巴尔干地区保加利亚人、希腊人与塞尔维亚人之间的竞争以及1876年起义的制度基础就此奠定。", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["阿西尔被置于直接统治之下", "4559e099"], "d": ["随着苏伊士运河开通，红海的战略价值上升，人们认识到不能让位于通往也门陆路中段的阿西尔山地处于无控制状态。出征也门的雷迪夫帕夏的部队进入艾卜哈，将该地区置于奥斯曼直接统治之下，并建立了阿西尔桑贾克。由于山地地理和伊德里斯人的影响，这种统治从未完全稳固。", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["米德哈特帕夏的内志远征：重建奥斯曼对哈萨的统治", "7db51461"], "d": ["巴格达总督米德哈特帕夏利用沙特家族内部的王位之争，向波斯湾西岸派兵，并将哈萨地区以内志桑贾克之名划归巴士拉省。阿卜杜拉·本·费萨尔被任命为穆塔萨里夫，奥斯曼的统治在纸面上得以确立。这次远征的目的是阻止英国势力在海湾扩张，并使卡塔尔于同年也归入奥斯曼控制之下。", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["大维齐尔阿里帕夏去世：坦齐马特班底的终结", "1cf0141c"], "d": ["1869年福阿德帕夏去世后独力支撑坦齐马特政策的阿里帕夏一去世，那一代主导国家外交三十年的老练外交家便凋零殆尽。继任的马哈茂德·内迪姆帕夏亲俄且专断的统治，巩固了阿卜杜勒阿齐兹的个人统治。阿里帕夏去世后的五年内，财政破产，巴尔干爆发起义，君主更替已不可避免。", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["奥斯曼控制在卡塔尔的建立", "3b453165"], "d": ["应处于英国压力下的谢赫卡西姆·本·萨尼之邀，奥斯曼军队在卡塔尔半岛登陆，1871年秋季在该地区确立了奥斯曼的控制。卡塔尔被编为隶属内志桑贾克的一个卡扎，谢赫被任命为卡伊马卡姆。这一举动是米德哈特帕夏在海湾对抗英国的进取政策中最具体的成果；奥斯曼旗帜在该半岛上一直飘扬到1913年。", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["关于突尼斯的世袭敕令——贝伊职位归穆罕默德·萨迪克帕夏家族", "1509ebb0"], "d": ["趁法国败于普鲁士之机，突尼斯贝伊穆罕默德·萨迪克帕夏派往伊斯坦布尔的海雷丁帕夏的努力促成了一道敕令，据此突尼斯以世袭方式授予穆罕默德·萨迪克帕夏及其后裔，同时仍直接隶属于伊斯坦布尔。未经苏丹许可，不得进行战争与和平谈判，不得将国内任何土地让与他人，奥斯曼的征兵要求须予满足。法国不承认该敕令；十年后占领了突尼斯。", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["萨那的攻占：奥斯曼权威在也门的重建", "978e20a0"], "d": ["苏伊士运河开通使红海的战略价值上升，高门遂派艾哈迈德·穆赫塔尔帕夏统率后备军进军也门。萨那被攻占后，在内陆也门这个两个世纪以来实际上已丢失的地区重新确立了国家权威，该地区被设为省。然而与栽德派伊玛目的斗争从未停止；1891年、1898年和1904年的起义构成了奥斯曼代价最高、持续最久的内部战线。同日加入的其他地点：萨那、塔伊兹。", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["黑塞哥维那起义爆发：东方问题再度升温", "571b18ec"], "d": ["由于重税和地方显贵的压迫，涅韦西涅周边基督徒农民的起义迅速蔓延到整个黑塞哥维那，并得到来自塞尔维亚和黑山志愿者的支援。起义促使奥地利和俄国强行要求改革，并于次年引发保加利亚人的起义以及塞尔维亚与黑山的宣战。这样，通向93战争以及通过《柏林条约》丧失巴尔干的那条大链条的第一环就断开了。", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["奥斯曼财政破产：外债偿付减半", "2cac2fa5"], "d": ["自1854年起接连举借的贷款、克里米亚战争的开销、宫殿营建以及1873至1874年安纳托利亚的饥荒，使预算赤字扩大到超过五百万里拉的深渊。马哈茂德·内迪姆帕夏政府宣布债务的利息和本金偿付在五年内减半，实际上等于宣布延期偿付。这一决定在欧洲交易所引起强烈反应，并开启了六年后以《穆哈兰法令》和奥斯曼公债管理局的设立为结果的进程。", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["穆拉德五世被废与阿卜杜勒哈米德二世登基", "cffb2271"], "d": ["阿卜杜勒阿齐兹被废黜后登基的穆拉德五世，由于叔父之死以及切尔克斯人哈桑事件所震撼的精神状态而无法履行职责；在其九十三天的统治中，他仅有七天神志清醒。他经大穆夫提的教令被废黜，其弟阿卜杜勒哈米德二世被推上王位。新苏丹是在向米德哈特帕夏许诺宣布立宪的条件下登基的；一个将持续三十三年的时代开始了。", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["造船厂会议：列强强加的巴尔干改革", "b5006a2c"], "d": ["为解决巴尔干危机，列强在伊斯坦布尔召集的会议要求将保加利亚分为两个自治省，并在波斯尼亚和黑塞哥维那实行受国际监督的改革。高门在会议开幕当天鸣炮宣布颁布《基本法》，企图以宪政改革来应对强加的要求。代表们视此为拖延，于1877年1月20日散会；四个月后俄国宣战。", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["首届国民议会在多尔玛巴赫切开幕", "429bb279"], "d": ["依据《基本法》选出的115名议员，于1877年3月19日在多尔玛巴赫切宫仪典大厅举行的典礼上首次集会；奥斯曼历史上的代议制议会时代由此开始。穆斯林和非穆斯林议员严厉质询政府，讨论战争的指挥和大臣的责任。这种勇敢的反对立场，成为缩短议会寿命的主要原因。", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["普列夫纳保卫战开始：加齐奥斯曼帕夏的抵抗", "0e04a878"], "d": ["93战争中渡过多瑙河的俄军为切断通往伊斯坦布尔的道路，奥斯曼帕夏从维丁向普列夫纳进军，以堡垒和战壕加固该镇，开始了长达五个月的传奇式防御。连续三次俄罗斯—罗马尼亚联军的大规模进攻均以惨重损失被击退，由沙皇亚历山大二世亲自指挥的军队被迫转入围困。普列夫纳作为奥斯曼军队在19世纪最辉煌的防御战功载入史册。", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["普列夫纳陷落：多瑙河战线崩溃", "185e7602"], "d": ["在五个月围困中粮尽的奥斯曼帕夏沿维德河发起突围；负伤被俘后城市投降。俄军指挥官们向被俘的帕夏致敬并归还了他的佩剑，奥斯曼帕夏被授予“加齐”称号。普列夫纳陷落后俄军的前路畅通；两个月内索非亚、普罗夫迪夫和埃迪尔内相继陷落，俄军先头部队抵达耶希尔柯伊。", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["俄军占领索非亚", "ef369d22"], "d": ["普列夫纳陷落后越过巴尔干山脉的俄军进入了无设防的索非亚。该城再未回到奥斯曼统治之下，将于1878年底成为自治的保加利亚公国的城市，1879年成为其实际首都。在地图上，索非亚自此日起脱离奥斯曼的直接统治，转入临时的俄军占领，随后转入自治的保加利亚管理。", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["埃迪尔内停战协定：93战争中枪声停息", "1f899180"], "d": ["索非亚、普罗夫迪夫和埃迪尔内相继陷落，俄军逼近马尔马拉海岸，高门被迫请求停战。在埃迪尔内签订的停战协定，使奥斯曼接受了保加利亚自治、黑山—塞尔维亚—罗马尼亚独立以及沉重的战争赔款等初步和平条件。这些条件一个月后将在圣斯特凡诺化为条约文本。", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["阿卜杜勒哈米德二世无限期休会国民议会", "e770b540"], "d": ["议员们把战争的灾难性结局归咎于政府和宫廷并提出尖锐批评，阿卜杜勒哈米德二世依据《基本法》赋予他的权力，将议会无限期休会。运作约十一个月的首届奥斯曼议会就此关闭，持续三十年的专制时代开始。议会直到1908年革命之后才得以重新召开。", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["《圣斯特凡诺条约》：大保加利亚方案", "2c7cc611"], "d": ["结束93战争的《圣斯特凡诺条约》建立了一个延伸到爱琴海并包含马其顿的庞大自治保加利亚；承认塞尔维亚、黑山和罗马尼亚独立；把卡尔斯、阿尔达汉、巴统和多乌巴亚泽特割给俄国，还强加了无法偿付的战争赔款。这份使俄国抵达地中海的文本引起英国和奥地利的强烈反应。它未经实施，四个月内就被柏林会议重新安排；但它仍是宣告奥斯曼鲁米利亚终结的文件。", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["卡尔斯、阿尔达汉和巴统割让给俄国——三省", "99bdfad2"], "d": ["根据《柏林条约》，奥斯曼国家以抵偿部分战争赔款为名，把卡尔斯、阿尔达汉和巴统割让给俄国；而在圣斯特凡诺让给俄国的多乌巴亚泽特和埃莱什基尔特河谷则留在奥斯曼。巴统虽作为自由港给予，但这一地位仅保持到1886年。俄国人把卡尔斯设为隶属于以第比利斯为中心的外高加索总督辖区的一个省；高达十万人的三省居民被迫迁往埃尔祖鲁姆一侧。同一条约还把南比萨拉比亚（基利亚、卡胡尔、博尔格勒）从罗马尼亚归还给俄国。", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["奥匈帝国占领波斯尼亚和黑塞哥维那及新帕扎尔", "e5f901df"], "d": ["凭借《柏林条约》赋予的权限，奥匈帝国军队进入波斯尼亚；尽管奥斯曼政府同意不予抵抗，萨拉热窝和莫斯塔尔的本地穆斯林与东正教居民仍拿起武器，进行了三个月的顽强抵抗。占领直到1878年10月20日才得以完成。苏丹的法理主权在纸面上持续到1908年，但四个世纪的奥斯曼波斯尼亚实际上已经丧失，大规模穆斯林移民潮开始。同日丧失的其他居民点：巴尼亚卢卡。", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["《穆哈兰法令》与奥斯曼公债管理局的设立", "02b7cc03"], "d": ["1875年破产后与债权国代表进行的谈判，以伊历1299年穆哈兰月28日（1881年12月20日）的法令告终：债务本金被削减一半以上，作为交换，盐、烟草、丝绸、印花税和渔税等最有收益的收入项目被直接移交给由债权人管理的奥斯曼公债管理局。雇用数千名官员的这一机构，成了国家内部独立的财政组织。它被视为奥斯曼财政独立实际终结之日。", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["萨瓦金——唯一没有落入马赫迪之手的港口", "5a37b198"], "d": ["自1884年2月起，除萨瓦金以外的整个苏丹东部地区都落入穆罕默德·艾哈迈德·马赫迪的统治，而该港口则靠格雷厄姆将军指挥的三个营的英军军事保护得以维持。这是事实状态与法律状态分离的一个时期的开端：虽然海岸实际上处于英国军事控制之下，但其行政隶属于1885年从埃及划出，直接划归也门省，即隶属于高门——这一安排一直持续到1888年法国占领泽拉为止。", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["米德哈特帕夏在塔伊夫监狱中被杀", "f4562261"], "d": ["《基本法》的设计者、第一次立宪的象征人物米德哈特帕夏，因阿卜杜勒阿齐兹之死一案在耶尔德兹法庭被判有罪，死刑改判流放，被送往塔伊夫。据TDV记载，1884年5月7至8日夜间他在牢房中被勒死，官方宣布的原因是“希尔彭杰”病。他的死成为阿卜杜勒哈米德二世时期清除宪政反对派的象征。", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["海达尔帕夏—安卡拉铁路特许权授予德国人", "5705b163"], "d": ["依照苏丹谕旨，海达尔帕夏—安卡拉线的修建与经营特许权被授予代表德意志银行的银行家阿尔弗雷德·冯·考拉，安纳托利亚铁路公司随之成立。这一特许权是打破英法在奥斯曼交通和外交中的垄断、确立德国影响的转折点。十一年后授予同一公司的巴格达线特许权，加上它催生了“柏林—巴格达”的设想，这成为第一次世界大战前大国竞争的主轴之一。", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["奥斯曼统一协会在伊斯坦布尔成立", "b7187939"], "d": ["军事医学院的四名学生为反对专制统治，作为秘密组织成立了奥斯曼统一协会；该组织不久演变为将青年土耳其运动所有反对派力量聚集在其旗下的统一与进步委员会。以细胞为原则的组织与欧洲的流亡者和萨洛尼卡的军官结合起来。1908年迫使宣布第二次立宪、1913年之后独力执掌国家的那批人，正是从这个小小的学生细胞中走出来的。", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["奥斯曼银行事件：达什纳克党人在加拉塔的行动", "08b3095f"], "d": ["亚美尼亚达什纳克苏蒂温组织的一支武装小组，为引起欧洲对亚美尼亚问题的关注，突袭并劫持了加拉塔的奥斯曼银行总部，并威胁炸毁大楼。危机在大使们出面斡旋后，以行动者乘船离境为条件结束。事件后数日里在伊斯坦布尔发生的流血事件，对亚美尼亚问题演变为国际干预的杠杆起了决定性作用。", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897年奥斯曼—希腊战争爆发：塞萨利战线", "33e490ab"], "d": ["鉴于希腊向克里特岛派遣舰队和军队，以及鲁米利亚边界上的匪帮袭击，奥斯曼国家宣战。由德国改革团训练的奥斯曼军队在塞萨利迅速推进，一个月内攻占了耶尼谢希尔、恰塔尔贾和多梅科；希腊军队溃散。经列强介入，所获土地被归还，但这场战争仍是阿卜杜勒哈米德二世时代唯一一次明确的军事胜利，却未能阻止克里特岛的实际丧失。", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["科尼亚—巴格达线特许权授予德国人", "fd8b6cbd"], "d": ["继德皇威廉二世1898年访问伊斯坦布尔和大马士革之后，安纳托利亚铁路公司获得了从科尼亚延伸至巴格达和巴士拉的线路的预备特许权。巴格达铁路计划，对奥斯曼意味着加强对阿拉伯各省的中央控制，对德国则意味着抵达波斯湾。英国和俄国强烈反对的这一计划，成为通向第一次世界大战的帝国主义竞争中最具争议的议题之一。", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["汉志铁路在大马士革动工", "62f58f68"], "d": ["阿卜杜勒哈米德二世1900年5月2日以谕旨下令修建的这条线路，于1900年9月1日在大马士革举行的正式典礼上开工。该项目完全依靠来自伊斯兰世界的捐款和奥斯曼工程师兵士的劳动修建，使朝觐者的大马士革—麦地那旅程从四十天缩短到五天。它既是巩固哈里发精神权威的声望工程，又是加强对汉志军事控制的战略投资。", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["《米尔茨施泰格纲领》：马其顿的国际改革监督", "4c7464da"], "d": ["伊林登起义之后，俄国与奥地利皇帝在米尔茨施泰格会晤，为马其顿制定了新的改革方案。纲领设想在奥斯曼总监察官身旁安置两名外国文官，由欧洲军官重组宪兵，并按民族原则变更行政边界。高门虽以主权受损为由抵制，但在共同压力下被迫接受；该纲领成为加速年轻军官中统一派组织发展的基本因素之一。", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["穆拉德五世去世", "396659a7"], "d": ["1876年在位约三个月即被废黜的穆拉德五世，在企图使他复位的行动之后，在严密看管下被囚禁二十八年，死于糖尿病。他被安葬于新清真寺内杰迪德·哈瓦廷陵墓中其母亲的身旁。他作为在位时间最短的奥斯曼苏丹载入史册。", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["萨那落入伊玛目叶海亚之手", "e7f876cb"], "d": ["栽德派伊玛目叶海亚·哈米杜丁1904年发动的起义，于1905年4月以萨那在围困结束时陷落而告终；该城脱离奥斯曼统治，围城期间发生了饥饿和瘟疫。也门山地的地理、补给线的漫长以及栽德派伊玛目制的地方合法性，使奥斯曼在当地的统治自建立以来就十分脆弱。该城五个月后将以惨重代价夺回，但也门问题直到1918年都未了结。", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["耶尔德兹暗杀事件：对阿卜杜勒哈米德二世的炸弹袭击", "1ee2e1a6"], "d": ["达什纳克苏蒂温组织在苏丹从聚礼仪式出来时，引爆了苏丹马车旁装有定时炸弹的马车，实施了暗杀；阿卜杜勒哈米德因与大穆夫提交谈而耽搁了几分钟，从而保住了性命。爆炸中二十六人死亡，五十多人受伤。该事件使苏丹对安全的偏执及依靠密探组织的专制统治进一步强化；也成为泰夫菲克·菲克雷特诗作《迟延的一刻》的题材。", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["萨那的收复：伊玛目叶海亚起义的镇压", "dec3b8f9"], "d": ["1904年在栽德派伊玛目叶海亚领导下开始的起义，于1905年4月以萨那陷落告终，城中出现饥饿和瘟疫。由阿里·里扎帕夏和艾哈迈德·费伊齐帕夏指挥的增援军队，在塔伊兹部队的支援下，于1905年7月15日至9月1日间展开行动，以惨重代价夺回该城，起义被镇压。也门战役使奥斯曼军队损失数以万计，并带来巨大的财政负担；鲁米利亚军官中“流放也门”的恐惧，是滋养统一派组织的首要不满之一。", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["第二次立宪时期第一届国民议会召开", "e7fd2716"], "d": ["经过三十年的间隔，通过两级选举产生的议会于1908年12月17日在苏丹的演说中开幕，青年土耳其运动领袖艾哈迈德·里扎贝伊当选议长。由土耳其人、阿拉伯人、阿尔巴尼亚人、希腊人、亚美尼亚人和犹太人议员组成的议会，是奥斯曼主义理想的最后一次大规模尝试。然而保加利亚独立、波斯尼亚被吞并以及克里特宣布并入希腊，在议会开幕之前就给这种乐观情绪蒙上了阴影。", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["行动军与阿卜杜勒哈米德二世被废：穆罕默德·列沙德五世登基", "6a65a704"], "d": ["因3月31日事件而从萨洛尼卡出发的行动军，于4月22至23日夜间分四路进入伊斯坦布尔，4月24日耶尔德兹宫投降。大国民议会4月27日决定废黜阿卜杜勒哈米德二世；苏丹被送往萨洛尼卡，其弟穆罕默德·列沙德五世被推上王位。三十三年的个人统治就此结束，但取而代之的是一个苏丹沦为象征、统一与进步党依靠军队支持执政的新时期。", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["阿尔巴尼亚起义：科索沃和斯库台的武装抵抗", "93ed30c6"], "d": ["统一派政府的中央集权税收政策、收缴武器运动以及拉丁字母之争，使一向被视为对国家最忠诚的阿尔巴尼亚部落发动起义。尽管马哈茂德·舍夫凯特帕夏指挥的军队严厉镇压了起义，不安仍于1911年和1912年再度升温。这些起义在巴尔干战争前夕消耗了奥斯曼军队，也加速了阿尔巴尼亚民族运动的诞生。", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["《乌希条约》：的黎波里塔尼亚和班加西割让给意大利", "4ffa1fd2"], "d": ["面对巴尔干各国的战争准备，无力承受两线作战的高门，在瑞士的乌希镇与意大利签订秘密和约，放弃了的黎波里塔尼亚和班加西。奥斯曼国家就此丧失了在非洲的最后一块领土；作为交换，虽然答应归还意大利占领的罗得岛和十二群岛，但这一许诺从未兑现。条约签订时，巴尔干战争已经开始。通过此事，穆尔祖克（费赞）、加特、塞卜哈、乌巴里、提尔甘（Traghan）、扎维拉（Zawila）和卡特伦（费赞（的黎波里塔尼亚省桑贾克））转入意大利统治。", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["利姆诺斯被希腊占领", "9555af1d"], "d": ["第一次巴尔干战争中，希腊舰队占领了利姆诺斯；该岛的穆兹罗斯港成为封锁达达尼尔海峡的基地。该岛于洛桑（1923年7月24日）被让给希腊。", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["萨索斯被希腊占领", "6c03c7f0"], "d": ["第一次巴尔干战争中，希腊占领了萨索斯和萨莫色雷斯。", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["萨莫色雷斯被希腊占领", "911e82a3"], "d": ["第一次巴尔干战争中，希腊占领了萨莫色雷斯。", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["莱斯沃斯被希腊占领", "6b2b07ba"], "d": ["希腊舰队在莱斯沃斯登陆；该岛在第一次巴尔干战争结束时被希腊陆军和舰队占领。伦敦会议（1913年5月）确认了这一状况。", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["希腊军队在希俄斯登陆", "901c6539"], "d": ["第一次巴尔干战争中，1912年4月7日遭到炮击的希俄斯被希腊人登陆；奥斯曼守军于1913年1月3日投降。该岛依《洛桑条约》（1923年7月24日）被让给希腊。", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["大维齐尔马哈茂德·舍夫凯特帕夏在伊斯坦布尔遇刺身亡", "68e60e63"], "d": ["高门事件后被任命为大维齐尔的马哈茂德·舍夫凯特帕夏，在前往陆军部途中，于恰尔舍卡普附近遭到向其马车开火而身亡。统一与进步党将暗杀归咎于反对派，发起了大规模逮捕和处决浪潮，自由与协商党实际上被清除。这一事件之后，以恩维尔—塔拉特—杰马尔三人为基础的统一派一党专政最终确立。", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["第二次巴尔干战争爆发：同盟者的分赃之争", "48d088a2"], "d": ["依据《伦敦条约》从奥斯曼获得的土地无法分配，巴尔干同盟者彼此反目；保加利亚进攻塞尔维亚和希腊阵地，第二次战争爆发。罗马尼亚和黑山也站到反对保加利亚的一边，保加利亚军队崩溃。奥斯曼国家利用这一机会，越过《伦敦条约》划定的米迪耶—埃内兹线，连同埃迪尔内一起收复了东色雷斯。", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["《伊斯坦布尔条约》：与保加利亚媾和及埃迪尔内的确认", "c8c18b2d"], "d": ["第二次巴尔干战争之后奥斯曼国家与保加利亚签订的条约，以梅里奇河为边界，从法律上确认埃迪尔内、克尔克拉雷利、迪迪莫特依霍和东色雷斯留在奥斯曼境内。杜拉萨奇（德德阿加奇）留给保加利亚（卡瓦拉则是在1912年秋季保加利亚占领之后，于1913年7月转归希腊，并于1913年8月10日根据《布加勒斯特条约》确认归希腊），还规定了两国间的相互人口交换以及保加利亚境内穆斯林的权利。这一文本是对从巴尔干灾难中唯一能够收回的领土的保证。同日加入的其他地点：久木尔吉纳。", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["博兹贾阿达与伊姆罗兹的收回——《雅典条约》", "ec084d09"], "d": ["巴尔干战争中被希腊占领的北爱琴海诸岛中，扼守海峡口的博兹贾阿达和伊姆罗兹，在《雅典条约》谈判中被认为对恰纳卡莱的防御不可或缺，因而归还奥斯曼。其他岛屿留在希腊。这两座岛屿成了帝国在爱琴海保有的最后领土，并在洛桑也留给了土耳其。", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["《雅典条约》：与希腊媾和及萨洛尼卡—约阿尼纳的移交", "8e94def7"], "d": ["奥斯曼国家与希腊之间签订的条约，正式承认在巴尔干战争中丧失的萨洛尼卡、约阿尼纳和南马其顿归属希腊，并放弃了对克里特的奥斯曼权利。留在希腊的穆斯林的宗教和财产权利、宗教基金的地位以及穆夫提的任命都得到详细规定。爱琴海诸岛的地位却被搁置未决，成为两国之间持续紧张的根源。", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["奥斯曼—德国秘密同盟条约在伊斯坦布尔签订", "0472efb3"], "d": ["欧洲战争一爆发，奥斯曼国家与德国在大维齐尔赛义德·哈利姆帕夏的宅邸签订了秘密同盟条约；文本规定一旦俄国对德国作战，奥斯曼也将站在德国一边。条约甚至对内阁保密，只有四个人知道。三个月后，奥斯曼国家将因黑海袭击事件而实际卷入战争，帝国的命运就被这份文件系住了。", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["单方面废除治外法权", "ec773d18"], "d": ["奥斯曼政府趁欧洲忙于战争之机，宣布自1914年10月1日起单方面废除赋予外国人司法、财政和关税特权的治外法权。这一四个世纪的特权制度的终结，在国内被怀着巨大的独立热情迎接，伊斯坦布尔举行了庆祝。包括盟友德国在内的所有国家都对此决定提出抗议；治外法权直到1923年才在洛桑被最终终结。", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["黑海袭击：奥斯曼舰队炮击俄国港口", "8ad4ef61"], "d": ["从德国逃出、以“购买”的名义加入奥斯曼舰队的戈本号（Goeben）与布雷斯劳号（Breslau）（亚武兹号与米迪利号），在苏雄上将指挥下驶入黑海，炮击俄国港口并击沉船只。恩维尔帕夏瞒着内阁下达的这道命令，实际上终结了中立。一周之内，俄国、英国和法国宣战，奥斯曼国家便无可挽回地卷入了第一次世界大战。", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["英属印度军队占领法奥——伊拉克战线的开启", "08663813"], "d": ["协约国对奥斯曼国家宣战的次日清晨，驻在巴林待命的英属印度旅在阿拉伯河口的法奥登陆。破败的法奥城堡中的奥斯曼小股部队在战舰炮火下撤退，印度电报线的站点落入英国人之手。伊拉克战线由此开启。", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["宣布大圣战：在法提赫清真寺宣读圣战教令", "2a6174e8"], "d": ["大穆夫提于尔居普吕·海里埃芬迪颁布的五项教令，以哈里发兼苏丹的名义在法提赫清真寺宣读，号召全体穆斯林对协约国发动圣战。德国寄予厚望的这一举措，目的在于使英法殖民地的穆斯林起义。预期中的全面起事并未发生；相反，两年后麦加埃米尔谢里夫侯赛因在英国支持下发动叛乱，痛苦地显示出哈里发政治影响力的局限。", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["库尔内向英军投降", "621d36b0"], "d": ["巴士拉陷落后退往底格里斯河与幼发拉底河交汇处库尔内的巴士拉总督苏卜希贝伊所部，在12月4日至8日的战斗之后，于1914年12月9日清晨投降。", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["埃及被置于英国保护之下并宣布苏丹国", "55d4e520"], "d": ["奥斯曼国家参战之后，英国宣布正式将自1882年起实际占领的埃及置于其保护之下；继续效忠奥斯曼的总督阿拔斯·希勒米帕夏被罢黜，由侯赛因·卡米勒以“苏丹”称号取而代之。这样，自1517年起延续的奥斯曼法理宗主权被单方面终结。高门不承认这一决定，两个月后以运河战役企图夺回埃及。", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["萨勒卡默什战役：高加索战线的灾难", "5cbde7f0"], "d": ["恩维尔帕夏为夺回1878年丢失的卡尔斯—阿尔达汉—巴统，并使高加索的突厥人起义，在冬季驱使第三集团军翻越安拉赫乌艾克巴尔山，进行一次包围俄军的机动。由于冬装不足、补给耗尽以及低至零下三十度的暴风雪，军队未及交战便消耗殆尽；数以万计的士兵冻死。这次行动成为奥斯曼在战争中最严重的灾难之一，使东线两年间处于无防御状态。", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["第一次运河战役：穿越西奈沙漠进攻苏伊士", "02dd72f5"], "d": ["第四集团军司令杰马尔帕夏为使埃及摆脱英国占领并使苏伊士运河停航，组织了一次横越西奈沙漠的进攻。奥斯曼部队抵达运河东岸，一部分得以渡过对岸，但由于英军的优势以及预期的埃及民众起义并未发生而撤退。这次行动未能达成目标，但迫使英国在埃及驻扎大批部队，从而产生了间接的战略影响。", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["《迁徙与安置法》的颁布", "2f2bc22c"], "d": ["在凡城起义和俄军推进之后，政府颁布了一项临时法律，允许军队指挥官将被认为在前线后方破坏安全的人口迁往其他地区，苏丹于1915年5月27日批准。实施的结果是，安纳托利亚东部和南部各省的亚美尼亚人口大部分被迁往叙利亚和摩苏尔方向；迁徙途中因疾病、饥饿和袭击造成了巨大的人员死亡。这一决定至今仍是奥斯曼末年最沉重、也最具争议的问题。", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["奥斯曼部队从俄国占领下收复穆什", "fb1be113"], "d": ["穆什被俄国首次占领六个月后，奥斯曼第16军在比特利斯—穆什反攻中进入该镇。", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["穆什再度落入俄国之手", "43ad8a03"], "d": ["俄军反攻之下，奥斯曼分遣队撤出穆什；该镇于1916年8月22至25日间再度被俄军占领，并一直持续到1917年春。", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["穆什最终摆脱俄国占领", "f0e89703"], "d": ["在第一次世界大战中被俄国占领的穆什，于1917年5月1日被奥斯曼军队最终收复。", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["阿卜杜勒哈米德二世在贝勒贝伊宫去世", "c9662582"], "d": ["1909年被废黜后先被送往萨洛尼卡、因巴尔干战争中该城丧失而被带回伊斯坦布尔并在贝勒贝伊宫遭到软禁的阿卜杜勒哈米德二世去世。在其三十三年的统治期间，他试图使国家远离战争以争取时间，但也因专制统治而为人铭记。他的灵柩在大批人群的陪伴下被安葬于迪凡尤鲁的马哈茂德一世陵墓；他的死恰逢他所建立的体制早已被清除的战争年代。", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["《布列斯特—立陶夫斯克条约》：收回卡尔斯、阿尔达汉和巴统", "da82636f"], "d": ["在布尔什维克革命后退出战争的俄国与同盟国之间签订的条约，关闭了东线，并使奥斯曼国家收回了通过1878年《柏林条约》丧失的卡尔斯、阿尔达汉和巴统（三省）。这是奥斯曼历史上间隔四十年之后唯一取得的领土收益。然而《穆德罗斯停战协定》之后该地区将再度丧失，最终解决要等到1921年的《卡尔斯条约》。", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["奥斯曼部队进入阿尔特温", "ca7d1778"], "d": ["3月25日越过1914年边界的奥斯曼部队，向布列斯特—立陶夫斯克归还了1878年以前边界的三省进军，并于1918年3月28日进入阿尔特温。阿尔特温作为巴统桑贾克的一部分，于1878年留给了俄国；TDV的阿尔特温条目只写回归时间为“1918年3月”，具体日期由穆斯塔法·萨勒给出。", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["阿尔达汉落入土耳其军队之手", "7fd9e3db"], "d": ["在三省行动中，奥斯曼军队继阿尔特温之后，于1918年4月3日占领阿尔达汉；阿尔达汉在93战争中于1877年陷落，1878年留给了俄国。卡尔斯将于一个月后的4月25日被攻占。", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["巴统的收回", "d37a1a0d"], "d": ["因《布列斯特—立陶夫斯克条约》俄国退出战争而向东推进的奥斯曼军队，四十年后收回了1878年丧失的巴统港。黑海东端的这个港口，是巴库石油的海上出口。这一收获仅持续七个月；《穆德罗斯停战协定》之后该地区将被撤空。", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["三省：卡尔斯归入奥斯曼统治", "02cbf0b3"], "d": ["在布列斯特—立陶夫斯克商定归还1878年《柏林条约》中丧失的三个桑贾克——卡尔斯、阿尔达汉和巴统；奥斯曼军队于1918年4月3日进入阿尔达汉、4月14日进入巴统、4月25日进入卡尔斯，行政随即实际建立。这些以“三省”之名著称的土地，被视为对自93战争以来持续的损失的补偿。停战之后它们将再度丧失，直到1921年的《卡尔斯条约》才最终归属土耳其。", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["伊迪尔被占领——阿拉斯河谷的推进", "87ebf4d3"], "d": ["在1918年2月开始的推进行动框架下，土耳其部队在阿拉斯河以北的塞尔德拉巴德击败亚美尼亚部队，并于1918年5月20日占领伊迪尔。伊迪尔不属三省，而是埃里温省的苏尔梅利卡扎；该地区约一百八十年后首次建立了奥斯曼统治。", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["穆罕默德·列沙德五世去世与穆罕默德六世瓦赫德丁登基", "d302ba07"], "d": ["统治九年间经历的黎波里塔尼亚战争、巴尔干战争和世界大战的穆罕默德·列沙德五世，在战争最关键的时期去世，其弟瓦赫德丁以穆罕默德六世之名登基。新苏丹试图摆脱统一派班底的监护；四个月后停战协定签订时，他将不得不主持帝国的清算。他是奥斯曼王朝的第三十六位也是最后一位苏丹。", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["协约国舰队抵达伊斯坦布尔外海及该城被实际占领", "d10cb14d"], "d": ["《穆德罗斯停战协定》之后，由英国、法国、意大利和希腊舰船组成的六十余艘盟军舰队停泊在多尔玛巴赫切前方，伊斯坦布尔实际上处于被占领状态。四百六十五年后，都城首次落入外国军队的控制。同日穆斯塔法·凯末尔帕夏据传在抵达海达尔帕夏、看到这番景象时说出的“他们怎么来，就怎么走”这句话，将成为民族斗争的标志性语句之一。", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["阿拉斯地区的撤退：伊迪尔被撤空", "57572ab4"], "d": ["根据《穆德罗斯停战协定》撤至1914年边界后方的条款，雅库普·舍夫基帕夏以11月21日的命令，下令布列斯特—立陶夫斯克边界之外的部队在12月4日前撤回；伊迪尔及其周边在该日完全撤空。随后，阿拉斯—土耳其政府于1918年12月底被亚美尼亚人推翻。", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["英国人进驻阿尔特温", "e2cb3153"], "d": ["由于1918年10月30日的《穆德罗斯停战协定》要求奥斯曼军队撤至1914年边界之后，阿尔特温被撤空，并于1918年12月17日被英国占领。据TDV的阿尔特温条目，英国占领持续到1920年4月。", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["穆德罗斯之后巴统的英国统治", "9dd768fc"], "d": ["根据1918年10月30日的《穆德罗斯停战协定》，奥斯曼国家被迫撤出巴统；该城于1918年12月24日被英国部队占领。1918年4月被设为独立桑贾克中心的巴统，自此日起至1920年7月一直处于英国控制之下。", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["阿尔达汉转入格鲁吉亚统治", "97cf47f6"], "d": ["穆德罗斯之后被撤空的阿尔达汉，在西南高加索政府被英国人解散的日子里，于1919年4月20日被格鲁吉亚军队占领。格鲁吉亚的统治将持续到1921年2月23日。", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["普雷斯顿将卡尔斯的管理移交亚美尼亚总督", "efa81cb0"], "d": ["1919年4月12至13日解散西南高加索政府的英国指挥官普雷斯顿，于1919年4月30日撤销临时苏维埃政府，并将该城的管理移交给被任命为卡尔斯总督的亚美尼亚人卡尔加诺夫；卡尔斯的亚美尼亚统治时期由此开始，一直持续到卡泽姆·卡拉贝基尔1920年10月30日的胜利。", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["埃尔祖鲁姆大会：东部各省的民族抵抗决议", "41ef0457"], "d": ["由东安纳托利亚维护权利协会召集的大会，在因英国施压而推迟之后，以五十六名代表开幕，已辞去军职的穆斯塔法·凯末尔帕夏当选主席。大会宣布，在民族疆界之内祖国是一个整体，委任统治和保护不可接受，一旦政府瓦解民族将自行掌握自己的命运。这些决议六个月后成为《民族公约》文本的核心。", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["锡瓦斯大会：民族抵抗统一于同一旗帜下", "0e9ad36b"], "d": ["1919年9月4日在锡瓦斯苏丹学校开始工作的大会，将全国各地的维护权利协会统一于安纳托利亚和鲁米利亚维护权利协会的名下，并选出了代表委员会。美国委任统治的提议在长时间讨论之后被否决。随着9月11日发表的声明，民族斗争成为单一中心的、合法的政治运动，并与伊斯坦布尔政府展开了公开的权力斗争。", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["阿马西亚议定书：伊斯坦布尔政府与代表委员会的会谈", "40e6a6ab"], "d": ["达马特·费里德倒台、阿里·里扎帕夏政府组成之后，海军大臣萨利赫帕夏被派往阿马西亚与代表委员会会谈。通过达成的议定书，伊斯坦布尔政府事实上承认了安纳托利亚运动的存在；同意召开国民议会、自由举行选举并保护民族疆界。这是民族斗争在伊斯坦布尔面前取得的首个正式政治成果。", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["《民族公约》在最后一届奥斯曼议会获得通过", "6322865e"], "d": ["在最后一届奥斯曼国民议会中由121名议员签署的《民族誓约》文本，要求位于穆德罗斯线之内、由穆斯林—土耳其多数居住的土地不可分割，在阿拉伯各省和西色雷斯举行公民投票，废除治外法权，并实现完全的政治与财政独立。该文本于1920年2月17日经一致通过并向世界宣布。这份声明既是民族斗争的政治纲领，也是将在洛桑捍卫的边界的地图；它成为协约国于3月16日正式占领伊斯坦布尔的直接原因。", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["英国人撤离时阿尔特温留在格鲁吉亚", "6d086b06"], "d": ["据TDV的阿尔特温条目，英国占领持续到1920年4月；英国人撤离时把该城留给了格鲁吉亚。阿尔特温在格鲁吉亚手中一直留到大国民议会1921年2月23日的最后通牒。", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["巴统移交格鲁吉亚管理", "6523d095"], "d": ["英国人正式将巴统移交格鲁吉亚人发生在1920年7月7日（TDV的巴统条目只写“1920年7月”）。安卡拉政府于7月25日以“占领”为由抗议这一移交。", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["《久姆里条约》：大国民议会政府的首个国际条约", "9232c690"], "d": ["卡泽姆·卡拉贝基尔指挥的东线军队收复萨勒卡默什和卡尔斯之后，亚美尼亚请求和平，并通过在久姆里签订的条约承认不接受《色佛尔条约》，放弃对东部的领土要求。安卡拉政府签订的这一首个条约，成为事实上否定《色佛尔条约》的首个国际文件，并为大国民议会获得法律承认开辟了道路。东部边界由此得到保障，使向西线调动兵力成为可能。", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["第一次伊诺努战役：正规军的首次胜利", "4add3719"], "d": ["新建的正规军在伊诺努阵地阻止了从布尔萨方向推进的希腊军队，迫使其撤退。这一军事上规模有限的成功，其政治后果却极为重大：安卡拉政府被邀请参加伦敦会议，通往与苏维埃俄国签订《莫斯科条约》的道路被打开，《基本组织法》获得通过。国内舆论对正规军的信心也因这场胜利而得到巩固。", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["第二次伊诺努战役：希腊进攻第二次被击破", "a974521c"], "d": ["在伦敦会议上一无所获的希腊军队从布尔萨和乌沙克方向展开新的进攻，但再次在伊诺努山脊被阻止，不得不撤退。穆斯塔法·凯末尔帕夏发给伊斯麦特帕夏的“你们在那里战胜的不仅是敌人，还有民族的厄运”的电报，正是在这次胜利之后写下的。这场战役提高了民族斗争的国际声望，并加速了意大利撤出安纳托利亚的进程。", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["《安卡拉协定》：与法国媾和及南线战事的结束", "35fc32db"], "d": ["萨卡里亚胜利之后与法国在安卡拉签订的协定，使南线战事结束；法国军队撤出包括阿达纳、安泰普、马拉什和乌尔法在内的奇里乞亚和东南部，退到叙利亚边界。协约国之一就此事实上承认了安卡拉政府，《色佛尔条约》阵线上出现了第一道裂缝。从撤出地区接收的武器和腾出的部队，在大反攻的准备中发挥了关键作用。", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["《穆达尼亚停战协定》：伊斯坦布尔和海峡的不战而移交", "ac0d9baf"], "d": ["大反攻之后，土耳其军队在恰纳卡莱和伊兹米特与英军对峙，在穆达尼亚召开的会议，经十一天艰苦的讨价还价后以停战协定告终。东色雷斯到梅里奇河为止由希腊在十五天内撤出并移交土耳其管理，伊斯坦布尔和海峡将在和平条约中交还，均获同意。这样，民族斗争的武装阶段以不发一枪而赢得的外交胜利结束，洛桑之门就此打开。", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["穆罕默德六世瓦赫德丁离开伊斯坦布尔与阿卜杜勒迈吉德埃芬迪当选哈里发", "8ab0e847"], "d": ["苏丹制被废除后处境成疑的末代苏丹穆罕默德六世瓦赫德丁，于1922年11月17日星期五清晨乘英国战舰马拉亚号离开伊斯坦布尔前往马耳他。大国民议会两天后即11月19日，选举阿卜杜勒迈吉德埃芬迪为没有政治权力的哈里发。六百二十三年的奥斯曼王朝统治由此实际终结；哈里发制则又象征性地延续了十五个月。前往马耳他并随后转往意大利的瓦赫德丁定居于圣雷莫的诺贝尔别墅；他为被某个穆斯林国家接纳所提出的申请均无结果，于1926年5月16日在那里去世，并重申自己从未放弃苏丹和哈里发的权利。", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["末代苏丹穆罕默德六世瓦赫德丁在圣雷莫去世", "7149ed0e"], "d": ["离开伊斯坦布尔后定居于意大利圣雷莫的末代奥斯曼苏丹穆罕默德·瓦赫德丁，在尚未获悉他曾声明从未放弃苏丹与哈里发权利的那次哈里发大会（1926年5月13日）已召开的消息之前，于1926年5月16日去世。他当时陷于严重的经济困难；欠圣雷莫商家六万里拉，得知其死讯的债主们对他住所的家什申请了查封。", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["科努拉尔普征服博卢地区——穆杜尔努、科努拉帕与博卢", "e245cd27"], "d": ["奥尔汗加齐的指挥官之一科努拉尔普，向萨卡里亚河以东的山区进军，把穆杜尔努、科努拉帕和博卢地区纳入奥斯曼统治；迪兹杰平原上的城镇即以其名称呼。征服的确切日期不详；叙述依据阿西克帕夏扎德的传闻。该地区当时是在坎达尔王朝与拜占庭之间易手的边境地带；这次征服使奥斯曼首次接近黑海西岸。安卡拉战役之后该地区将再度转归坎达尔王朝，但在法提赫时代被最终夺回。", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["马尔马拉海南部拜占庭城镇的攻占——米哈利奇、克尔马斯蒂、格尔亚兹", "9c61b8d4"], "d": ["尼西亚和伊兹米特被攻占之后，布尔萨平原以西仍留在拜占庭手中的城镇逐一归入奥斯曼统治。乌卢阿巴特湖周边的格尔亚兹、苏苏尔卢克河畔的克尔马斯蒂和米哈利奇，完成了把马尔马拉海南岸与卡雷西领土相连的走廊。这些城镇长期未经围攻，在周边被切断之后投降；拜占庭在该地区的存在由此被压缩到盖姆利克湾。", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["戈尔迪斯（科林斯）归入摩里亚专制公国", "392495eb"], "d": ["自1358年起为佛罗伦萨阿恰约利家族之阿凯亚公国采邑的科林斯，于1395年落入拜占庭摩里亚专制君主狄奥多罗斯之手。该城此后一直留在专制公国管辖之下，直到奥斯曼征服。", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["哈吉埃米尔奥卢侯国的并入——奥尔杜与翁耶", "c064f07f"], "d": ["由巴伊拉姆贝伊在奥尔杜周边建立、其子哈吉·埃米尔于1350年代扩展的这个突厥蛮侯国，是一个中心位于今日埃斯基帕扎尔的小而具战略意义的沿海国家：它是萨姆松与特拉布宗之间唯一的独立统治区。埃米尔苏莱曼于1398年在雷霆巴耶塞特的贾尼克行动中表示效忠，安卡拉战役之后该侯国重获自由。在穆拉德二世时代，与清除塔杰丁奥卢家族同一年间，侯国领土被直接并入奥斯曼统治，黑海海岸自萨姆松到吉雷松统一于一人之手。", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["戈尔迪斯（科林斯）的征服", "87a2bc59"], "d": ["在法提赫的摩里亚远征中，阿克罗科林斯城堡被围攻三个月，最后以和平方式接收。被视为摩里亚之门的科林斯地峡由此归入奥斯曼。", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["黑山并入奥斯曼统治——采蒂涅", "7fdb7cc8"], "d": ["统治泽塔的茨尔诺耶维奇王朝于1496年放弃统治后，作为斯库台后院的黑山山区被直接纳入奥斯曼统治，起初组建为独立桑贾克，随后作为斯库台桑贾克的一部分组织起来。采蒂涅修道院作为该地区的宗教中心被保留在原处。由于地势严酷，这里的管理从未像平原上那样严密；两个世纪后诞生于同一修道院的弗拉迪卡统治，将成为实际独立的核心。", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["巴耶塞特城堡在两伊拉克远征中接受奥斯曼统治", "f29e2e17"], "d": ["大维齐尔易卜拉欣帕夏在两伊拉克远征中到达宾格尔一带时，该地区的许多库尔德部落连同凡城、托普拉卡莱、阿夫尼克和巴耶塞特的城堡，同意归入奥斯曼统治。巴耶塞特曾在1514年塞利姆一世的远征中并入奥斯曼，但军队返回后萨法维人夺回了该地区。", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["大不里士再度转归萨法维人——两伊拉克远征的归途", "80b8b761"], "d": ["两伊拉克远征中军队进入了大不里士，但由于主要目标是巴格达，城中并未留下长期守军。在巴格达过冬的军队折返西行之际，沙赫塔赫马斯普重新进入被撤空的阿塞拜疆，夺回了大不里士。这是奥斯曼—萨法维战争中反复出现的模式：大不里士五次被攻占，五次都未能据守；该城直到1585年才获得长期的奥斯曼守军。", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["凡城与埃尔吉什落入塔赫马斯普之手（奥斯曼的统治于1534至35年告终）", "cb93d561"], "d": ["在1534年把凡城交给奥斯曼统治的这一地区，乌拉马帕夏在凡城城堡中顶住了萨法维人的围攻；城堡落入萨法维人之手，围攻埃尔吉什的萨法维军队也在奥斯曼的援助下被迫撤退。当苏莱曼大帝抵达阿赫拉特时（1535年9月23日），凡城已在塔赫马斯普手中。凡城一直是萨法维的，直到1548年。", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["巴耶塞特桑贾克转入萨法维统治（凡城与埃尔吉什1535年已是萨法维的）", "806a2cf1"], "d": ["位于奥斯曼—萨法维边界中央的巴耶塞特桑贾克重新落入伊朗之手（Kaya 2017称之为“与凡城和埃尔吉什一起”；但据Karataş 2025和TDV，凡城和埃尔吉什已于1535年9月22日回归萨法维——见前一条）；在这次易手中，桑贾克的某些地方遭到毁坏。该桑贾克在16世纪最后二十五年之前，在两国之间多次易手。", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["巴耶塞特桑贾克在纳希切万远征期间再度转归奥斯曼", "cf0171fa"], "d": ["在苏莱曼大帝第三次伊朗（纳希切万）远征期间，巴耶塞特桑贾克重新被纳入奥斯曼统治。在1554年远征中，巴耶兹特成为军队的重要基地；该桑贾克于1578年最终归入奥斯曼主权。", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["埃里温丧失给沙阿巴斯", "34413cf2"], "d": ["在杰拉里起义使安纳托利亚陷于停滞的年代，东线处于无防御状态，已按欧洲方式重新整编军队的沙阿巴斯展开进攻。1583年由费尔哈德帕夏修建的埃里温城堡，在被围攻七个月后投降。依《费尔哈德帕夏条约》取得的高加索防线的第一环断裂，其后三年内整个南高加索都将丧失。", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["第比利斯与占贾的丧失", "3fb51753"], "d": ["埃里温陷落之后，萨法维军队沿库拉河谷推进；卡拉巴赫的中心占贾和格鲁吉亚的首府第比利斯相继丧失。奥斯曼国家当时同时在奥地利战线进行持续十三年的长期战争，并在安纳托利亚对付杰拉里叛乱；已没有可派往东方的兵力。这样，1590年《费尔哈德帕夏条约》所建立的辽阔高加索行省体制实际上告终。", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["希尔万的丧失——沙马基、巴库与杰尔宾特", "81beab11"], "d": ["里海岸的希尔万行省，是通过厄兹德米尔奥卢奥斯曼帕夏1578至1585年的远征所获，作为丝绸贸易的主要来源，为奥斯曼财政提供了重要收入。沙阿巴斯北进的行动接连攻占沙马基、巴库和杰尔宾特，清除了该行省。损失不仅是土地：伊朗丝绸经奥斯曼流向欧洲的通道也脱离了控制，萨法维国家开始经印度洋销售丝绸。", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["塔伊兹的丧失", "65f20d53"], "d": ["奥斯曼人于1038年（1629年），随着也门的统治权一起交给萨那的卡西米统治，放弃了塔伊兹——这是栽德派伊玛目夺回内陆也门进程中的第一个重大步骤。", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["也门的丧失——卡西米伊玛目的统治", "49e83e3c"], "d": ["也门自1538年起是奥斯曼行省；然而栽德派伊玛目的抵抗从未停止。由伊玛目卡西姆发起的起义，在其子穆艾耶德·穆罕默德时期蔓延到全国，奥斯曼守军被逐一围攻。在穆拉德四世专注于巴格达和埃里温的年代，无法派出援军；塔伊兹于1629年丧失，摩卡则在同一崩溃的最后阶段于1635年10月22日被撤空。1635年萨那和宰比德的最后部队也撤出了也门。这样，红海东岸有二百三十七年处于帝国之外，直到1872年才得以收回。据TDV伊斯兰百科全书，拉希季（哈维塔）直到1635年一直在奥斯曼人手中；自该年起栽德派伊玛目开始掌握影响。", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["摩卡的撤空", "c6b3061a"], "d": ["穆斯塔法贝伊于伊历1045年杰马迪·乌拉月10日（1635年10月22日）带着剩余兵力和武器撤出摩卡；随后伊玛目卡西姆之子哈桑·本·卡西姆向宰比德和摩卡任命了自己的人，在提哈马海岸也建立了卡西米的控制。", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["哈萨丧失给贝尼哈立德酋长国", "a9b6131a"], "d": ["哈萨是1550年为封闭葡萄牙进入波斯湾西岸而设立的行省；但它离伊斯坦布尔很远，处在一条孤零零的沙漠道路的尽头。在克里特围攻耗尽资源的年代，该地区的贝尼哈立德部落在巴拉克·本·古雷伊尔率领下逐出奥斯曼守军，并建立了自己的酋长国。海湾西岸在一个半世纪间留在部落酋长国手中；1795年归入沙特人，1871年再度归入奥斯曼。", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["普雷韦扎与沃尼察丧失给威尼斯——埃皮鲁斯海岸的打开", "1201204c"], "d": ["加入神圣同盟的威尼斯，在开始摩里亚远征之前，夺取了扼守安布拉基亚湾口的两座城堡：普雷韦扎及对岸的沃尼察。同年夏天阿亚马夫拉（莱夫卡达）也已陷落。这三个据点保证了舰队从伊奥尼亚海安全进入希腊内陆，并成为次年开始的摩里亚行动的基地。普雷韦扎和沃尼察在帕萨罗维茨也留给了威尼斯；要到1798年才将回到奥斯曼统治之下。", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["索尔诺克的丧失——蒂萨防线的瓦解", "51c2c8ef"], "d": ["新堡于八月陷落之后，哈布斯堡军队转向南方，攻占了蒂萨河上的桥头堡索尔诺克。该城是布达与特兰西瓦尼亚之间唯一安全的通道；其丧失意味着匈牙利东半部的奥斯曼城堡彼此断绝。次年围攻布达时，补给道路被切断具有决定性。", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["莫东丧失给威尼斯", "114c9cc0"], "d": ["位于摩里亚半岛西南端的莫东，是威尼斯三个世纪前丧失并称之为“国家的两只眼睛之一”的港口。科龙陷落之后受到围攻的城堡，在陆海同时炮击下被攻占。莫罗西尼的摩里亚行动由此夺得半岛整个西海岸，通往内地的道路打开。", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["佩奇的丧失", "99d54cf4"], "d": ["布达于九月陷落之后，哈布斯堡军队在多瑙河以西南下，攻占了自苏莱曼大帝时代起属于奥斯曼的佩奇。以加齐·卡西姆帕夏清真寺著称的这座城市，是布达行省最发达的桑贾克中心之一。其丧失意味着通往莫哈奇平原的道路打开；次年的第二次莫哈奇溃败将发生在这里。", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["塞格德的丧失", "9fbee1b2"], "d": ["位于蒂萨河与穆列什河交汇处的塞格德，是匈牙利平原的南门，把守着通往泰梅什瓦尔行省的道路。布达与佩奇同年秋天陷落之后受到围攻的城堡，很快投降。三座城堡一季之内的丧失，是自1541年建立的奥斯曼在匈牙利的行政结构开始崩溃的征兆。地图集同日还把蒂萨河畔的曾塔视为由奥斯曼转归哈布斯堡一方（来源中未读到曾塔专属的投降日期，日期取自塞格德；TDV zenta：自1686年10月起奥斯曼与哈布斯堡领导的同盟者之间开始交战——声明为近似）。", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["巴利亚巴德拉（帕特雷）的丧失——摩里亚的北门", "b9cff63c"], "d": ["位于科林斯湾口的巴利亚巴德拉，是控制摩里亚与鲁米利亚之间通道的港口。威尼斯军队攻占该城之后，海湾两岸的城堡也相继陷落，半岛从陆路被完全隔绝。这次行动的结局是整个摩里亚归于威尼斯；该地区将以“摩里亚王国”之名治理，直到1715年。", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["戈尔迪斯（科林斯）留给威尼斯", "9a25b6b9"], "d": ["巴利亚巴德拉陷落之后，科林斯以和平方式留给威尼斯人，穆斯林居民离开了该城。1687年8月，莫罗西尼的军队为雅典远征正在科林斯集结。", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["埃格尔的丧失", "983391aa"], "d": ["埃格尔于1596年经穆罕默德三世亲自参加的远征攻占，并成为以其为名的行省的中心。北匈牙利这座最后的大型奥斯曼城堡，在第二次莫哈奇溃败之后处于完全被围的状态下抵抗了一年，因饥饿而投降。随着它的丧失，奥斯曼国家在匈牙利的北翼被彻底清除。", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["伊斯托尔尼·贝尔格莱德（塞凯什白堡）的丧失——匈牙利国王的加冕之城", "c6147255"], "d": ["匈牙利国王们数百年间加冕并安葬于此的这座城市，1543年被苏莱曼大帝攻占，成为布达行省最重要的桑贾克中心之一。布达陷落约两年之后，周边被完全切断的城堡投降。这一损失使奥斯曼在多瑙河以西的存在被压缩到锡雷姆和奥西耶克一带。", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["锡盖特堡的丧失", "834910a7"], "d": ["锡盖特堡是苏莱曼大帝第十三次也是最后一次远征中，于1566年围攻进行时去世的城堡；因此它在奥斯曼记忆中具有象征意义。一百二十三年后，在周边所有城堡陷落之后，被沼泽保护的这座城堡也投降了。埋有苏莱曼大帝内脏的陵墓及其周围的城镇，在转入哈布斯堡统治之后被毁。同日在地图上自奥斯曼转归哈布斯堡的另一处居民点：巴尔奇——沿袭锡盖特堡的“兄长中心”链条（Bánlaky 0017/1449；声明为近似）。", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["瓦拉德的丧失", "6cce360d"], "d": ["瓦拉德是1660年由柯普吕律·穆罕默德帕夏攻占并设为以其为名的行省中心的、通往特兰西瓦尼亚的关键城堡。萨伦卡门溃败之后完全陷于孤立的城堡，在近两年的封锁后因饥饿投降。其丧失使奥斯曼对特兰西瓦尼亚的影响实际终结，哈布斯堡的统治在蒂萨河以东确立。", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["雅诺瓦的丧失——特兰西瓦尼亚道路的封闭", "4b5e30d8"], "d": ["雅诺瓦是1658年攻占、把守瓦拉德与泰梅什瓦尔之间联系的城堡。瓦拉德陷落之后周边立即被切断，它也随之丧失。这样，泰梅什瓦尔行省从北面被完全隔绝，并作为直到卡尔洛维茨为止留在奥斯曼手中的唯一匈牙利土地而延续。", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["黑山弗拉迪卡统治的建立——采蒂涅的实际脱离", "a924b778"], "d": ["在神圣同盟战争使奥斯曼对巴尔干的控制松弛的年代，采蒂涅修道院的都主教之职成为彼得罗维奇家族中父子相传的职位，该地区实际上取得了单独的管理。凭借山地的难以到达，这一弗拉迪卡统治在两个世纪里既不完全独立也不完全隶属地存续；其法律上的独立将直到1878年《柏林条约》才得到承认。", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["戈尔迪斯（科林斯）的收复", "26f53e3a"], "d": ["达马德·阿里帕夏的摩里亚远征的第一个大站是科林斯；奥斯曼人于1715年6月从威尼斯人手中夺回该城，并从这里向半岛其余地区推进。", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["纳迪尔的进攻：大不里士、纳希切万、哈马丹、克尔曼沙汗、马拉盖和卡斯尔希林的丧失", "d95efd59"], "d": ["利用萨法维国家崩溃之机于1723至1727年间夺得的西伊朗城市，在于伊朗掌握实际权力的纳迪尔汗的进攻下相继丧失。在阿塞拜疆，阿尔达比勒和哈尔哈尔也落入纳迪尔之手。哈马丹、克尔曼沙汗和卡斯尔希林的丧失在伊斯坦布尔引起沉重反响；军队不出征而在于斯屈达尔等候，以及试图掩盖损失，成为六周后爆发的帕特罗纳·哈利勒起义的直接原因之一。地图集还把沿袭霍伊链条的科图尔视为在这一天由奥斯曼转归萨法维（Uluerler 2015，《Turkish Studies》10/5，第6页；来源中没有科图尔专属的日期——声明为近似）。", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["巴格瓦尔德（阿尔帕恰伊）溃败——高加索丧失给纳迪尔汗", "4262f54c"], "d": ["利用萨法维国家崩溃之机在1723至1725年夺得的高加索各省，只保住了十年。掌握伊朗实际权力的纳迪尔汗，在埃里温附近的巴格瓦尔德使奥斯曼军队遭受惨败；统帅阿卜杜拉·柯普吕律帕夏战死沙场。溃败之后，埃里温、第比利斯、占贾和希尔万在数月内被撤空。东部边界退回到1639年卡斯尔希林线，并在1746年得到确认。", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["本德尔丧失给俄国", "0daca453"], "d": ["卡古尔平原溃败之后，奥斯曼军队退到多瑙河以南，摩尔达维亚与奥泽之间的城堡便孤立无援。把守特尔拉河渡口的本德尔，经两个月围攻后被强攻攻占；该城遭到洗劫。城堡的丧失使北黑海防线的中间一环断裂，随后阿克尔曼和基利亚也相继陷落。在库楚克—凯纳尔贾本德尔将被归还，但将于1806年再度丧失。", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["科威特的萨巴赫酋长国归入奥斯曼保护", "3584dba0"], "d": ["据TDV的科威特条目，该港口是18世纪初由来自内志的乌图卜部落建立的，萨巴赫家族在该世纪末前后接管了统治。在哈萨落入沙特人之手的同一些年里，面对瓦哈比压力别无选择而只能依靠巴士拉的酋长国归入了奥斯曼保护。这一联系将在1871年通过米德哈特帕夏的巴士拉安排得到正式确定，科威特被视为巴士拉桑贾克三个卡扎之一；伊拉克后来的领土主张也依据这一记录。", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["麦加丧失给瓦哈比派", "2da23acd"], "d": ["诞生于内志的瓦哈比运动在沙特·本·阿卜杜勒阿齐兹时期转向汉志；继塔伊夫和麦地那之后，麦加也第二次被攻取——麦加埃米尔谢里夫加利卜在保留埃米尔职位的条件下把该城交给了瓦哈比派。陵墓被毁，来自大马士革和开罗的朝觐商队道路被切断；苏丹每年送往两圣地的苏尔拉（赠礼）也在这些年中断——这项持续到1915年未曾间断的拨款，唯一的例外就是瓦哈比统治时期。由于两圣地保护者的身份是苏丹合法性的基本支柱之一，这一损失除土地丧失之外还是沉重的政治打击；收回它花了七年，且是借助卡瓦拉的穆罕默德·阿里帕夏的军队才得以实现。", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["拉古萨共和国的终结——法国占领", "f8e27bf1"], "d": ["依《坎波福尔米奥条约》（1797年）进驻达尔马提亚海岸的法国人，于1806年5月27日攻占拉古萨，终结了这个小小的商业共和国。这样，自1458年起向奥斯曼纳贡而保持其自治和贸易特权的拉古萨三个半世纪的属国地位终结；该城及共和国的姆列特（Mljet）岛在地图上转入法国的直接统治。", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["苏呼米丧失给俄国——东黑海海岸的打开", "adc96bd4"], "d": ["在1806至1812年奥斯曼—俄国战争中，俄国舰队转向东黑海海岸，攻占了奥斯曼在阿布哈兹统治所依赖的苏呼姆卡莱。该城堡是与高加索部落联系和沿海贸易的中心。随着它的丧失，俄国首次永久地驻足黑海东岸；奥斯曼在高加索的影响被压缩到阿纳帕和波季一带。", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["帕尔加留给奥斯曼统治", "66e0cc5d"], "d": ["帕尔加自1401年起在威尼斯手中，从未归入奥斯曼统治；威尼斯覆灭之后，先后转归法国和英国。TDV的特佩德伦利·阿里帕夏条目概括了情况：该城向英国人投降，直到1819年才交给阿里帕夏统治。移交的结果是其居民的大部分迁往伊奥尼亚群岛。这样，在帕萨罗维茨留给威尼斯的普雷韦扎—帕尔加—沃尼察三城中的最后一个也并入了帝国；帕尔加将作为奥斯曼领土存续九十四年。", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["戈尔迪斯（科林斯）落入希腊起义者之手", "892dcdc6"], "d": ["在希腊独立战争期间，阿克罗科林斯落入起义者之手，城堡指挥官卡米勒贝伊被俘。", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["纳夫普利翁（Nauplion）丧失给起义者", "1a67fa50"], "d": ["作为摩里亚防御最强的港口的纳夫普利翁，在超过一年的封锁之后因饥饿而投降。该城堡自起义之初就是奥斯曼对半岛控制的最后一个大据点；它的丧失使整个摩里亚落入起义者之手。该城不久之后将成为新希腊国家的第一个首都。", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["勒班陀归入希腊统治", "c9d19d4b"], "d": ["直到希腊起义为止一直留在奥斯曼手中的科林斯湾北岸的勒班陀，于1829年4月丧失，并归入希腊统治；该镇的名称改回古代的纳夫帕克托斯。该城的穆斯林和犹太人口完全消失，这里成了一个小镇。", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["法国占领阿尔及尔——三百年军团的终结", "0be8f568"], "d": ["以一场源自债权纠纷的“扇击事件”为借口，法国封锁阿尔及利亚海岸三年，随后在西迪费鲁什登陆。经过三周的行动，侯赛因·德伊投降，自1516年延续的奥斯曼阿尔及尔军团就此终结。占领并未限于首都；内地的特莱姆森、舍尔沙勒和梅迪亚也在同一个夏天丧失。整个海岸落入法国控制又花了二十四年。", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["埃维亚割让给希腊——连同该岛（卡里斯托斯、奥雷奥伊）", "7b524aa4"], "d": ["在希腊独立战争期间经历激烈战斗但仍留在奥斯曼手中的埃维亚，在和平条约生效之后于1831年被交给希腊人。自1470年起即为重要海军基地的该城的穆斯林居民，以极低的价格变卖全部财产，成批迁往奥斯曼领土；该城长期空置，德国旅行家法尔梅赖尔1842年称其为一座幽灵之城。", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["法国占领瓦赫兰（奥兰）", "a8415d66"], "d": ["西班牙于1792年不战而移交的瓦赫兰，是阿尔及利亚西部最大的港口。首都陷落六个月后，法国部队进入该城。由此展开的西部行动，很快遇到埃米尔阿卜杜勒卡迪尔持续十五年的抵抗。", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["安纳巴（Bône）的占领", "21f37fb1"], "d": ["阿尔及利亚东部靠近突尼斯边界的港口安纳巴，被法军占领，成为向君士坦丁进军的基地。该城同时也是对着撒丁岛最近的非洲港口。", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["雅典让给新希腊国家（巴伐利亚部队接收卫城之日）", "deee4d37"], "d": ["自1456年起属于奥斯曼的雅典，在希腊独立战争期间数次易手，卫城的守军于1827年重新回到奥斯曼控制之下。由于它位于伦敦议定书所划边界的北侧，该城被移交给新王国，守军撤出卫城。地图集所取日期，是巴伐利亚部队接收卫城之日；奥斯曼守军的实际撤出发生在数日之后（St Clair，《Who Saved the Parthenon?》，Open Book Publishers，2022，第13章；Finlay，《Journals and Letters》，第1卷，第67页）。次年雅典取代纳夫普利翁被宣布为希腊首都。", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["贝贾亚（Bougie）的占领", "a8927e00"], "d": ["卡比利亚山脉向海洋敞开处的贝贾亚港，是阿尔及尔与安纳巴之间海岸线上最后一个独立环节。它在海军炮火的支援下被攻占；但其背后的山地内陆又三十年没有归入法国控制。这些沿海占领构成了奥斯曼阿尔及利亚在地图上逐年消融的过程。", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["塞提夫的占领", "2073731a"], "d": ["君士坦丁一年前陷落之后，法军登上高原，攻占古罗马城市塞提夫，并在此建立了长期守军。塞提夫是沿海与撒哈拉之间商队道路的交汇点；其占领表明法国此时已不仅控制港口，而且开始控制内陆贸易网络。", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["比斯克拉的占领——撒哈拉之门的丧失", "d895cad0"], "d": ["比斯克拉是阿特拉斯山南麓通往撒哈拉的门户和椰枣绿洲的中心。在埃米尔阿卜杜勒卡迪尔的抵抗开始被打破的年代，它的攻占使法国的控制首次抵达沙漠的北岸。此后便是逐绿洲推进的沙漠行动了。", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["图古尔特的占领——阿尔及利亚全境的丧失", "33c056e2"], "d": ["随着撒哈拉以北的绿洲城市图古尔特被攻占，自1830年开始的占领在今日阿尔及利亚的北半部完成。奥斯曼国家当时在克里米亚战争中与法国站在同一阵营；虽然从未正式放弃对阿尔及利亚的法律主张，但实际上无法迈出一步。北非留在手中的唯一领土是的黎波里塔尼亚。", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["乌拜伊德的陷落——科尔多凡转入马赫迪军队之手", "58299f62"], "d": ["自称马赫迪的穆罕默德·艾哈迈德发起的运动，迅速蔓延，反抗埃及在苏丹的统治。科尔多凡的中心乌拜伊德经过四个月的围攻而陷落，并成为起义的首都；城中的金库和武器库使该运动得以军队化。苏丹在法律上仍是隶属奥斯曼的埃及总督辖区的领土，因此这一损失在地图上从帝国本体中脱落。", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["喀土穆的陷落——整个苏丹的丧失", "d4b98464"], "d": ["经过十个月的围攻之后，马赫迪军队进入蓝尼罗河与白尼罗河交汇处的喀土穆；该城总督戈登被杀，前来救援的英军纵队晚到了两天。自此之后，包括森纳尔、栋古拉和科尔多凡在内的整个苏丹，在十四年间留在马赫迪国家的统治之下。该地区直到1899年才在奥斯曼联系被完全切断的状况下，归入英国—埃及共管。", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["意大利占领马萨瓦——红海西岸的丧失", "c333b95b"], "d": ["作为哈巴沙省中心的马萨瓦港，被利用马赫迪起义席卷苏丹所造成混乱的意大利占领；这构成了意大利厄立特里亚的核心。北面的萨瓦金和海中的达赫拉克群岛也在同一进程中丧失。这样，自“冷酷者”塞利姆苏丹时代起持续的奥斯曼在红海西岸的统治告终，红海从此两岸都成了外国之水。", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["意大利占领罗得岛", "e08662c5"], "d": ["在的黎波里塔尼亚战争中想迫使奥斯曼国家上谈判桌的意大利，把战争引向地中海，在罗得岛登陆。该岛在数日内被接收。1522年苏莱曼大帝经长期围攻夺取并据守三百九十年的罗得岛，由此不再是帝国在东地中海最大的岛屿基地；尽管在《乌希条约》中被视为临时占领，却再也没有被收回。", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["意大利占领十二群岛", "200aacf2"], "d": ["罗得岛被攻占后一周之内，意大利舰队也占领了周边岛屿；这一群岛后来被称为“十二群岛”。这些岛屿大多距安纳托利亚海岸仅数英里，控制着爱琴海东南部的通道。占领在《乌希条约》中被视为以割让的黎波里塔尼亚为条件的临时占领，但意大利从未撤出这些岛屿；它们将于1947年移交希腊。", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["科斯岛的占领", "ab246c62"], "d": ["作为十二群岛行动最后一环的科斯，是紧邻博德鲁姆半岛对岸的肥沃而人口稠密的岛屿。随着这一占领，爱琴海东南角的所有岛屿都归入意大利控制，安纳托利亚的西南海岸被一条外国岛链从头到尾环绕起来。", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["尼卡里亚宣布独立", "c4452033"], "d": ["在萨摩斯与希俄斯之间的小岛尼卡里亚，居民在意大利占领造成的不确定环境中起义，把奥斯曼宪兵逐出该岛，并宣布成立有自己的旗帜、邮票和议会、持续五个月的“自由国家”。1912年11月，该岛并入希腊。尽管规模很小，这一事件清楚地表明中央行政在爱琴海是如何瓦解的。", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["萨摩斯脱离奥斯曼统治", "3a862f2b"], "d": ["萨摩斯是自1832年起向奥斯曼纳税、由伊斯坦布尔任命的一位贝伊统治的自治公国。在的黎波里塔尼亚战争造成的空隙中，岛上主张合并的运动夺取了政权，自治公国体制实际终结；该岛于同年宣布并入希腊。距安纳托利亚海岸仅两公里的这座岛屿，成为爱琴海上最早丧失的土地之一。", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["约阿尼纳的陷落——伊庇鲁斯和帕尔加的丧失", "d42fce18"], "d": ["在巴尔干战争中被围攻五个月的约阿尼纳，在比扎尼阵地陷落之后投降；连同该城，整个伊庇鲁斯转归希腊。隶属约阿尼纳桑贾克的帕尔加也在这一日期丧失，九十四年的奥斯曼统治告终。约阿尼纳的丧失意味着帝国通向亚得里亚海的最后一扇窗户被关闭。", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["埃迪尔内陷落于保加利亚人", "459d2e56"], "d": ["经过五个半月的围攻，弹药和粮食耗尽的埃迪尔内投降；舍夫凯帕夏被俘。自1361年起属于奥斯曼并作了九十二年都城的这座城市的陷落，被视为巴尔干战争中最沉重的打击。四个月后，埃迪尔内将在第二次巴尔干战争中利用保加利亚在其他战线上的崩溃而被收回。", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["延布丧失给谢里夫侯赛因的军队", "e291c816"], "d": ["谢里夫侯赛因在六月发动的起义蔓延到红海海岸；麦地那的港口延布，在英国舰队的支援下落入起义者之手。该港口成为外部武器和金钱输入起义的主要门户。这样，麦地那的法赫雷丁帕夏部队与海洋的联系被切断，该城孤零零地留在汉志铁路的尽头。", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["第三次加沙战役——加沙与汗尤尼斯的丧失", "c142a069"], "d": ["经过两次失败的尝试后，艾伦比在第三次进攻中绕过贝尔谢巴突破战线，坚守了六个月的加沙防线崩溃。加沙与其南面的汗尤尼斯在同一天被撤空。这次突破成为巴勒斯坦战线瓦解的开端；耶路撒冷将在五周后陷落。", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["久木尔吉纳的占领——西色雷斯的丧失", "904d813c"], "d": ["穆德罗斯之后先处于协约国部队控制之下的西色雷斯，依圣雷莫会议的决定被让给希腊，希腊军队进入久木尔吉纳。1913年从保加利亚手中收回的该地区，成为帝国在鲁米利亚丧失的最后一块土地。该地区土耳其人口的地位，将于三年后在洛桑以少数群体制度加以安排。通过这一占领，西色雷斯的久木尔吉纳、伊斯凯切、杜拉萨奇和索福卢诸卡扎转归希腊。", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["伊尔汗国的瓦解：艾布·赛义德·巴哈杜尔汗去世", "0f187469"], "d": ["据TDV伊斯兰百科全书的伊尔汗国条目，艾布·赛义德未留继承人而去世，导致统治伊朗一个世纪的伊尔汗国解体；各埃米尔利用王位之争，建立了杰拉伊尔人、黑羊王朝、穆扎法尔王朝、呼罗珊的塞尔贝达尔王朝和埃雷特纳奥卢等地方王朝。这次瓦解把该地区分成了持续一个世纪的诸侯国马赛克；最终将通过帖木儿的征战再度统一。", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["帖木儿把伊朗大部分置于统治之下", "1cee2b82"], "d": ["据TDV伊斯兰百科全书的帖木儿条目，自1380年代初起逐一清除塞尔贝达尔王朝、克尔特王朝和穆扎法尔王朝等伊尔汗国后的地方王朝的帖木儿，在1386至1388年的“三年远征”期间，实际上把伊朗的大部分置于自己统治之下；对穆扎法尔王朝的最后了结则将在1393年进行。该地区由此在一个世纪的分裂之后重新归于单一的中央权威。", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["阿拉斯胜利：卡拉·优素福击败帖木儿王朝的艾布·巴克尔米尔扎", "4b61a75a"], "d": ["帖木儿于1405年去世后从流亡归来的黑羊王朝贝伊卡拉·优素福，在夺取阿夫尼克并重新占有东安纳托利亚领地之后，向被视为阿塞拜疆和两伊拉克之主的帖木儿之孙艾布·巴克尔米尔扎进军，并在阿拉斯河畔将其击败。这次胜利并未使大不里士归入黑羊王朝：TDV `tebriz` 记载该城1408年在艾布·巴克尔米尔扎手中；使阿塞拜疆得手的战役是1408年4月13日的塞尔德鲁德。", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["塞尔德鲁德胜利：大不里士和阿塞拜疆归入黑羊王朝", "1f0a429d"], "d": ["卡拉·优素福继阿拉斯之后，第二次在大不里士附近的塞尔德鲁德击败了帖木儿王朝的艾布·巴克尔米尔扎；这次胜利使黑羊王朝得到了阿塞拜疆。卡拉·优素福随后任命比斯塔姆贝伊负责征服波斯伊拉克；", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["伊斯坦布尔发生瘟疫与宫廷迁往埃迪尔内", "70c7a163"], "d": ["据TDV伊斯兰百科全书的伊斯坦布尔条目，该城迅速而密集的安置，为时而发生的流行病的蔓延创造了条件；1466年瘟疫流行期间，宫廷和国家要员暂时退往埃迪尔内。该城人口在此类疫情中蒙受了严重损失。", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["乌宗·哈桑终结黑羊王朝", "ef68399e"], "d": ["据TDV伊斯兰百科全书的乌宗·哈桑条目，白羊王朝君主乌宗·哈桑于伊历872年赖比尔·阿希尔月12日／1467年11月10日在宾格尔—桑贾克一带击败并杀死了黑羊王朝君主贾汉沙；贾汉沙之子哈桑·阿里于1468年9月在梅伦德战败，于1469年4至5月在哈马丹城前被杀，黑羊王朝由此最终终结。领土归入白羊王朝统治；该国在其后十年里将扩展到伊朗内陆。", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["萨赫恩·赛马内（八所）经学院开始授课", "021f2a83"], "d": ["据TDV伊斯兰百科全书的“萨赫恩·赛马内”条目，在法提赫建筑群之内设立的这八所经学院，被设计为当时最高水平的教学机构，构成了奥斯曼乌理玛等级制度的顶端。担任这里的穆德里斯及从这里毕业，在其后数个世纪里被视为卡迪和穆德里斯职业生涯中最受尊重的阶梯。", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["托普卡珀宫（新宫）的竣工", "d2db6323"], "d": ["据TDV伊斯兰百科全书的托普卡珀宫条目，当时的来源在建造的开始和结束日期上存在分歧；依据帝国之门铭文上的伊历883年（1478年）日期，按法提赫之命大概于1465年开始的建造到此时已基本完成，该宫取代了旧宫中的国家中心。这样，苏丹迁入了将在三个世纪里成为国家行政和礼仪之心的新住所。", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["巴耶塞特二世在伊斯坦布尔登基", "9b686d04"], "d": ["据TDV伊斯兰百科全书的巴耶塞特二世条目，时任阿马西亚桑贾克贝伊的王子巴耶塞特，在得知父亲去世的消息后迅速赶到伊斯坦布尔登基；借助耶尼切里的支持，把其弟杰姆自科尼亚的出发抛在了身后。登基时向耶尼切里发放了惯例的登基赏金。这次王位更替也点燃了兄弟二人之间斗争的导火索。", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["杰姆苏丹在布尔萨自立为苏丹", "b355168a"], "d": ["据TDV伊斯兰百科全书的杰姆苏丹条目，经卡拉曼抵达布尔萨的杰姆，占领该城并自立为苏丹，宣读了呼图白。这一短暂的统治，随着其兄巴耶塞特二世派出的军队在耶尼谢希尔击败杰姆而告终。战败之后，杰姆被迫逃向埃及。", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["盖迪克·艾哈迈德帕夏被处决", "6d75a58c"], "d": ["据TDV伊斯兰百科全书的盖迪克·艾哈迈德帕夏条目，以奥特朗托远征和大维齐尔之职著称的这位帕夏，因在杰姆苏丹问题上的态度以及对其势力的忧虑，奉巴耶塞特二世之命在埃迪尔内被处决。法提赫时代最有经验的指挥官之一的死，在宫廷中引起了广泛反响。", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["伊斯坦布尔建立第一家印刷所", "04475930"], "d": ["据TDV伊斯兰百科全书的印刷所条目，来自西班牙的犹太移民、兄弟大卫与撒母耳·伊本·纳赫米亚斯，在伊斯坦布尔创建了以希伯来文字母印刷的第一家印刷所。这被记录为在奥斯曼土地上活动的第一次印刷所尝试；土耳其语—阿拉伯文字的印刷则要到晚得多的18世纪才成为可能。", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["沙阿伊斯玛仪攻占大不里士：萨法维国家的建立", "014d81e6"], "d": ["据TDV伊斯兰百科全书的萨法维人和白羊王朝条目，阿尔达比勒道堂的年轻谢赫伊斯玛仪，率领由安纳托利亚红头军弟子组成的军队，在纳希切万一带使白羊王朝苏丹埃尔文德遭受惨败；埃尔文德逃往迪亚巴克尔，伊斯玛仪进入大不里士登上王位，并宣布十二伊玛目派为官方教派。这样，白羊王朝的统治和该地区伊尔汗国后诸侯国时代都告结束；将持续三个世纪的萨法维国家建立。", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["伊斯坦布尔的“小末日”地震", "53e3b1d6"], "d": ["据TDV伊斯兰百科全书的伊斯坦布尔条目，袭击该城的强烈地震在当时被民间称为“小末日”；城墙、清真寺和许多建筑受到严重损坏，造成大量人员死亡。奉巴耶塞特二世之命，城中开始了大规模的修复和建设动员。", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["沙库卢起义的开始", "3d9a4a90"], "d": ["据TDV伊斯兰百科全书的沙库卢·巴巴·特凯利条目，受萨法维宣传滋养的沙库卢，在泰凯地区把大批突厥蛮人聚集在自己周围，发动了具有宗教—社会性质的大起义。该起义作为当时最严重的内部安全危机之一，深深动摇了国家的中央权威。", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["巴耶塞特二世在前往迪迪莫特依霍的途中去世", "c46e98c9"], "d": ["退位之后离开伊斯坦布尔前往其出生地迪迪莫特依霍的这位前苏丹，乘坐每天只能前行五六公里的轿辇行进，在乔尔卢附近的阿巴拉尔村病倒，于伊历918年赖比尔·敖外鲁月25日（1512年6月10日）去世。TDV伊斯兰百科全书认为死因十分可疑；据一些本国和外国来源，强调他有可能被毒死。三十一年统治之后，奥斯曼加齐后裔中的第八位苏丹就此逝世。", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["艾哈迈德王子奉冷酷者塞利姆之命被处决", "65abb2f2"], "d": ["据TDV伊斯兰百科全书的塞利姆一世条目，作为其父巴耶塞特二世的宠儿、王位真正对手的艾哈迈德王子，在其兄塞利姆登基之后展开的斗争中，在耶尼谢希尔平原溃败，并在逃离战场时被抓获处死。通过这一事件，塞利姆在很大程度上终结了其兄弟和侄子之间的王位竞争。", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["易卜拉欣帕夏被任命为大维齐尔", "9c94c1e3"], "d": ["据TDV伊斯兰百科全书的易卜拉欣帕夏（马克布尔）条目，从哈斯奥达巴什升任鲁米利亚贝勒贝伊并于同日升为大维齐尔的易卜拉欣帕夏，于伊历929年舍尔邦月13日（1523年6月27日）成为大维齐尔。这是从宫廷服务直接升任大维齐尔的前所未见的任命，显示了易卜拉欣帕夏在苏莱曼大帝面前的非凡亲近。", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["巴巴罗萨·海雷丁帕夏被任命为海军总司令", "a0ff6bab"], "d": ["据TDV伊斯兰百科全书的巴巴罗萨·海雷丁帕夏条目，以在阿尔及尔的成就著称的海雷丁帕夏，于1534年4月6日被召到伊斯坦布尔，被任命为海军总司令和白海群岛贝勒贝伊。这一任命被视为奥斯曼舰队重组及其地中海海上力量制度化的开端。", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["吕斯泰姆帕夏首次出任大维齐尔", "ddfcc014"], "d": ["据TDV伊斯兰百科全书的吕斯泰姆帕夏条目，在哈德姆·苏莱曼帕夏因与一位维齐尔的纠纷而被解职之后，吕斯泰姆帕夏于伊历951年斋月17日（1544年12月2日）被任命为大维齐尔。借助与米赫丽玛赫苏丹的婚姻而与宫廷日益亲近的吕斯泰姆帕夏，凭此职成为苏莱曼大帝时代最有影响的国家人物之一。", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["艾卜苏欧德埃芬迪出任大穆夫提", "11ed04f8"], "d": ["据TDV伊斯兰百科全书的艾卜苏欧德埃芬迪条目，担任八年鲁米利亚大法官的艾卜苏欧德埃芬迪，于伊历952年舍尔邦月（1545年10月）被任命为大穆夫提，在该职位上待了二十八年十一个月。以使苏莱曼大帝的法典与伊斯兰教法相协调的教令著称的艾卜苏欧德埃芬迪，在其时代法律和教育机构的塑造中起了决定性作用。", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["巴巴罗萨·海雷丁帕夏去世", "3378a0bf"], "d": ["据TDV伊斯兰百科全书的巴巴罗萨·海雷丁帕夏条目，在一场短暂的疾病之后，他于伊历953年杰马迪·敖外鲁月6日（1546年7月5日）在伊斯坦布尔去世。他被安葬于贝西克塔什自己修建的经学院毗邻的陵墓中；巴巴罗萨之死被视为奥斯曼舰队所建立的地中海优势中一个时代的终结。", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["苏莱曼尼耶清真寺及建筑群开始修建", "101ec36f"], "d": ["据TDV伊斯兰百科全书的苏莱曼尼耶清真寺及建筑群条目，在建筑师希南主持下于1550年奠基的这一建筑群，被设计为除清真寺外还包括经学院、医院、施粥所和图书馆的大型社会建筑群。这项工程是象征苏莱曼大帝统治力量和伊斯坦布尔建设的最大建筑计划之一。", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["伊斯坦布尔及周边新一轮瘟疫开始", "547d6bf6"], "d": ["据TDV伊斯兰百科全书的“瘟疫”条目，影响伊斯兰世界的16世纪疫情之一发生在1552至1566年间，尤其在伊斯坦布尔、安纳托利亚、鲁米利亚、埃及和北非产生影响。不断扩展的贸易路线和不断增加的人口流动，被认为是在帝国最强盛时期使流行病更易传播的因素之一。", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["卡拉·艾哈迈德帕夏被任命为大维齐尔", "a7d7748e"], "d": ["据TDV伊斯兰百科全书的卡拉·艾哈迈德帕夏条目，担任第二维齐尔的卡拉·艾哈迈德帕夏，在时任大维齐尔被突然解职之后，于伊历960年闪瓦鲁月27日（1553年10月5日）被擢升为大维齐尔。这一更替，指向与穆斯塔法王子被处决同一时期、宫廷内部权力平衡迅速易手的时代。", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["海军总司令皮里·雷斯被处决", "3b2ad7a0"], "d": ["据TDV伊斯兰百科全书的皮里·雷斯条目，当关于他在解除霍尔木兹围攻时收受贿赂而劫掠穆斯林财物并在战场上抛弃军队的指控传到埃及时，这位著名的航海家和制图家于伊历960年末（1553年末）在开罗被处决。其财产被没收的皮里·雷斯之死，被视为当时巴士拉和印度洋海上政策中各帕夏之间竞争的结果。", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["卡拉·艾哈迈德帕夏被处决，吕斯泰姆帕夏再度出任大维齐尔", "9a85076a"], "d": ["据TDV伊斯兰百科全书的吕斯泰姆帕夏和卡拉·艾哈迈德帕夏条目，伊历962年都尔喀尔德月13日（1555年9月29日）在御前会议期间突然被处决的卡拉·艾哈迈德帕夏之位，在许蕾姆和米赫丽玛赫两位苏丹之女的支持下，由吕斯泰姆帕夏于同日第二次出任大维齐尔。该事件的幕后在来源中语焉不详，被认为是宫廷内部阴谋的结果。", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["许蕾姆苏丹去世", "1ae998b5"], "d": ["据TDV伊斯兰百科全书的许蕾姆苏丹条目，作为苏莱曼大帝的哈塞基苏丹多年在宫中拥有巨大影响力的许蕾姆苏丹，于伊历965年杰马迪·阿希尔月26日（1558年4月15日）在伊斯坦布尔去世，安葬于苏莱曼尼耶清真寺建筑群内的陵墓。在瓦利德苏丹哈芙莎于1534年去世后巩固了自己对后宫权威的许蕾姆苏丹之死，也消除了其子巴耶塞特与塞利姆之间王位竞争的缓冲作用。", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["索科鲁·穆罕默德帕夏升任大维齐尔", "896391a2"], "d": ["据TDV伊斯兰百科全书的索科鲁·穆罕默德帕夏条目，因塞米兹·阿里帕夏于伊历972年都尔喀尔德月30日（1565年6月29日）去世而升任大维齐尔的索科鲁·穆罕默德帕夏，成为苏莱曼大帝的最后一位大维齐尔，并在其后塞利姆二世和穆拉德三世时期继续担任该职，成为奥斯曼历史上任职时间最长的大维齐尔之一。", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["塞利姆二世抵达伊斯坦布尔登基", "0289ef97"], "d": ["苏莱曼大帝在锡盖特堡去世之后，为避免秩序混乱，消息被索科鲁·穆罕默德帕夏隐瞒了数周。据TDV伊斯兰百科全书，塞拉尼基给出的塞利姆抵达伊斯坦布尔的日期为伊历974年赖比尔·敖外鲁月15日（1566年9月30日），而当代历史学家多数认为赖比尔·敖外鲁月9日（9月24日）为是。苏莱曼大帝的死讯直到1566年10月24至25日才在贝尔格莱德正式宣布。", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["克勒奇·阿里帕夏重建的舰队下水", "d0fc9f48"], "d": ["勒班陀惨败（1571年10月7日）之后，整个冬天都在造船厂建造舰船。据TDV伊斯兰百科全书，伊历980年色法尔月1日（1572年6月13日），由250艘桨帆船和约300名志愿雷斯（船长）所组成的新舰队，以一场实力展示的形式下水。", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["索科鲁·穆罕默德帕夏遇刺身亡", "6ffa8dec"], "d": ["在三位苏丹时代出任十四年大维齐尔的索科鲁·穆罕默德帕夏，于伊历987年舍尔邦月20日（1579年10月12日），在其宅邸午后御前会议上，被一名装作要递交申诉书而走近的德尔维什用匕首刺死。据TDV伊斯兰百科全书，这次暗杀是否与被处决的哈姆扎维教团谢赫哈姆扎·巴利的复仇有关，尚有争论。", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["与英国签订首个贸易敕约——授予英国人治外法权", "59c8e3ee"], "d": ["1578年10月被派往伊斯坦布尔的英国代表威廉·哈伯恩，在索科鲁·穆罕默德帕夏和霍加·萨德丁埃芬迪的支持下，从穆拉德三世处获得了1580年的敕约。依据这一敕约，英国商人获得了同等享有此前给予法国人和威尼斯人的贸易特权（治外法权）的权利。女王伊丽莎白一世与穆拉德三世之间互通书信，两国之间也建立了正式关系。紧随这些特权之后，1581年在伦敦成立了黎凡特公司；英国人直到1825年都通过这家公司经营在该地区的贸易。", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["伊斯坦布尔天文台经御批手谕被拆毁", "3bc0c78c"], "d": ["受天文台会给国家带来不祥的教令以及宫廷内部反对意见的影响，伊斯坦布尔天文台于伊历987年都尔黑哲月4日（1580年1月22日）的一道御批手谕下，连同其中的全部仪器一起被拆毁。据TDV伊斯兰百科全书，这是塔基丁·拉希德所创建机构的短暂结局。", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["穆罕默德王子在竞技场的割礼庆典开始", "c2926d5d"], "d": ["穆拉德三世之子穆罕默德王子，在伊历990年杰马迪·敖外鲁月6日（1582年5月29日）开始、持续五十六至五十七天的盛大庆典中接受了割礼。据TDV伊斯兰百科全书，在竞技场举办的这些庆典，是其时代最辉煌的宫廷庆祝活动之一。", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["努尔巴努瓦利德苏丹去世", "77d0a577"], "d": ["穆拉德三世之母努尔巴努苏丹于伊历991年都尔喀尔德月22日（1583年12月7日）去世。据TDV伊斯兰百科全书，作为瓦利德苏丹，她与威尼斯和法国宫廷保持通信，威尼斯元老院同年同意因其服务而赠送她价值2000威尼斯金币的礼物。", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["因银币成色被降低，贝勒贝伊事件爆发", "db2f2e61"], "d": ["国家以降低阿克切银含量的方式支付之后，西帕希和耶尼切里包围宫殿，引发了以贝勒贝伊事件之名载入史册的流血骚乱。据TDV伊斯兰百科全书的阿卜杜勒卡迪尔·谢伊希埃芬迪条目，大穆夫提因这一事件被免职。", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["穆罕默德三世登基，十九名王子被勒死", "2cd9a8c5"], "d": ["穆罕默德三世在其父穆拉德三世去世后，于伊历1003年杰马迪·敖外鲁月16日（1595年1月27日）星期五抵达伊斯坦布尔并登基。据TDV伊斯兰百科全书，同一夜里十九名王子被勒死，其中四人已成年（穆斯塔法、巴耶塞特、奥斯曼和阿卜杜拉）；这是奥斯曼历史上人数最多的兄弟屠杀。", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["萨菲耶苏丹以瓦利德苏丹之身取得影响力", "000bec21"], "d": ["穆拉德三世的妻子、穆罕默德三世之母萨菲耶苏丹，随着其子的登基，以瓦利德苏丹的身份升至宫廷政治中的决定性地位。据TDV伊斯兰百科全书，这一时期源于后宫的影响，达到了直接干预国家事务的程度。", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["穆罕默德三世在耶尼切里压力下亲自出征", "d3c50656"], "d": ["尽管大维齐尔达马德·易卜拉欣帕夏反对，在耶尼切里的压力下，穆罕默德三世作为继苏莱曼大帝之后第一位亲自统率军队的苏丹，于1596年6月20日从伊斯坦布尔出征。据TDV伊斯兰百科全书，这意味着旧时圣战传统的复兴。", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["始于1570年代的瘟疫继续影响伊斯坦布尔", "eb4ca37a"], "d": ["据TDV伊斯兰百科全书的“瘟疫”条目，始于1570年代的疫情，其影响持续到17世纪初，以伊斯坦布尔为首，波及安纳托利亚、巴尔干、埃及和北非。疫情时期构成了经常中断宫廷和城市生活的长期威胁。", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["卡拉亚兹吉·阿卜杜勒哈利姆去世，起义运动衰弱", "876ca7a6"], "d": ["1601年8月12日在埃尔比斯坦附近的塞佩特利遭受惨败后负伤撤退的卡拉亚兹吉·阿卜杜勒哈利姆，于伊历1010年（1602年）去世。据TDV伊斯兰百科全书，死讯于伊历1010年斋月（1602年2至3月）传到伊斯坦布尔；来源指出，他的死是因伤所致还是由其手下所为尚有争论。", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["兄弟相杀传统实际终结", "9046c607"], "d": ["艾哈迈德一世登基时，与前几任苏丹不同，没有处死其弟穆斯塔法王子，而是饶了他的性命；这一决定被视为奥斯曼继承制度中长幼制（ekber-erşed）实际被采纳的开端。TDV伊斯兰百科全书的“穆斯塔法一世”条目记述，穆斯塔法此后在宫中过着幽居的生活。这一做法使数百年来的登基杀戮实际上走向终结。", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["苏丹艾哈迈德清真寺奠基", "1683262f"], "d": ["奉艾哈迈德一世之命，将由建筑师塞德夫卡尔·穆罕默德阿加修建的清真寺，在竞技场举行仪式奠基。据TDV伊斯兰百科全书的“苏丹艾哈迈德清真寺及建筑群”条目，该建筑因是没有征服胜利而直接由国库出资修建的第一座大型苏丹清真寺，也成为当时批评的话题。建筑群被设计为除清真寺外还包括经学院、施粥所和陵墓。", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["少年奥斯曼被耶尼切里杀害（奥斯曼之祸）", "324f6582"], "d": ["在传闻他以朝觐为借口出走伊斯坦布尔并计划解散耶尼切里军团之后，起事的耶尼切里和西帕希把奥斯曼二世废黜，并在七塔监狱将其勒死。据TDV伊斯兰百科全书的“奥斯曼二世”条目，该事件是奥斯曼历史上苏丹被公然以军事叛乱杀害的第一例，在王朝与军队的关系中造成了深刻的断裂。他的最后几个小时是这样度过的：投奔耶尼切里阿加阿里阿加宅邸的企图未果之后，用TDV的话说，苏丹“惨不忍睹地，光着头，衣衫凌乱地”被扶上一匹马，在遭受严重侮辱的情况下，先被带到穆斯塔法一世所在的奥尔塔清真寺，同一天下午又被带往七塔；据一些历史学家所述，为证明他已死，他的耳朵和鼻子被割下，拿给穆斯塔法一世之母看。事件之后穆斯塔法一世第二次被推上王位。被称为“奥斯曼之祸”（奥斯曼的灾难）的这一事件，永久地破坏了宫廷与军团的平衡，并开启了持续整整一个世纪的合法性争论。", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["穆斯塔法一世第二次登基", "34a0b29a"], "d": ["少年奥斯曼被耶尼切里杀害之后，由于王朝中没有其他成年男性成员，穆斯塔法一世第二次被推上王位。据TDV伊斯兰百科全书的“穆斯塔法一世”条目，这第二次统治与以前并无不同，同样未能实际处理国家事务，国家管理落到维齐尔们和瓦利德苏丹手中。这一持续十四个月的时期，于1623年穆拉德四世登基而结束。", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["杰巴利大火", "3e42fb08"], "d": ["在杰巴利起火、借风势迅速蔓延的大火，把伊斯坦布尔的大部分化为灰烬；据TDV伊斯兰百科全书的“伊斯坦布尔”条目，当时的来源记述数千户人家被烧毁。大火被与木结构房屋和吸烟联系起来，成为穆拉德四世不久后宣布的严厉烟草和咖啡馆禁令的直接理由。这场灾难只是当时伊斯坦布尔反复发生的大火之一。", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["穆拉德四世的烟草与咖啡馆禁令", "5dd71297"], "d": ["杰巴利大火之后，出于对火灾和治安的担忧，穆拉德四世禁止吸烟和开设咖啡馆；对违令者施以包括死刑在内的严厉处罚。据TDV伊斯兰百科全书的“穆拉德四世”条目，苏丹为监督禁令，甚至亲自微服在城中街道巡行，推行如此严格的内部纪律政策。这些严厉措施被视为穆拉德四世重建中央权威努力的一部分。", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["伊斯坦布尔瘟疫", "f33f58c5"], "d": ["穆拉德四世时期，伊斯坦布尔被一场影响很大一部分人口的严重瘟疫所震动；城内的贸易和日常生活中断数月。TDV伊斯兰百科全书的“伊斯坦布尔”条目记载，17世纪反复发生的疫情严重影响了该城的人口平衡。疫情期间，宫廷和上层人士曾一度迁往城外的花园和别墅。", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["赫扎尔芬·艾哈迈德·切莱比的翅膀飞行（传闻）", "df474c04"], "d": ["据埃夫利亚·切莱比所述的传闻，赫扎尔芬·艾哈迈德·切莱比用自制的翅膀从加拉塔塔跳下，滑翔到了于斯屈达尔；尽管其历史确凿性有争议，却成为技术想象力的象征。苏丹起初曾奖赏赫扎尔芬，后来因这一事件引起的反响，又把他流放到了阿尔及尔。", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["辛吉·霍加·侯赛因埃芬迪在宫中获得影响", "41d21572"], "d": ["为治疗苏丹易卜拉欣的精神烦恼而被召入宫中的术士侯赛因埃芬迪，很快获得苏丹信任，一直升到安纳托利亚大法官。据TDV伊斯兰百科全书的“辛吉·霍加，侯赛因埃芬迪”条目，他利用这一影响来积聚财富并干预当时的政治事件。易卜拉欣去世之后，他被免去全部职务，于1648年被处决。", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["凯曼凯什·穆斯塔法帕夏被处决", "0ecc8030"], "d": ["自穆拉德四世时期起担任大维齐尔、凭借财政改革使国库获得可观盈余的凯曼凯什·穆斯塔法帕夏，因宫廷内部对手影响易卜拉欣并指控他发动耶尼切里起义，而被勒死处决。据TDV伊斯兰百科全书的“凯曼凯什·穆斯塔法帕夏”条目，处决发生于伊历1053年都尔喀尔德月21日／1644年1月31日：凯曼凯什·卡拉·穆斯塔法帕夏在霍贾帕夏集市被刽子手卡拉·阿里勒死，并安葬于恰尔舍卡普他自己的陵墓。他的死被视为当时大维齐尔职位不稳定的突出例子，并终结了短暂而严厉的改革时期。", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["克里特远征在御前会议上决定与舰队启航", "9076827e"], "d": ["对威尼斯所属克里特岛展开大规模远征，在御前会议上被决定，由海军总司令指挥的奥斯曼舰队从伊斯坦布尔驶向克里特。据TDV伊斯兰百科全书的“克里特”条目，这一决定构成了持续约二十五年的漫长围攻与战争时期在政治上的开端。远征的发动作为易卜拉欣时期最大的对外政策举措，在国家要员中引起了广泛争论。", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["穆罕默德四世七岁登基", "a197a3bc"], "d": ["易卜拉欣被废黜之后，年仅七岁的其子穆罕默德被推上王位，以穆罕默德四世之名成为苏丹。据TDV伊斯兰百科全书的“穆罕默德四世”条目，如此年幼的登基，激化了其祖母科塞姆苏丹与其母图尔汉苏丹之间在宫中的影响力斗争。这一权力斗争将以1651年科塞姆苏丹被杀告终。", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["塔尔洪朱·艾哈迈德帕夏的平衡预算改革", "376fc7f2"], "d": ["大维齐尔塔尔洪朱·艾哈迈德帕夏，为克服长年战争造成的财政危机，推行包括宫廷开支在内的严厉节约方案，编制了奥斯曼历史上已知的第一份平衡预算（塔尔洪朱方案）。据TDV伊斯兰百科全书的“塔尔洪朱·艾哈迈德帕夏”条目，这一改革使国库获得可观盈余，但在宫廷圈子和高级官僚中引起广泛不满。这种不满将在一年后以他被处决告终。", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["悬树事件（瓦克瓦基耶事件）", "4c6ed90f"], "d": ["据TDV伊斯兰百科全书的悬树事件条目，从克里特远征归来未获发饷的耶尼切里和西帕希在伊斯坦布尔起事，要求处决被其指控贪腐的国家官员。大维齐尔祖尔纳泽恩·穆斯塔法帕夏提出的没收与流放建议未被接受；先是三名官员，随后近三十名国家官员被处决，尸体被悬挂在苏丹艾哈迈德广场的悬铃木上。该事件因此得名悬树事件。", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["柯普吕律·穆罕默德帕夏有条件接受而被任命为大维齐尔", "3a6b7f8f"], "d": ["据TDV伊斯兰百科全书的柯普吕律·穆罕默德帕夏条目，年近八十岁的柯普吕律·穆罕默德帕夏，在使瓦利德图尔汉苏丹和穆罕默德四世接受他提出的苛刻条件——不得干预其任命、不得相信对他的非议——之后才接过印玺。他于伊历1066年都尔喀尔德月26日接替博伊努埃格里·穆罕默德帕夏上任，开始严厉地重建国家纪律。", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["卡迪扎德派运动被柯普吕律·穆罕默德帕夏镇压", "5ec3ce84"], "d": ["据TDV伊斯兰百科全书的卡迪扎德派条目，柯普吕律·穆罕默德帕夏一上任，就着手处理卡迪扎德·穆罕默德埃芬迪周围与苏菲教团之间的宗教冲突。在咨询乌理玛之后，他对运动领袖于斯蒂瓦尼·穆罕默德埃芬迪、突厥人艾哈迈德和疯子穆斯塔法颁布了处决敕令，但此刑罚改为流放，三人被送往塞浦路斯；该运动的第二阶段由此终结。", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["伊斯坦布尔大火：阿加卡普苏被烧毁", "b9253b66"], "d": ["据TDV伊斯兰百科全书的阿加卡普苏条目，穆罕默德四世时期1660年7月发生的大火中，作为耶尼切里阿加正式驻地的阿加卡普苏被完全烧毁，随后重建。这场火灾是当时反复袭击伊斯坦布尔的大型城市火灾之一。", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["柯普吕律扎德·法济勒·艾哈迈德帕夏被任命为大维齐尔", "c1999b5c"], "d": ["据TDV伊斯兰百科全书的柯普吕律扎德·法济勒·艾哈迈德帕夏条目，在其父柯普吕律·穆罕默德帕夏去世之后，于伊历1072年赖比尔·敖外鲁月8日（1661年11月1日）被任命为大维齐尔。与其父不同，以性情温和、虔诚并是学者和艺术家庇护者而著称的法济勒·艾哈迈德帕夏，在其十五年多的大维齐尔任期内，在伊斯坦布尔和被征服的土地上设立了图书馆和慈善机构。", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["瓦尼·穆罕默德埃芬迪被任命为新清真寺的传道师和苏丹的教师", "7ea6aaae"], "d": ["据TDV伊斯兰百科全书的穆罕默德埃芬迪（瓦尼）条目，随着柯普吕律扎德·法济勒·艾哈迈德帕夏出任大维齐尔而被召到伊斯坦布尔并被引见给穆罕默德四世的瓦尼·穆罕默德埃芬迪，很快获得了苏丹的密切关注。1665年他被任命为新清真寺的传道师和苏丹的教师，成为宫中最有影响的宗教人士之一。", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["梅尔济丰卢·卡拉·穆斯塔法帕夏被任命为大维齐尔", "3d1e836c"], "d": ["据TDV伊斯兰百科全书的梅尔济丰卢·卡拉·穆斯塔法帕夏条目，在法济勒·艾哈迈德帕夏去世之后，于伊历1087年舍尔邦月28日（1676年11月5日）被任命为大维齐尔。作为柯普吕律家族的女婿和门生、在国家管理中拥有长期经验的梅尔济丰卢，成为穆罕默德四世最强大和最有影响力的大维齐尔之一。", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["瓦尼·穆罕默德埃芬迪在流放中去世", "cda714aa"], "d": ["据TDV伊斯兰百科全书的穆罕默德埃芬迪（瓦尼）条目，被视为说服苏丹接受维也纳远征的主要人物之一的瓦尼·穆罕默德埃芬迪，在远征以溃败告终之后，因舆论压力而失势，被流放到布尔萨的凯斯泰尔镇。他于伊历1096年都尔喀尔德月14日（1685年10月12日）在此去世，安葬于自己所建清真寺的入口处。", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["柯普吕律扎德·法济勒·穆斯塔法帕夏被任命为大维齐尔及其财政整顿", "b048570e"], "d": ["据TDV伊斯兰百科全书的柯普吕律扎德·法济勒·穆斯塔法帕夏条目，于伊历1101年穆哈兰月11日（1689年10月25日）被任命为大维齐尔的法济勒·穆斯塔法帕夏，依据教法原则重新整理了吉兹亚（人头税）的征收办法，与曼吉尔（铜币）通胀作斗争，并从宫廷机构调拨资源以增强国库。此外，他以可靠的官员加强了地方管理，并设立了类似中央御前会议的地方会议。", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["马利卡内制度生效", "316b8426"], "d": ["据TDV伊斯兰百科全书的马利卡内条目，17世纪最后二十五年间，战争开支增加以及土地丧失导致收入减少，使国库陷入严重的财政危机。伊历1106年（1695年）生效的马利卡内制度，给予包税人终身固定的征税权，以取代短期的榨取而鼓励保护生产。", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["穆斯塔法二世登基", "b53656c7"], "d": ["据TDV伊斯兰百科全书的穆斯塔法二世条目，三十一岁登基的穆斯塔法二世，没有等待大维齐尔和大穆夫提的批准便宣布了自己的统治；佩剑典礼数日后在旧清真寺举行。在维也纳溃败之后多线战争持续的时期登基的这位苏丹，成了奥斯曼历史上最后一位亲自出征的苏丹。", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["费伊祖拉埃芬迪第二次被任命为大穆夫提", "1cf14cff"], "d": ["据TDV伊斯兰百科全书的费伊祖拉埃芬迪（赛义德）条目，穆斯塔法二世登基之后，他于伊历1106年闪瓦鲁月11日（1695年5月25日）第二次被任命为大穆夫提。在其持续八年多的这一任期内，他对苏丹的影响逐渐增大。", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["费伊祖拉埃芬迪使其儿子们担任高位及积累的反应", "a6398280"], "d": ["据TDV伊斯兰百科全书的费伊祖拉埃芬迪（赛义德）条目，大穆夫提从穆斯塔法二世处取得了前所未见的敕令，规定其子费特胡拉埃芬迪在他之后担任大穆夫提，并把亲属年纪轻轻就安插到高位。这些做法在乌理玛阶层、军队和伊斯坦布尔民众中引起了广泛的不满；与迁都埃迪尔内的传闻结合，为1703年埃迪尔内事件奠定了基础。", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["埃迪尔内事件的开始", "5a106458"], "d": ["据TDV的“埃迪尔内事件”条目，由领不到军饷的士兵起事开始的这一运动，很快演变成耶尼切里、经学院学生、商人和民众共同参加的大规模起义。起义的真正目标是被指干预国家事务过度的大穆夫提费伊祖拉埃芬迪。约六万人的人群从伊斯坦布尔向埃迪尔内进发。", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["内夫谢希尔的达马德·易卜拉欣帕夏的大维齐尔任期", "8d627a6f"], "d": ["据TDV的“达马德·易卜拉欣帕夏（内夫谢希尔人）”条目，在与奥地利的和平谈判正在进行之际，他于伊历1130年杰马迪·阿希尔月8日（1718年5月9日）被任命为大维齐尔，一经任命便转向能结束战争的谈判；两个月后《帕萨罗维茨条约》签订（1718年7月21日）。用TDV的话说，他“想处理社会和财政问题，渴望一个能让人忘记多年来以失败告终的战争的和平时期”。他在财政上进行改革，降低了军饷，并使国库获得了可观盈余。他持续十二年的大维齐尔任期，构成了以其名命名的时代（郁金香时代）的政治框架。", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["图伦巴吉军团的建立", "f58b0d97"], "d": ["据TDV的“图伦巴吉”条目，从1715年摩里亚远征归来的真正的达乌德，因在伊斯坦布尔火灾中使用水泵（图伦巴）的成绩，大维齐尔内夫谢希尔的达马德·易卜拉欣帕夏委托他建立一个正式的消防军团。在阿杰米·奥卢兰兵营以六名军官和五十名士兵建立的该军团，1724年达到150人，1755年达到461人。达乌德一直留任军团首领，直到1733年去世。", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["穆罕默德埃芬迪被路易十五接见", "0ff5b174"], "d": ["据TDV的“二十八·切莱比·穆罕默德埃芬迪”条目，使节在杜伊勒里宫被法国国王路易十五正式接见，并呈上艾哈迈德三世的礼物和信函。访问期间，他参观了凡尔赛、特里亚农和马尔利诸宫殿、医院、天文台和工场；并以图画记录所见。", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["穆罕默德埃芬迪返回伊斯坦布尔", "a09a8bba"], "d": ["据TDV的“二十八·切莱比·穆罕默德埃芬迪”条目，从为期一年的巴黎使节任务返回的使节，其观察影响了郁金香时代的建筑品味。其子后来与易卜拉欣·穆特费里卡一起工作，为使节任务最持久的遗产——第一家土耳其印刷所的建立——奠定了基础。", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["萨达巴德宫的修建", "aec9c65e"], "d": ["据TDV的“萨达巴德”条目，在卡厄特哈内溪畔建起了一个受法国宫廷建筑启发、由宫殿、运河、喷泉和亭阁构成的大型游乐和休憩综合体。成为当时最受青睐游乐场所的萨达巴德，在诗人内迪姆的诗篇中得以不朽。该综合体在1730年帕特罗纳·哈利勒起义期间大部分被毁。", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["俄军占领杰尔宾特：彼得一世的里海远征", "c2b269f9"], "d": ["萨法维国家因阿富汗入侵陷入内乱之际，俄国沙皇彼得一世为夺取里海沿岸的伊朗土地而出征；沿海城市杰尔宾特未经显著抵抗便向俄军投降。据TDV伊斯兰百科全书的杰尔宾特条目，这次占领是将持续十三年的临时俄国统治的开端；奥斯曼国家也利用同一混乱，转向高加索西部。军队从阿斯特拉罕经海路抵达阿格拉汗湾，从那里沿海岸经塔尔库陆行；塔尔库的沙姆哈尔款待了彼得，并归入俄国的臣属。", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["塔尔库沙姆哈国的废除：俄国直接统治", "b0f029c6"], "d": ["1722年款待彼得并归入俄国臣属的塔尔库沙姆哈尔阿迪勒—吉雷，于1725年起事；叶罗普金于1725年秋摧毁了塔尔库，沙姆哈尔于1726年5月中旬被捕并遭流放，沙姆哈国被废除。塔尔库及其周边在1735年《占贾条约》之前一直处于俄国直接管辖之下。", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["准许易卜拉欣·穆特费里卡建立印刷所", "0659dd0a"], "d": ["据TDV的“易卜拉欣·穆特费里卡”条目，依艾哈迈德三世的敕令和大穆夫提耶尼谢希尔利·阿卜杜拉埃芬迪的教令，准许建立第一家土耳其印刷所。该印刷所在伊斯坦布尔的亚武兹塞利姆街区开始运作。穆特费里卡直到1747年去世，共印制了十七种、二十三卷著作。", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["第一部印刷书籍《万库鲁词典》完成", "684700e8"], "d": ["据TDV的“易卜拉欣·穆特费里卡”条目，印刷所的第一部作品、《西哈赫·朱瓦赫里》的土耳其语译本（《万库鲁词典》）于1729年初完成。这是在奥斯曼土地上以阿拉伯文字印刷的第一本书，被视为土耳其印刷史的开端。", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["内夫谢希尔的达马德·易卜拉欣帕夏被处决", "50c64341"], "d": ["据TDV的“达马德·易卜拉欣帕夏（内夫谢希尔人）”条目，在帕特罗纳·哈利勒起义期间于宫中被杀的大维齐尔，其尸体在伊斯坦布尔街头被拖行，并被丢弃在苏丹艾哈迈德广场的艾哈迈德三世喷泉附近。他十二年的大维齐尔任期和郁金香时代就此以流血的方式结束。", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["艾哈迈德三世退位，马哈茂德一世登基", "a43f5d40"], "d": ["据TDV的“马哈茂德一世”条目，面对起义者的压力，艾哈迈德三世为自己和孩子们取得保证后退位，亲自把侄子马哈茂德王子推上了王位。带着叔父“国事你自己掌管，不要相信任何人”的忠告登基的马哈茂德一世，首先着手削弱把他推上王位的起义团体的影响。", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["洪巴拉吉·艾哈迈德帕夏对炮兵军团的整顿", "ea3a7c64"], "d": ["据TDV的“洪巴拉吉”条目，皈依伊斯兰教的法国裔军官艾哈迈德帕夏，在大维齐尔哈基姆奥卢·阿里帕夏时期着手按欧洲方式整顿有薪的洪巴拉吉（榴弹兵）组织。他建立了直属大维齐尔、由300名领俸和301名领封地者共601人组成的新结构。以当时的技术，他还制造了100门臼炮和5万发炮弹。", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["亨德塞哈内（工程学校的第一个雏形）的建立", "a77ed1f3"], "d": ["据TDV的“马哈茂德一世”条目，洪巴拉吉·艾哈迈德帕夏在于斯屈达尔建立了亦称洪巴拉哈内的亨德塞哈内，对从宫廷仆役和园丁卫队中选出的学员进行以数学和几何为基础的军事教育。这一机构被视为后来发展的工程学校的最初范例。", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["《占贾条约》：杰尔宾特和巴库归还伊朗", "ff19d531"], "d": ["为应对奥斯曼的威胁而寻求与伊朗结盟的俄国，通过《占贾条约》，把占据十三年的里海沿岸城市归还给纳迪尔汗（尚未取得沙阿称号）指挥的伊朗。据TDV伊斯兰百科全书的杰尔宾特条目，这次撤退是俄国不愿在南方同时与奥斯曼和伊朗两线作战的结果，并巩固了为纳迪尔数年后登上王位开辟道路的军事声望。处于俄国管辖下的塔尔基（塔尔库）也随这次撤退转向伊朗一方（地图上使用占贾之日）。处于俄国管辖下的萨尔扬和沙布兰也随这次撤退转向伊朗一方（来源中没有这些居民点专属的日期，地图上使用占贾之日——声明为近似）。", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["纳迪尔沙在穆甘草原登基：萨法维王朝的实际终结", "4f640979"], "d": ["据TDV伊斯兰百科全书的纳迪尔沙条目，在穆甘草原集会的约两万人的忽里勒台坚持要他出任伊朗之主；纳迪尔以放弃造成萨法维人与奥斯曼人之间战争的极端什叶派观念、采纳温和的贾法里教派为条件接受这一提议，于伊历1148年闪瓦鲁月24日（1736年3月8日）以纳迪尔沙之称号登基。这意味着两个世纪之久的萨法维王朝实际终结，阿夫沙尔王朝建立。", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["伊斯坦布尔瘟疫的开始", "9fa82b56"], "d": ["据TDV的“瘟疫”条目，1739至1743年间在伊斯兰地区产生影响的瘟疫，在此时也袭击了伊斯坦布尔。该条目指出，18世纪的疫情与此前几个世纪相比相对较轻。疫情时期中还列有1713年、1719年、1728至1729年及1759至1765年。", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["霍贾帕夏大火", "321c7d0d"], "d": ["据TDV的“法特玛苏丹清真寺”条目，夜间发生的霍贾帕夏大火毁坏了高门及其周边；该地区的法特玛苏丹清真寺据推测也受到这场火灾的损害。作为奥斯曼三世时期袭击伊斯坦布尔的大火之一，这场灾难对该城的商业和行政中心造成了严重破坏。", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["科贾·拉吉普·穆罕默德帕夏的大维齐尔任期", "a1846910"], "d": ["以诗人和外交家身份著称的拉吉普帕夏，被奥斯曼三世任命为大维齐尔（1757年10月奥斯曼三世去世后继续任职，从穆斯塔法三世处领取了新印玺）。在七年战争持续期间，他奉行平衡的对外政策，使奥斯曼国家置身于欧洲冲突之外。在其持续六年的大维齐尔任期内，他还重视设立图书馆等文化活动。", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["拉吉普帕夏去世", "6bc19323"], "d": ["拉吉普帕夏在为期六年的大维齐尔任期之后去世。随着他的去世，穆斯塔法三世时期最持久而平衡的大维齐尔任期告终。", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["伊斯坦布尔大地震与法提赫清真寺的倒塌", "2475b4dc"], "d": ["据TDV的“法提赫清真寺及建筑群”条目，在1766年的大地震中，清真寺的主圆顶完全坍塌，墙壁受损到无法修复的程度。奉穆斯塔法三世之命，在建筑师萨勒姆·易卜拉欣埃芬迪和伊泽特·穆罕默德贝伊主持下于1767年开始的重建，以不同于旧平面的新设计于1771年完成。", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["以德·托特男爵为首的短命炮兵学校尝试", "4192260c"], "d": ["据TDV的“皇家海军工程学校”条目，1768年奥斯曼—俄国战争中的失利暴露了对技术性军事教育的需求；在法国军官德·托特男爵的参与下开办的短命炮兵学校于1772年10月开始运作，但收效甚微。这次尝试被视为1775年建立的皇家海军工程学校的先驱。", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["塞利姆三世登基", "00d046d9"], "d": ["阿卜杜勒哈米德一世去世之后，其侄塞利姆三世继位。据TDV伊斯兰百科全书的塞利姆三世条目，自王子时代起就对整顿欧洲军队感兴趣的新苏丹，在登基后不久就开始着手准备一个彻底更新的方案。这一方案数年后将被称为新秩序（尼扎姆·杰迪德）。", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["新秩序改革方案开始筹备", "eff78a68"], "d": ["塞利姆三世依据向国家要员和外国专家征求的意见书，筹备了一个全面更新的方案。据TDV伊斯兰百科全书的新秩序条目，该方案并不仅限于建立新军队；而是演变成涵盖财政、地方管理和外交的广泛改革运动。在其后十五年里，该方案既有支持者也有反对者。", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["向欧洲各首都设立常驻使馆", "2e9dc8a1"], "d": ["塞利姆三世在奥斯曼国家历史上首次向欧洲各大中心派出长期任职的常驻使节。据TDV伊斯兰百科全书的“使节”条目，这一步骤使此前仅通过临时性、一次性使团进行的奥斯曼外交获得了长期性的机构。新使馆的主要任务是定期向伊斯坦布尔通报欧洲的政治和军事动态。", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["伊拉德·杰迪德国库设立", "ae5c8ce2"], "d": ["为支付新秩序军队和改革方案的开支，设立了单独的国库。据TDV伊斯兰百科全书的“股票（埃沙姆）”条目，新国库的收入包括某些穆卡塔阿由国家直接经营以及对埃沙姆销售加以管控。这一安排是在传统财政制度之外创造新来源的尝试。", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["卡巴克奇·穆斯塔法起义开始", "b98eee17"], "d": ["对新秩序积累的不满，以雅马克士兵在卡巴克奇·穆斯塔法率领下起义的方式爆发。据TDV伊斯兰百科全书的卡巴克奇起义条目，起义者很快控制了伊斯坦布尔，并要求交出支持新秩序的国家要员的首级。起义在数日内以塞利姆三世被废黜告终。", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["塞利姆三世被废黜", "ff2c30ec"], "d": ["在卡巴克奇·穆斯塔法起义的压力下，依据从大穆夫提处取得的教令，塞利姆三世被废黜。据TDV伊斯兰百科全书的塞利姆三世条目，这一决定是持续十八年的改革时期实际终结的时刻；新秩序军队也在不久后被解散。塞利姆被开始软禁在托普卡珀宫中。", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["穆斯塔法四世登基", "8f1ac86c"], "d": ["塞利姆三世被废黜之后，其侄穆斯塔法四世随即被宣布为苏丹。据TDV伊斯兰百科全书的穆斯塔法四世条目，新苏丹是在支持起义的反新秩序圈子的影响下开始统治的。这一短暂时期，成为中央权威彻底衰弱的动荡阶段。", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["阿勒姆达尔·穆斯塔法帕夏率军进入伊斯坦布尔", "0cad3dea"], "d": ["鲁斯丘克的地方显贵阿勒姆达尔·穆斯塔法帕夏，为使塞利姆三世复位，率军抵达伊斯坦布尔城外。据TDV伊斯兰百科全书的阿勒姆达尔·穆斯塔法帕夏条目，他入城时由穆斯塔法四世亲自迎接；但数日之内，宫中的力量平衡将完全改变。这次入城开启了以塞利姆之死和一次新的登基为结果的事件链。", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["塞利姆三世被杀", "e452f5f6"], "d": ["阿勒姆达尔·穆斯塔法帕夏占领高门的那天，塞利姆三世奉穆斯塔法四世之命在宫中被杀。据TDV伊斯兰百科全书的塞利姆三世条目，这是为阻止被废黜苏丹复位的企图而作出的决定。塞利姆之死，以同日马哈茂德登基告终。", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["马哈茂德二世登基", "661c1974"], "d": ["塞利姆三世被杀之后成为王朝唯一男性成员的马哈茂德，在阿勒姆达尔·穆斯塔法帕夏的支持下登基。据TDV伊斯兰百科全书的马哈茂德二世条目，新苏丹在统治头几个月里，处于把他推上王位的阿勒姆达尔的监护之下，并致力于重建地方显贵与中央之间的平衡。这一时期成为其后二十年彻底改革进程的开端。", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["塞克班·杰迪德军队建立", "6f9eb5e4"], "d": ["阿勒姆达尔·穆斯塔法帕夏，建立了配备欧洲式装备的新军，以取代被解散的新秩序军。据TDV伊斯兰百科全书的塞克班·杰迪德条目，由三个团组成的这支力量，在耶尼切里眼中被视为直接威胁，建立仅数月后便在一次耶尼切里起义中被消灭。", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["伊布赖拉的陷落——多瑙河防线的第一个大缺口", "ee519321"], "d": ["在1806年开始的俄国战争中，多瑙河北岸的伊布赖拉城堡被卡明斯基伯爵指挥的俄军围攻并遭炮击。城内有4100名步兵、1100名骑兵和260门火炮；城堡因粮食短缺向埃森将军投降。多瑙河防线的北端由此被打开。", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["鲁斯丘克的投降——多瑙河南岸也在丧失", "084062e8"], "d": ["鲁斯丘克抵抗了卡明斯基伯爵指挥的俄军漫长而血腥的围攻；以守军和平民安全离城为条件投降。多瑙河南岸最坚固的堡垒城市的陷落，使战争进程转向有利于俄国。", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["埃什金吉军团建立", "67c56759"], "d": ["马哈茂德二世，以从耶尼切里军团中挑选的士兵，建立了一支将按欧洲方式受训的新部队。据TDV伊斯兰百科全书的埃什金吉军团条目，该部队于1826年6月12日开始训练，但耶尼切里视之为自己军团的末日。三天后爆发的起义，也终结了埃什金吉军团的短暂寿命。", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["穆罕默德常胜军（阿萨基尔·曼苏尔·穆罕默迪耶）建立", "14b84a7e"], "d": ["耶尼切里军团被废除之后，马哈茂德二世随即建立了一支正规的、受欧洲式训练的新军取代它。据TDV伊斯兰百科全书的“阿萨基尔·曼苏尔·穆罕默迪耶”条目，这支军队凭借军阶制度、训练方案和薪饷制度，与此前的尝试不同，成为长期性的机构。该军在其后数年将演变为坦齐马特时期的尼扎米耶军队。", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["贝克塔什教团被取缔", "f7d9a367"], "d": ["在耶尼切里军团被废除的同时，与军团有宗教联系的贝克塔什教团也被禁止。据TDV伊斯兰百科全书的贝克塔什教条目，一些小型苏菲道堂的谢赫被处决，而哈吉贝克塔什道堂的谢赫被流放到阿马西亚，各道堂被移交给纳克什班迪教团管理。该教团尽管遭受这一重大打击，仍秘密继续其组织活动。", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["扇击事件——占领的借口", "e949001e"], "d": ["在法国未偿还阿尔及尔旧有粮食债务而紧张的会谈中，德伊侯赛因用手中的扇子击打了法国领事德瓦尔。这起源自债权纠纷的事件，被作为三年后开始的占领的官方借口。", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["法国对阿尔及利亚海岸的封锁——持续三年的围困", "d0ba97a5"], "d": ["扇击事件之后，法国封锁了阿尔及利亚海岸。封锁持续了三年；军团的海上贸易和收入来源被切断，其抵抗力量在占领开始之前就已被侵蚀。", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["《土库曼恰伊条约》：埃里温和塔雷什转归俄国", "abffcfdb"], "d": ["1826至1828年俄伊战争以伊朗的惨败告终，依在土库曼恰伊签订的条约，埃里温和纳希切万两汗国及里海岸的塔雷什地区（伦科兰、阿斯塔拉）被让给俄国；并课以沉重的战争赔款。据TDV伊斯兰百科全书的埃里温条目，这一损失是高加索俄伊边界划定的时刻，该边界在很大程度上沿用至今，并引发亚美尼亚人口迁往埃里温。通过这一条约，埃里温汗国（埃奇米阿津、伊迪尔、诺拉帕特、贝里）和纳希切万汗国（朱尔法、舍吕尔）转归俄国。", "847d76d5"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["伊布赖拉第二次陷落——沙皇尼古拉在城堡前", "eb6a8741"], "d": ["1812年归还给奥斯曼人并于1817至1818年重新加固的伊布赖拉，在城内有4000名守军和278门火炮的情况下，于四月被围攻。守将埃布贝克尔帕夏建立了新的防线；沙皇尼古拉一世于五月底亲自来到城堡前。该城遭到俄国占领，但依《埃迪尔内条约》将被归还并留给瓦拉几亚公国。", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["菲斯帽被宣布为正式头饰", "f55be4eb"], "d": ["马哈茂德二世对官员和军人的服装进行了彻底改变，宣布以菲斯帽取代缠头巾作为正式头饰。据TDV伊斯兰百科全书的菲斯帽条目，这一决定通过一道御批手谕公布，并与穆罕默德常胜军的西式改革一起付诸实施。这一变化也意味着传统服饰等级制度的终结。", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["阿哈尔齐赫割让给俄国——乔尔德尔行省的中心丧失", "e2e00b2a"], "d": ["自1578年乔尔德尔战役以来处于奥斯曼统治之下并充当乔尔德尔行省中心的阿哈尔齐赫，在1828至1829年战争结束时签订的《埃迪尔内条约》中被割让给俄国。该城的丧失在民众中引起深切悲痛，成为许多挽歌的题材。通过这一事件，阿哈尔卡拉基、扎扎洛和茨卡尔特比拉（阿哈尔齐赫—阿哈尔卡拉基地区）转归俄国。", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["西迪费鲁什登陆——法军踏上阿尔及利亚土地", "33327553"], "d": ["三年封锁之后，布尔蒙伯爵指挥的法国登陆军在阿尔及利亚西部的西迪费鲁什海湾登陆。向该城推进的部队在三周内突破了防线；7月4日，控制该城的皇帝堡陷落，次日德伊侯赛因投降。", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["德伊侯赛因的流放——阿尔及尔军团的实际终结", "e122403b"], "d": ["依据投降条件，阿尔及尔末代德伊侯赛因连同其家人和财宝被逐出该城，送往那不勒斯。1519年归附塞利姆一世（冷酷者）、三个世纪间作为地中海最强大的奥斯曼海军基地的这一军团的统治就此终结。", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["俄军撤出瓦拉几亚和摩尔达维亚——六年占领的终结", "efdb0275"], "d": ["1828至1829年奥斯曼—俄国战争中，俄国人占领了瓦拉几亚和摩尔达维亚，《埃迪尔内条约》之后在战争赔款付清之前也未撤出。1834年1月赔款降至五百万之后，俄军撤出了多瑙两公国，并向两公国任命了新的大公。奥斯曼宗主权在纸面上得以恢复，但俄国保持了凭《组织规程》建立的影响。", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["常胜军后备军（雷迪夫）组织建立", "15947493"], "d": ["作为支援穆罕默德常胜军的后备力量，雷迪夫组织依1834年7月8日的条例建立。据TDV伊斯兰百科全书的雷迪夫条目，在塞拉斯克尔科贾·胡斯雷夫帕夏主持下，在各省卡扎组建了每营约一千四百人的营。该组织被设计为无需长期征召也可支持地方治安。", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["外交部建立", "750c6c7d"], "d": ["马哈茂德二世废除了办理外交事务的帝国书记官长之职，设立外交部取而代之。据TDV伊斯兰百科全书的外交部条目，新部的首任大臣由穆罕默德·阿基夫帕夏担任，该机构在维也纳大使里法特贝伊的宅邸开始运作。这一安排成为奥斯曼外交按现代部门原则运行的开端。", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["最高司法法令会议设立", "69db056e"], "d": ["马哈茂德二世设立了最高司法法令会议，作为讨论将要制定的法律和条例的高级会议。据TDV伊斯兰百科全书的该会议条目，会议于1838年3月31日实际开始工作，其后坦齐马特的几乎所有改革都经由该会议筹备和审查。该机构成为现代奥斯曼官僚体制最重要的中心之一。", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["锡诺普突袭", "5947e93f"], "d": ["俄国黑海舰队在纳希莫夫海军上将指挥下，未经宣战便对停泊在锡诺普港的奥斯曼舰队发动突袭；十二艘船被击沉，两千多名士兵殉难，舰队司令奥斯曼帕夏被俘。据TDV伊斯兰百科全书的锡诺普条目，突袭中城中的七座小清真寺、两所学堂、247座房屋和170家店铺被烧毁，五名穆斯林和十六名基督徒平民丧生。在欧洲舆论中被称为“锡诺普惨案”的这一事件，成为英国和法国数月内站在奥斯曼一边参战的直接导火索。", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["《舆论之镜》创刊", "506c98e2"], "d": ["辛纳西创办的《舆论之镜》，继《事件年鉴》、《事件报》和《状况翻译报》之后，作为第四份土耳其语报纸开始出版。据TDV的“舆论之镜”条目，该报在后来出任主笔的纳米克·凯末尔时期，成为新奥斯曼人运动的喉舌。", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["新奥斯曼人协会成立", "335fb02d"], "d": ["在穆斯塔法·法济勒帕夏带领下逃往欧洲的奥斯曼知识分子，以十三条章程的规章，以“青年土耳其”之名组织起来。据TDV的“新奥斯曼人协会”条目，该团体在巴黎、伦敦和日内瓦出版《通报》和《自由》等报纸，传播立宪政体的主张。", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["国务会议设立", "b863b306"], "d": ["司法法令会议被一分为二，设立了办理行政事务的国务会议和负责司法事务的司法法令司。据TDV的“国务会议”条目，以法国国务委员会为模式的该机构，首任主席由米德哈特帕夏担任；目的在于使立法、行政与司法相互分离。", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["大学（达鲁尔菲农）设立谕旨颁布", "513704bf"], "d": ["凭大维齐尔阿里帕夏和教育大臣萨夫韦特帕夏拟定的谕旨，大学正式设立；而首批课程此前已于1863年开始。据TDV的“大学（达鲁尔菲农）”条目，该机构于1870年2月在霍贾·塔赫辛埃芬迪任校长之下，以哲学与文学、理学和法学各系实际开始教学。", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["《法典汇编》（美杰莱）的编纂工作开始", "8abdcbee"], "d": ["在司法法令司主席艾哈迈德·杰夫代特帕夏主持下成立的美杰莱委员会，着手准备一部以哈乃斐教法为基础的民法典。据TDV的“《司法法令汇编》（美杰莱）”条目，由十六卷、1851条构成的这部著作，最后一册于1876年9月15日完成并生效；它被视为伊斯兰法的第一次法典化形式。", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["《祖国或锡利斯特拉》上演，纳米克·凯末尔被流放", "3861284c"], "d": ["纳米克·凯末尔以爱国为主题的剧作在盖迪克帕夏剧院上演时，观众高呼“祖国万岁，凯末尔万岁”涌上街头。据TDV的“纳米克·凯末尔”条目，政府被这场示威吓到，关闭了《教训报》，并于1873年4月6日未经审判便把纳米克·凯末尔流放到塞浦路斯（法马古斯塔）。", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["阿卜杜勒阿齐兹可疑身亡", "85816692"], "d": ["被废黜后依自己的意愿转往费里耶宫（1876年6月1日）的阿卜杜勒阿齐兹，于6月4日被发现在其房间里手腕动脉被割断。包括使馆医生在内的十九人医生小组拟出了措辞含糊的报告；6月6日报纸宣布死亡为自杀。阿卜杜勒哈米德二世下令展开的调查则得出结论认为死亡不是自杀而是谋杀，被告于1881年在耶尔德兹法庭受审；这一问题在史学上至今仍有争论。", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["米德哈特帕夏被解除大维齐尔职务并流放", "b5247b06"], "d": ["《基本法》的设计者大维齐尔米德哈特帕夏，在宣布后六周被阿卜杜勒哈米德二世解职，一夜之间被流放出境。据TDV伊斯兰百科全书的米德哈特帕夏条目，罢免与苏丹对宪法中限制其权力的条款感到不安有关。帕夏先到那不勒斯，然后前往欧洲各城市。", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["阿卜杜勒阿齐兹·本·沙特从拉希德家族手中夺回利雅得", "75eb8830"], "d": ["十年前流亡科威特的沙特王室年轻成员阿卜杜勒阿齐兹，以一支小分队突袭利雅得，杀死阿勒·拉希德（沙姆马尔）的总督代理，夺取了该城。据TDV伊斯兰百科全书的利雅得条目，拉希德家族的日渐衰弱以及无法向该城派出增援，使这次突袭得以成功；该事件被视为其后三十年将构成今日沙特阿拉伯核心的第二沙特国家的建立时刻。", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["行动军进入伊斯坦布尔", "41c8304c"], "d": ["从萨洛尼卡出发、大部分由属于统一与进步党的部队组成的行动军，为镇压3月31日起义而进入伊斯坦布尔。据TDV伊斯兰百科全书的行动军条目，指挥由马哈茂德·舍夫凯特帕夏担任，参谋长由科拉加西穆斯塔法·凯末尔担任。经过短暂交战后，城中重新恢复了治安。", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["最后一届奥斯曼国民议会被解散", "2b709269"], "d": ["在伊斯坦布尔被协约国军队正式占领以及许多议员被捕之后，国民议会已无法运作，并依穆罕默德六世的谕旨被正式解散。据TDV伊斯兰百科全书的国民议会条目，这次解散象征着奥斯曼立宪议会传统的实际终结。关闭加强了在安卡拉召开新的民族议会的必要性。", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["土耳其大国民议会开幕", "6eab539d"], "d": ["伊斯坦布尔的国民议会被解散之后，议员们在安卡拉集会，开启了土耳其大国民议会，穆斯塔法·凯末尔帕夏当选议长。据TDV伊斯兰百科全书的土耳其大国民议会条目，该议会具有把立法和行政权力集于一身的非常性质。这次开幕是民族斗争的政治与制度中心迁往安卡拉的转折点。通过这一事件，包括科尼亚、锡瓦斯、开塞利、埃斯基谢希尔、埃尔祖鲁姆、特拉布宗、萨姆松、迪亚巴克尔、凡城、马拉蒂亚、代尼兹利和伊斯帕尔塔在内的124处居民点（土耳其未被占领的地区）归入大国民议会政府的管理。", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["兹沃尔尼克（Zvornik）城堡的征服", "657c465a"], "d": ["德里纳河畔的兹沃尔尼克城堡于1460年被奥斯曼征服。据TDV伊斯兰百科全书，由于其行政和军事上有利的位置，先被设为卡扎中心，1480年被改设为同名桑贾克的中心，1491年以石墙加固，凭借六座清真寺、八所道堂和浴场成为重要的行政—商业中心。", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["卡西姆汗去世，达尼亚尔汗登基（卡西莫夫汗国）", "522fd0fd"], "d": ["汗国的创建者卡西姆汗于伊历873年／1468年去世，其子达尼亚尔继位；达尼亚尔统治到1486年。", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["第乌海战——葡萄牙在印度洋的优势", "1778d347"], "d": ["以古吉拉特苏丹国名义治理该地区的马利克·阿亚兹的马穆鲁克支持的舰队，在第乌外海对葡萄牙总督弗朗西斯科·德·阿尔梅达试图在这些海岸建立补给基地的舰队遭受惨败。这次失败使葡萄牙获得了在印度洋的长期海上优势，并粉碎了马穆鲁克—古吉拉特的海上力量；它被视为构成奥斯曼1517年之后接手的红海—印度洋斗争（吉达防御、1538年第乌围攻）背景的力量失衡的开端。", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["卡伦德尔沙起义", "f60f6ca4"], "d": ["在安纳托利亚的财政困难、对新行政安排的不满以及萨法维宣传的影响下，奇切克利、阿克科云鲁、马萨德利和博佐克鲁等大突厥蛮部落，以及此前巴巴·祖努恩起义遗留的团体，聚集在卡伦德尔沙周围，达到约三万人的力量。起义者先是击败了鲁姆贝勒贝伊；随着大维齐尔马克布勒·易卜拉欣帕夏征召军队并许诺其权益，卡伦德尔的支持逐渐消散，起义在埃尔比斯坦一带被镇压，卡伦德尔沙和韦利·丹达尔于1527年6月被杀。", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["舍赫里佐尔的征服——扎尔姆城堡的攻占", "4320d9b8"], "d": ["在苏莱曼大帝的纳希切万远征期间，巴格达贝勒贝伊奥斯曼帕夏被委派占领舍赫里佐尔地区；在他去世后成为巴格达贝勒贝伊的巴尔塔吉·穆罕默德帕夏，围攻了该地区的中心城堡扎尔姆，于1554年8月22日（伊历961年斋月23日）将其攻占。这样，扎格罗斯山西坡的舍赫里佐尔盆地归入奥斯曼统治，巴格达与库尔德斯坦之间的联系得到保障；该地区先被设为桑贾克，交给穆拉德贝伊。1563年贝勒贝伊穆扎法尔帕夏修建了古拉姆贝尔城堡，作为新行省的中心；该城堡将于1623年依沙阿巴斯之命被拆毁，1638年在胡斯雷夫帕夏时期重建。", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["卡西莫夫汗国君主皈依基督教并被免去汗位", "a1a8eeb9"], "d": ["汗国的首领取名“谢苗（西缅）”并成为基督徒；俄国人考虑到穆斯林臣民的反应，将他从汗位上撤下。此人不久后被恐怖的伊凡以“沙皇与全俄罗斯大公”的称号，于莫斯科宣布为名义上的统治者（1575年）——这是卡西莫夫汗国与莫斯科王位之间最引人注目的交会。", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["费赞桑贾克并入的黎波里塔尼亚——穆尔祖克与撒哈拉商队枢纽", "2e6554a4"], "d": ["在的黎波里塔尼亚贝勒贝伊区的压力下，撒哈拉商队枢纽费赞以穆尔祖克为中心接受了奥斯曼的臣属地位。据TDV伊斯兰百科全书的费赞条目，统治该地区的埃夫拉德·穆罕默德王朝，在定期纳税的条件下被保留内政自主；费赞被组织为隶属1551年攻占的的黎波里行省的桑贾克。这样，的黎波里—穆尔祖克—博尔努一线的奴隶、黄金和骆驼贸易归入奥斯曼控制。这种间接统治将于1711年落入卡拉曼利家族之手，1842年则落入直接的卡扎组织之手。", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["纳希切万与奥尔杜巴德归入奥斯曼统治", "24d939b3"], "d": ["1583年埃里温被攻占并被设为贝勒贝伊区中心之后，沿阿拉斯河谷向东南推进的部队，把纳希切万和奥尔杜巴德纳入奥斯曼统治；两座城市成为新建埃里温行省的桑贾克。据TDV伊斯兰百科全书的纳希切万条目，该城的首次长期奥斯曼统治是在这场战争期间建立的——1553年的纳希切万远征中虽曾攻占该城，但只是劫掠后便离去。这样，埃里温与大不里士之间的军路被打开，同年九月便得以进入大不里士。沙阿巴斯将于1603年夺回纳希切万。", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["德利·哈桑帕夏起义与以波斯尼亚贝勒贝伊区安抚", "144f3f2d"], "d": ["杰拉里首领卡拉亚兹吉·阿卜杜勒哈利姆于1602年去世后接掌运动的其弟德利·哈桑，利用持续的奥地利战争给杰拉里团体带来的行动自由，侵入屈塔希亚并向阿菲永卡拉希萨尔进军。在国家同时应付奥地利和伊朗战线的这一时期，问题以“和解”方式得到解决：给予德利·哈桑帕夏衔和波斯尼亚贝勒贝伊区，起义运动于1603年正式终结。", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["俄军攻占卡西莫夫城，乌拉兹·穆罕默德汗", "b3f0bd34"], "d": ["作为俄国动乱时代（斯穆塔）的反映，俄军围攻并攻占了卡西莫夫城，居民大多被杀。汗国首领乌拉兹·穆罕默德因支持伪德米特里二世而成为目标；次年（1610年），他本人也在一场阴谋中被杀。", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["亚速城堡丧失给顿河哥萨克", "ba068b2f"], "d": ["顿河哥萨克于1637年4月21日围攻亚速城堡，两个月后将其攻占；作为黑海东北门户和顿河贸易锁钥的这座城堡，首次脱离奥斯曼之手。据TDV伊斯兰百科全书的亚速条目，哥萨克于1637年攻占城堡，1641年顶住了德利·侯赛因帕夏指挥的持续三个月的大围攻，直到1642年克里米亚汗穆罕默德·吉莱到来才撤出城堡。国家当时正忙于巴格达战线；城堡未能据守五年，是黑海作为“奥斯曼之湖”地位的第一道裂缝。", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["利姆诺斯与萨莫色雷斯的收复", "c445553b"], "d": ["1657年8月31日博兹贾阿达被解放之后，柯普吕律·穆罕默德帕夏把舰队引向北方，收复了威尼斯占据十六个月的利姆诺斯和萨莫色雷斯。据TDV伊斯兰百科全书的利姆诺斯条目，该岛于1656年7月落入威尼斯之手，于1657年11月被收回。这样，达达尼尔海峡口的威尼斯封锁被彻底打破，伊斯坦布尔的粮食通道重新得到保障；这是大维齐尔以非常权限上任的第一年最具体的收获。", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["克宁丧失给威尼斯——166年的达尔马提亚边境城堡陷落", "252406b7"], "d": ["1683年维也纳溃败之后，在多线展开的战争中威尼斯军队向达尔马提亚内陆推进。被达尔马提亚总督杰罗拉莫·科尔纳罗围攻的克宁，经十二天围困后由贝勒贝伊穆罕默德帕夏交出。克宁是1522年加齐·胡斯雷夫贝伊征服、在奥斯曼手中保留166年的达尔马提亚边境线的关键城堡；它的丧失使该地区在很大程度上向威尼斯敞开。", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["巴士拉自伊朗占领下收回", "5b10c5c1"], "d": ["1776年被克里姆汗·赞德之弟萨迪克汗攻占的巴士拉，在克里姆汗于1779年3月2日去世后伊朗爆发王位之争时被撤空；萨迪克汗以觊觎王位的名义返回伊朗。该城短暂留在穆坦非克部落手中之后，重新归入奥斯曼统治。从设拉子返回的前穆特塞利姆苏莱曼阿加，请求巴士拉总督之职，并以大苏莱曼帕夏之名成为巴士拉、巴格达和舍赫里佐尔的总督。海湾贸易回到奥斯曼控制之下；占领期间，贸易的一部分转移到了科威特，自1778年起沙漠邮路也从科威特发出。", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["帖木儿沙去世，扎曼沙登基（杜兰尼王朝）", "c3effdb2"], "d": ["随着二十多年来在国内巩固国家的帖木儿沙去世，坎大哈—赫拉特—喀布尔的总督三兄弟为王位而争执；控制首都的喀布尔总督扎曼沙于1793年5月20日成为沙阿。这次继承危机实际上是王朝分裂进程的开端。", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa——夏威夷传统禁忌制度的废除", "0b10e1d8"], "d": ["卡美哈梅哈一世去世六个月后，新国王利霍利霍在其母卡阿胡马努的支持下，故意违反了男女分食禁令（ʻaikapu）。这一被称为“ʻAi Noa”（自由进食）的举动正式终结了传统的禁忌（kapu）宗教—法律制度；岛上的旧神庙（heiau）不久被拆毁。这是西方传教士到来（1820年）之前最大的宗教—政治断裂。", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["《伦敦议定书》——承认希腊独立", "4c7b4b72"], "d": ["英国、法国和俄国在伦敦签订的议定书，超越《埃迪尔内条约》所设想的自治，承认希腊为独立国家。条款：摩里亚半岛、阿提卡和埃维亚及基克拉泽斯群岛留给新国家；边界划在阿尔塔—沃洛斯一线；决定向奥斯曼国家支付赔偿；国家的政体被确定为“独立君主国”。这是从帝国分离出去的第一个独立国家，并为其后巴尔干各国独立确立了法律范例。通过《伦敦议定书》得到独立承认的希腊，包括了基克拉泽斯群岛（纳克索斯、伊斯滕迪尔、圣托里尼、帕罗斯、安蒂帕罗斯、锡罗斯、米科诺斯等）。", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["阿卜杜拉·本·拉希德夺取哈伊勒酋长国——沙姆马尔（拉希德）王朝的建立", "fb513b8a"], "d": ["随着1818年穆罕默德·阿里帕夏的军队攻陷迪里耶，沙马尔山地区脱离沙特统治，酋长国留在伊本·阿里家族手中。支持重建奥斯曼统治的阿卜杜拉·本·拉希德，与其弟乌拜德一起对伊本·阿里家族展开的斗争于1835年获胜，夺取了哈伊勒酋长国并建立了拉希德王朝的统治。", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["夏威夷首部成文宪法颁布", "401a8a1d"], "d": ["王国首部完整成文宪法颁布；这份限制国王权力、设立代议制议会的文件，使夏威夷变成了君主立宪国。", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["刺刀宪法——卡拉考阿国王的权力被削减", "4953363b"], "d": ["一支武装民兵团体威胁国王卡拉考阿，迫使他签署一部大幅削减王国权力的新宪法；该文件被称为“刺刀宪法”（Bayonet Constitution），使王位实际上落入白人移民精英的控制之下。", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["乔治·图普一世去世，乔治·图普二世登基（汤加）", "b56e2b32"], "d": ["随着创建者国王乔治·图普一世去世，其曾孙乔治·图普二世继位；加冕典礼于1893年3月17日在努库阿洛法举行。", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["新西兰成为第一个给予妇女选举权的自治国家", "0d277cde"], "d": ["凭总督格拉斯哥勋爵签署的新选举法，新西兰成为世界上第一个在议会选举中给予妇女投票权的自治国家。", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["夏威夷共和国宣布成立", "4346bd5d"], "d": ["1893年推翻女王利留卡拉尼的阴谋者把临时政府变成了正式的共和国；桑福德·多尔被宣布为总统。这一过渡政权持续到1898年美国吞并。", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["新西兰疆界扩展至库克群岛和纽埃", "d0370a33"], "d": ["新西兰的疆界被扩展到包括库克群岛（拉罗汤加、艾图塔基及南部诸岛和北库克群岛）和纽埃；这些岛屿成为隶属新西兰的领地。", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["乔治·图普二世去世，萨洛特·图普三世登基（汤加）", "a3084f3b"], "d": ["乔治·图普二世死于肺结核；其十八岁的女儿萨洛特次日被宣布为女王，加冕典礼于1918年10月11日举行。", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["花剌子模人民共和国宣布成立", "0a6b79f9"], "d": ["1917年十月革命之后，希瓦汗被推翻，花剌子模人民共和国宣布成立。", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["《色佛尔条约》——帝国的瓜分文本", "64980d7b"], "d": ["奥斯曼政府与协约国签订的、实际上清算帝国的文本。条款：东色雷斯和伊兹密尔地区划归希腊；在东安纳托利亚设想建立独立的亚美尼亚和自治的库尔德斯坦；叙利亚作为委任统治地留给法国，伊拉克和巴勒斯坦留给英国；海峡移交国际委员会；军队缩减到50700人，治外法权恢复，财政交由协约国监督。安卡拉的大国民议会根本不承认该条约，并宣布签署者为叛国者；文本未生效，1923年被洛桑取代。这就是它在地图上没有对应的原因——《色佛尔条约》在法律上从未实施。", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["红军进入布哈拉城——末代埃米尔阿利姆汗被赶下王位", "f8f5bfcf"], "d": ["红军于1920年9月2日进入布哈拉城，末代曼吉特王朝埃米尔阿利姆汗被赶下王位。埃米尔退往该国东部的杜尚别，半年间自那里指挥对苏维埃的斗争；红军于1921年2月21日攻占杜尚别，埃米尔再向东并从那里逃往阿富汗。汗国于1920年10月6日被正式废除（见布哈拉人民苏维埃共和国）。", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["布哈拉人民苏维埃共和国宣布成立", "ef579627"], "d": ["红军于1920年8月28至31日推翻布哈拉埃米尔国并迫使埃米尔阿利姆汗逃往东布哈拉之后，在费伊祖拉·霍贾耶夫领导下，布哈拉人民苏维埃共和国宣布成立。", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["唐努图瓦人民共和国宣布独立", "8710ea3d"], "d": ["在图瓦人民革命党领导下宣布独立；第一部宪法的第一条指出，国家“在国际关系中处于苏维埃俄国的保护之下”行事。通过这一事件，克孜勒（别洛察尔斯克，唐努图瓦）转归唐努图瓦人民共和国。", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["布哈拉人民苏维埃共和国新宪法通过", "fb17bf39"], "d": ["与俄国1918年宪法相反，一部允许土地／生产资料私有并给予非无产者以选举权的新宪法获得通过（被推翻的埃米尔之亲属和大地主除外）。", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["改组为花剌子模苏维埃社会主义共和国", "14a1d26f"], "d": ["该国更改了名称和地位，成为花剌子模苏维埃社会主义共和国；行政—法律结构依据苏维埃体制重新安排。", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["唐努图瓦政府实际开始工作", "22ea1516"], "d": ["1922年2月首次党的会议之后组成的政府实际开始工作。", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["唐努图瓦首届大呼拉尔召开", "80fe15f2"], "d": ["国家首届大呼拉尔（人民议会）召开；这是国家制度化进程中的第一次大型代表性会议。", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["花剌子模苏维埃共和国与布哈拉人民苏维埃共和国因民族划界而终结——乌兹别克和土库曼苏维埃共和国的建立", "e8c8ab4f"], "d": ["依据苏联“民族—领土划界”（natsionalno-territorialnoe razmezhevanie）的决定，花剌子模苏维埃社会主义共和国和布哈拉人民苏维埃共和国被废除；其领土在新建的乌兹别克和土库曼苏维埃社会主义共和国之间分配（希瓦以东划给乌兹别克，以西划给土库曼）。TDV的 `harizm` 条目：“1924年，希瓦汗国的东部被划归乌兹别克苏维埃社会主义共和国，西部被划归土库曼苏维埃社会主义共和国。”——仅给出年份。", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["阿拉尼亚卖给马穆鲁克苏丹巴尔斯贝", "c8bd35f2"], "d": ["1293年被卡拉曼奥卢·梅杰迪丁·马哈茂德贝伊夺取的阿拉尼亚，已成为由卡拉曼家族一支统治的独立侯国；伊本·白图泰记载1333年的统治者是卡拉曼奥卢·优素福贝伊。卡拉曼·本·萨夫吉贝伊于1427年以五千金币的价格把该城卖给马穆鲁克苏丹巴尔斯贝，阿拉尼亚归入马穆鲁克统治。地中海的这个关键港口，由此成为奥斯曼南下道路上马穆鲁克手中的障碍；1471年盖迪克·艾哈迈德帕夏围攻时，末代贝伊克尔奇·阿尔斯兰交出了该城。", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["塔巴尔卡自热那亚人手中夺取——洛梅利尼珊瑚特许权的终结", "b1f33eb5"], "d": ["查理五世于1544年与突尼斯贝伊签订条约之后，热那亚的洛梅利尼家族定居于塔巴尔卡岛，两百年间一直掌握珊瑚特许权；该岛一直是奥斯曼突尼斯中央的一个基督徒贸易据点。侯赛因王朝的阿里帕夏在得知该家族试图处置该岛的企图后派兵前往，于1741年6月12日占领该岛；约一千五百名基督徒被迁往突尼斯。塔巴尔卡此后归入突尼斯军团的管理。", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["金字塔战役与法军占领开罗", "3ddd6b96"], "d": ["拿破仑从亚历山大港沿尼罗河南进，于1798年7月21日在吉萨对面的因巴巴迎战穆拉德贝伊的马木留克骑兵。方阵队形的法国步兵击破了骑兵冲锋；马木留克军队溃散，开罗两天后未经抵抗投降。穆拉德贝伊退往上埃及，易卜拉欣贝伊退往叙利亚。法国人在开罗建立了迪万，试图通过乌理玛来进行管理；1798年10月和1800年3月爆发了两次开罗大起义。", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["拿破仑围攻阿卡——叙利亚远征受阻", "d2a947ad"], "d": ["为打散奥斯曼为夺回埃及而准备的军队，拿破仑于1799年初进军叙利亚；2月18日攻占阿里什，3月攻占雅法，并于1799年3月18日围攻阿卡。杰扎尔·艾哈迈德帕夏的防御和英国海军上将西德尼·史密斯自海上的支援，使围攻两个月来未能得手；由于攻城炮在海上被缴获，城墙未能攻破。拿破仑于5月撤退，这次失败成为法国占领的最高点。", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["埃米尔阿卜杜勒卡迪尔国家的建立——西阿尔及利亚抵抗的集中化", "9e482383"], "d": ["阿尔及尔陷落之后分散的抵抗，聚集在卡迪里教团谢赫穆希丁之子年轻的阿卜杜勒卡迪尔周围；1832年11月22日，在穆阿斯卡尔附近，部落首领们以“信士的长官”之名向他效忠。他建立的结构并非部落联盟，而是一个正规国家：有铸币厂、火药作坊、税收制度，并在塔格登普特设有首都。法国通过1837年的塔夫纳条约正式承认其统治。阿卜杜勒卡迪尔所依附的不是奥斯曼，而是摩洛哥苏丹阿卜杜拉赫曼的宗主权；也就是说，这些土地在1832年之后不属奥斯曼臣属。他于1847年12月23日投降，奥斯曼国家同年也宣布其对阿尔及利亚的权利终结。", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["君士坦丁的陷落——东阿尔及利亚贝伊国的终结", "159fed36"], "d": ["1830年阿尔及尔陷落之后，东部贝勒贝伊区并未瓦解：末代贝伊艾哈迈德在君士坦丁继续自己的统治，并宣布以奥斯曼的名义行事。法国人1836年的第一次远征以溃败告终；第二次远征于1837年10月6日围攻该城，指挥官达姆雷蒙10月12日被炮火击毙，10月13日城墙被突破，该城经逐街战斗被攻占。艾哈迈德贝伊退入山区，直到1848年才投降。这一日期是三百年奥斯曼—土耳其统治在阿尔及利亚东部的实际终结。", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["塔卡地区的征服与卡萨拉的建立", "cc3e0631"], "d": ["苏丹总督艾哈迈德帕夏·艾布·维丹于1840年把阿特巴拉河与加什河之间的塔卡地区并入埃及统治，并把卡萨拉城建为军营。该城成为控制森纳尔与萨瓦金之间商队道路及阿比西尼亚边境地带的穆迪里耶中心。", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["法国占领穆阿斯卡尔（Mascara）——阿卜杜勒卡迪尔都城的丧失", "bd363c05"], "d": ["随着比若1841年出任总督，法国战略发生了变化：不再固守海岸，而是逐一占领内陆城市。从瓦赫兰、穆斯塔加奈姆和梅迪亚出动的机动纵队攻占了阿卜杜勒卡迪尔正规国家的各个中心；拥有铸币厂、火药作坊和粮仓、堪称真正首都的穆阿斯卡尔是其中最重要的一个。埃米尔此后放弃建立固定中心，把军队变成了称为“斯马拉”的游牧营地。", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["谢利夫河谷与特内斯的占领——奥尔良斯维尔的建立", "e1eeeb68"], "d": ["为了追击阿卜杜勒卡迪尔，法国人于1843年4月在谢利夫河谷中部建立了名为奥尔良斯维尔的新城；同年沿海的特内斯港也被占领。这样，阿尔及尔与瓦赫兰之间的内陆走廊归入法国控制，达赫拉山区的抵抗被包围。同年5月16日，阿卜杜勒卡迪尔的游牧营地“斯马拉”被偶然发现并被击散。", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["西迪贝勒阿巴斯设防营地的建立", "fb33ec29"], "d": ["比若于1843年6月12日命令贝多将军在西迪贝勒阿巴斯建立一个有壕沟和围墙的设防营地；工程于6月18日开始，同年11月外籍军团的一个营进驻此处。该营地成为控制瓦赫兰与特莱姆森之间内陆平原的长期基地。", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["奈德鲁迈及摩洛哥边境地带归入法国控制", "61d821f3"], "d": ["阿卜杜勒卡迪尔于1843年退入摩洛哥之后，特莱姆森西北的奈德鲁迈和特拉拉沿岸归入法国控制。1844年8月14日的伊斯利战役使摩洛哥军队溃败，两国之间的边界通过1845年3月18日的拉拉·马格尼亚协定划定；奈德鲁迈留在这条线的阿尔及利亚一侧。", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["拉古阿特（Laghouat）的陷落——撒哈拉之门的打开", "b161b32c"], "d": ["佩利西耶将军率六千人的部队于1852年11月21日围攻拉古阿特，12月4日该城在血腥的强攻中陷落。拉古阿特是把守泰勒与撒哈拉之间通道的绿洲城市；它的陷落使法国的推进向沙漠商队道路敞开，并为姆扎布联盟一年之内被课以赋税扫清了道路。", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["博戈斯（凯伦）地区并入埃及", "b2ab83ce"], "d": ["赫迪夫伊斯梅尔在红海西岸建立的“东苏丹与红海沿岸”省的总督维尔纳·蒙青格帕夏，于1872年把比伦人居住的博戈斯地区及其中心凯伦并入埃及。这是埃及对阿比西尼亚高原边缘最持久的推进，并引发了与阿比西尼亚长达十二年的边界争端。", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["达尔富尔苏丹国并入埃及——祖拜尔帕夏进入法希尔", "f41268ed"], "d": ["凭借象牙和奴隶贸易壮大的祖拜尔·拉赫马帕夏，率领配备雷明顿步枪的部队，于1874年10月25日在梅内瓦希击溃富尔军队；苏丹易卜拉欣在战斗中阵亡。祖拜尔于11月2日未经战斗进入法希尔，自1603年起延续的凯拉王朝的统治实际终结。达尔富尔由此并入卡瓦拉埃及的苏丹各省；但凯拉家族在山区的抵抗持续到1891年。", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["姆扎布绿洲（加尔达亚）的并入", "9372959f"], "d": ["姆扎布的伊巴德派城市于1852年同意向法国纳税，但保留了内部管理；三十年后的1882年，该地区被直接并入法国领土，加尔达亚划归军事管理。这样，北撒哈拉最后的自治地带在法律上也告终结。", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["亚历山大港遭炮击与英军登陆", "18d57bf8"], "d": ["当乌拉比帕夏领导的军官运动控制了赫迪夫后，英国以苏伊士航道安全为借口进行干预。西摩海军上将的舰队于1882年7月11至12日炮击亚历山大港的海岸炮台；城中发生火灾和劫掠之后，7月15日英军登陆。奥斯曼国家未能阻止在其法律上拥有宗主权的行省中进行的这一行动，对于参与干预的邀请也未予回应。这样，将持续三十二年的占领迈出了第一步。", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["泰勒凯比尔战役——乌拉比军队的溃散", "8e38fecf"], "d": ["沃尔斯利把部队经苏伊士运河运到伊斯梅利亚登陆并穿越沙漠行军，于1882年9月13日拂晓突袭了泰勒凯比尔的埃及战壕；战斗一小时便结束。乌拉比次日投降，英国骑兵当天进入开罗。此后埃及的财政、军事和外交实际上转入英国控制；奥斯曼宗主权在法律上则持续到1914年。", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["马尔萨（拉马尔萨）协定——突尼斯保护的完成", "71338640"], "d": ["1881年5月12日的巴尔杜（卡斯鲁萨伊德）条约把突尼斯的外交留给法国，但把内政留给贝伊；两年后于1883年6月8日签订的马尔萨协定又把财政和行政改革交由法国控制，从而完成了保护。奥斯曼国家继续坚持对突尼斯的宗主权主张，从不承认这一占领，但无法采取实际的反制措施。这样，自1574年起为奥斯曼军团的突尼斯正式归入法国保护。", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["舍伊坎溃败——希克斯帕夏军队被歼", "a0e08986"], "d": ["从开罗派出、指挥约一万人埃及部队的退役英国军官希克斯帕夏，在科尔多凡沙漠中无水无向导地前进，于1883年11月5日在舍伊坎被马赫迪军队包围，军队几乎被全部歼灭。这次溃败折断了埃及在苏丹统治的脊梁：一个月内，达尔富尔和巴赫尔加扎勒投降，整个科尔多凡转入马赫迪之手。通往喀土穆陷落的道路由此开始。", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["达尔富尔转入马赫迪军队之手——斯拉廷帕夏的投降", "6d8992d4"], "d": ["达尔富尔总督斯拉廷帕夏，自1882年起一直在应对里泽加特部落的马赫迪式起义；他认为士兵的失败归咎于自己的基督徒身份，因此于1883年公开成为穆斯林，取名阿卜杜勒卡迪尔。1883年11月希克斯帕夏的军队在科尔多凡被消灭之后，抵抗已失去意义，他于1883年12月23日向埃米尔马迪博投降。达尔富尔的小型埃及哨所不久也步其后尘；十年的土耳其—埃及统治告终。通过这一事件，杰贝勒梅拉（达尔富尔）转入马赫迪国家的统治。", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["泽拉与索马里海岸转入英国管辖", "1d649502"], "d": ["当马赫迪起义使埃及在苏丹和红海的守军崩溃时，开罗被迫撤出阿比西尼亚海岸的偏远哨所。亚丁的英国当局于1884年在泽拉和柏培拉登陆；次年与索马里部落首领签订保护条约，建立了英属索马里兰。自1559年起隶属哈巴沙省的泽拉由此丧失。", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["法希尔守军向马赫迪军投降", "68f0760d"], "d": ["在斯拉廷于1883年12月23日投降之后，法希尔城堡中的埃及守军仍在抵抗。在七天的围攻中失去水井的守军，于1884年1月15日投降；武器被放下，城堡转入马赫迪军之手。", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["《赫维特（阿杜瓦）条约》——博戈斯让给阿比西尼亚", "0de1b701"], "d": ["当马赫迪起义围困埃及在苏丹的守军时，英国为获取阿比西尼亚的帮助，于1884年6月3日在阿杜瓦与约翰尼斯四世签订条约。条约第二条把博戈斯归还阿比西尼亚，作为交换，阿比西尼亚使被围守军经马萨瓦撤出。凯伦由此脱离十二年的埃及统治；五年后该地区将并入意大利厄立特里亚。", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["栋古拉的收复——尼罗河沿线远征的开始", "f63aa14f"], "d": ["意大利人在阿杜瓦战败之后，英国令埃及军队在基钦纳指挥下沿尼罗河向南进军。随着铁路在沙漠中推进，补给问题得到解决，栋古拉省于1896年9月23日被收复。十一年的马赫迪统治在此终结；远征又持续两年，直到抵达恩图曼。", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["恩图曼战役——马赫迪国家的覆灭", "28dff7b2"], "d": ["基钦纳配备火炮和机枪的英—埃军队，于1898年9月2日在恩图曼城前数小时内击溃了哈里发阿卜杜拉·塔阿伊希的军队。次日进入喀土穆，在十三年前戈登被杀的宫殿中升起了旗帜。马赫迪国家的都城陷落；哈里发于1899年底在追击行动中被杀。实际统治在此日易手——而1899年1月19日则是确立管理法律框架的条约。随着马赫迪国家的这次失败，达尔富尔（法希尔、尼亚拉、杰宁纳、库图姆等）转入阿里·迪纳尔重建的达尔富尔苏丹国。", "ad27827a"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["共管条约——苏丹的英—埃共管", "8033c688"], "d": ["恩图曼之后四个月在开罗签订的条约，把苏丹以“英—埃苏丹”之名置于两国共管之下：两面旗帜将同时升起，总督由赫迪夫在英国同意下任命。在实践中，管理完全掌握在英国人手中。奥斯曼国家以苏丹之权经埃及属于自己为由，没有成为条约的一方，也不予承认；但实际上被排除在外。通过这一条约，北纬22度线以南的苏丹土地（栋古拉、喀土穆、森纳尔、科尔多凡、萨瓦金海岸等）转入英—埃共管（英—埃苏丹）。", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["意大利在托布鲁克登陆——的黎波里塔尼亚的首次占领", "44780018"], "d": ["意大利于1911年9月29日宣战，其舰队于9月25至26日封锁了海岸。首次陆上行动于10月8日在托布鲁克展开：奥斯曼小股守军退往内陆，该港口未经战斗被占领。托布鲁克是离埃及边界最近的奥斯曼港口；其陷落打开了拜尔卡的东翼，并便利了意大利军队沿海岸向西进军。", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["的黎波里城向意大利人投降", "785091ad"], "d": ["的黎波里在三天炮击后于1911年10月9日投降。奥斯曼军队没有保卫该城，而是退往阿齐齐耶和加里扬，选择在内陆组织抵抗；恩维尔和穆斯塔法·凯末尔两位贝伊参加的这次抵抗，把意大利人囚禁在海岸带直到战争结束。也就是说，该城虽然陷落，行省内陆仍在奥斯曼控制之下。", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["德尔纳因意大利登陆而丧失", "f014c741"], "d": ["继托布鲁克之后，轮到拜尔卡的第二大港口德尔纳；该城于1911年10月16日被占领。德尔纳周边的高原，是赛努西教团最密集的地区，应谢赫艾哈迈德·谢里夫的圣战号召聚集起来的圣战者，把意大利人围困在港口周围。占领仅限于城市，从未扩展到腹地。", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["意大利在班加西登陆——拜尔卡桑贾克中心的丧失", "f9183c40"], "d": ["拜尔卡的中心班加西，于1911年10月21日以沿海第四次也是最重要的一次登陆而被占领。这样，意大利在宣战三周之后，就控制了的黎波里塔尼亚省所有主要港口（的黎波里、托布鲁克、德尔纳、班加西）；但没能深入其中任何一个的腹地。战争剩下的一年，是从海岸这四点向内地进行的毫无结果的进攻中度过的。", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["意大利单方面的吞并法令", "cfe3f9c2"], "d": ["意大利在战争持续期间，于1911年11月5日颁布法令，宣布吞并的黎波里塔尼亚和拜尔卡。奥斯曼国家不予承认，战争又持续了一年；吞并直到1912年10月18日《乌希条约》才获得法律效力。因此该法令并不改变地图上奥斯曼的颜色——法律上的所有权到1912年为止仍属奥斯曼，意大利的控制以阴影线的占领来表示。", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["攻取克普吕希萨尔与筹建耶尼谢希尔", "39abff03"], "d": ["通过攻陷布尔萨与伊兹尼克之间的隘口城堡，奠定了可围困两城的前进指挥部的基础。", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["耶尼谢希尔的建立", "d3275837"], "d": ["为指挥布尔萨与伊兹尼克的围攻，建立了第一个正规的奥斯曼驻军—居民点；奥尔汗加齐出生于此。", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["伊兹尼克的首次围攻与马尔马拉吉克的征服", "cdca2349"], "d": ["伊兹尼克首次被围而未能攻克（最终征服在1331年）；其附近的马尔马拉吉克城堡此时被攻取。", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["加泰罗尼亚军团远征安纳托利亚", "4fd940d5"], "d": ["拜占庭为阻止突厥人推进而雇佣的加泰罗尼亚军团虽取得暂时的成功，却未能持久；他们撤走后，边境诸侯国的推进加快。", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["科塞·米哈尔皈依伊斯兰并归附奥斯曼", "ca0d86e1"], "d": ["哈尔曼卡亚的塔克福尔科塞·米哈尔连同其城堡和部众皈依伊斯兰，归附奥斯曼加齐；成为第一位出身拜占庭的奥斯曼指挥官。", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["奥尔汗贝伊实际接掌政务", "6dadbefc"], "d": ["由于奥斯曼加齐年迈多病，布尔萨围攻及各次出征的实际指挥与管理转到其子奥尔汗贝伊手中（正式登基是在1326年）。", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["攻占穆达尼亚", "0a623368"], "d": ["攻占布尔萨的港口穆达尼亚，该城与海洋的联系被切断；围攻布尔萨进入扼杀阶段。", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["阿克亚泽与伊姆拉勒岛的征服", "d041b0c8"], "d": ["萨卡里亚河以北的阿克亚泽被攻取；随着伊姆拉勒岛的夺取，奥斯曼人首次与马尔马拉岛相邻。", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["盖姆利克（基奥斯）与阿尔穆特卢的征服", "682d3bac"], "d": ["布尔萨最后的海上联系也被切断，使该城为1326年的投降做好了准备。", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["阿克恰·科贾攻占坎德勒及其周边", "341bb97e"], "d": ["奥尔汗加齐的边境贝伊之一阿克恰·科贾，从萨潘贾湖以西的营地对伊兹米特一带发动袭掠，约1326年攻占了坎德勒及其周围。伊兹米特当时仍在拜占庭手中；该城直到1337年才陷落。", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["亚洛瓦与卡拉穆尔塞尔的并入", "133cb07a"], "d": ["伊兹米特湾南岸的亚洛瓦及其周边于这一年落入突厥人之手；沿海地带被奥尔汗贝伊作为蒂马尔授予卡拉穆尔塞尔加齐。", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["阿克恰·科贾攻取艾多斯与萨曼德拉城堡", "ce4daa8a"], "d": ["坎德勒被攻占后，阿克恰·科贾与科努拉尔普和加齐阿卜杜拉赫曼一起攻取卡尔塔尔附近的艾多斯城堡，随后又攻取其北面的萨曼德拉城堡；萨曼德拉地区作为私产授予了他。阿克恰·科贾于1328年死于坎德勒附近；边境侯位与该地区转给了王子穆拉德。", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["奥斯曼—艾登—萨鲁汗联盟", "9df6bb74"], "d": ["三个侯国联手对付拜占庭；艾登奥卢乌穆尔贝伊的舰队通过对色雷斯海岸的袭掠，从第二条战线消耗拜占庭。", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["奥尔汗·加齐与狄奥多拉联姻：拜占庭同盟", "9b67a590"], "d": ["在拜占庭的王位斗争中支持坎塔库泽诺斯的奥尔汗·加齐，娶了他的女儿狄奥多拉；这一同盟使奥斯曼军队得以熟悉鲁米利。", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["安卡拉的攻取", "49bf1f6d"], "d": ["由阿希统治的安卡拉进入奥斯曼治下；通往中安纳托利亚的道路被打开。同日并入的其他地方：锡夫里希萨尔、昌克勒。", "eec5d13e"]}
});
